/* 平成20年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h20.committeeSessions.push(...[{"id":"h20-20080311-3","meetingId":"h20-c-budget","date":"2008年3月11日","dateIso":"2008-03-11","committee":"予算特別委員会","time":"午後６時０８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を175件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２０年度品川区一般会計予算","agenda":"平成２０年度品川区一般会計予算","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"私のほうは、２８５ページ、子ども達による基本構想策定記念公園づくり、国文学研究資料館跡地の公園の暫定整備工事の２点を伺いたいと思います。そして、２点目に、検討委託の中で、予算ということで、１,４２０万円が計上されていまして、結構な金額がこの検討段階で計上されているので、まず主な内訳を伺えればと思います。３つ目に、どうしても関心事になるので伺いますが、公園の場所はどこだろう。","respondent":"松代管理工事課長","answer":"今後少し時間をかけまして、この夢のある基本構想策定記念公園にふさわしいような場所、またそれにふさわしい面積、そういったものも今後検討する中で、検討していければというように考えているところです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"こういう、とてもわくわくする、本当にキーワードで言えば夢だと思います。夢のある企画が今回出てきた経緯というのは、どなたの思いつきといいますか、どなたの発想なのかなとか、こういう自分の、それぞれの区民の人の思いが形になるような、こういう取り組みというのはとても望ましいと思いますが、その辺の経緯を伺いたいと思います。","respondent":"松代管理工事課長","answer":"そういったものをぜひ取り入れて、今回、策定に当たっての記念公園にしたいと、こういうように思ってあります。今後もそういった、子どもたちの夢が極力実現できるようなことを中心に置きまして、進めていきたいと考えているところです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そういう中で、まず、暫定整備の中で、歩道の整備だとか要望があったと思いますが、そういう一緒になって取り組んだ、そういったことがどのように反映されているかどうか、まず伺いたいのと、もう一点は、今後この跡地の利用計画は、何年かかけてというお話もありましたが、地域の方はどのように参加していくのか、地域の意向をどのように伺っていくのか、タイムスケジュール等、今わかる範囲でいいので。","respondent":"松代管理工事課長","answer":"その間に、地域の皆様と今後の将来の公園のあり方、公園の整備方針等を今私ども定めておりますので、そういったものに沿って意見を集約しながら、一緒に将来計画をつくっていければと、このように考えているところです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"金野委員","kind":"質問","question":"私のほうからは、２６５ページの交通安全対策費についてお伺いします。この間の第１回定例会でも、私、この交通安全対策についてお伺いしてまいりましたけれども、そのときに普及啓発の取り組みに対して、このようなご答弁をいただきました。「参加体験型の交通安全教室を警察と協力して実施しています」ということをご答弁いただきました。開催時期と参加人数をまず教えてください。","respondent":"松嶋交通安全担当課長","answer":"例えばトラックの左折巻き込みの部分だとか、シートベルトコンビサーはもちろん、それと、自動車が５０kmで来るとこのように来るんですよという、そういったものも体験として、いろいろなものを実施しています。なお、これの主催につきましては、品川区で主催をしております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"金野委員","kind":"質問","question":"高齢者交通安全モデル地区交通安全講習会というほうも、教えてください。","respondent":"松嶋交通安全担当課長","answer":"もちろんこれも警察のほうの協力を得て、実施をしています。開催時期につきましては、大体、何月ごろということは決まっておりませんけれども、例えば昨年でいえば、荏原のモデル地区でやったのは、これも１１月だったと記憶しております。","voiceIndex":15,"id":"exchange-005"},{"speaker":"金野委員","kind":"質問","question":"今のは高齢者の方ということで、ここに記載をされているものを伺ったんですが、そのほか、学校関係、また地域、そして高齢者だけではなくて、あらゆる対象の方等々、普及啓発活動というか、そういうのをされているかと思うんですが、特に自転車に特化したものという、そういうものはあるんでしょうか。","respondent":"松嶋交通安全担当課長","answer":"安全教室をやっていただけないかと。そういったときに、区のほうから現場に赴いて、現場のほうでこれも体験型の自転車教室を実施しています。","voiceIndex":17,"id":"exchange-006"},{"speaker":"金野委員","kind":"質問","question":"もう一つお聞きしたいのが、ここに記載されています黄色い帽子１,３００個、「交通しながわ」、それから幼稚園の交通安全の絵本、それぞれこれは多分配布をされたりする啓発活動のものだと思うんですが、その具体的な内容というんでしょうか、例えば「交通しながわ」の内容だとかも含めて、どのような配布対象者、また配布するタイミングなども教えてください。","respondent":"松嶋交通安全担当課長","answer":"黄色い帽子のほうから説明をいたします。黄色い帽子につきましては、黄色い帽子の協会というところがありまして、そこでおおむね毎年１,０００個、協力でいただいております。","voiceIndex":19,"id":"exchange-007"},{"speaker":"金野委員","kind":"質問","question":"それぞれご説明いただきまして、この啓発活動はいろいろとされているんだなというところとともに、学校関係では、幼稚園、保育園、小学校等でしてくださっているということなんですが、私立の学校、幼稚園ではどのような対応をされているのか、そちらはどうなんでしょうか。","respondent":"松嶋交通安全担当課長","answer":"幼稚園におきましては、先ほどお話ししましたけれども、こちらで出向いての交通安全教室、これにつきましては私立、公立関係なく、こちらで出向いて行っております。","voiceIndex":21,"id":"exchange-008"},{"speaker":"金野委員","kind":"質問","question":"それには自転車を利用される方のルール、またマナーを知らないでいるということと同時に、とても悪質な乗り方というんでしょうか。学校等で行っていただいている中で、例えばもっと年齢が高くなると、高校生などの乗り方が非常に目立ってくるわけですけれども、そういった高校生への交通安全指導、特に自転車の指導というところでは、どうなんでしょうか。","respondent":"松嶋交通安全担当課長","answer":"そういったものも当然各学校のほうに配布されると思いますので、それは教育の課程の中で実施していっていただきたいなと考えているところです。","voiceIndex":23,"id":"exchange-009"},{"speaker":"金野委員","kind":"質問・要望","question":"自転車教則ですが、先日も新聞、テレビ等で話題になりまして、子育て中のママたちから声が上がって、この自転車教則で、子どもを前と後ろに乗せた３人乗りは本当は禁止ということが、ママたちの要望によって、警察庁が認めていくような動きがあるというふうにも報じられていたんですけれども、そのことについても、生活者の視点に立つと自転車はなくてはならないもの。","respondent":"松嶋交通安全担当課長","answer":"これは、警視庁と区で共催でやるわけですけれども、これは当然教育委員会だとか学校のほうの協力を得ながら実施をします。","voiceIndex":25,"id":"exchange-010"},{"speaker":"金野委員","kind":"質問・要望","question":"今、具体的にということで、中学生の部でお話をいただいたんですが、スタントマンもいいと思うんですが、危険度に対しての周知というのはわかっていてやってしまうこの年代、それをどう指導していくかというところにかぎがあるかなと非常に思いますので、その点ひとつよろしくお願いしたいと思います。幼児用の自転車に限っては、私、何度も要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"菊地委員","kind":"質問","question":"住宅耐震化のほうを先に聞かせていただきますけれども、促進計画中間のまとめと、それから今年度の予算を見させていただいて、どうもよくわからない部分がありますので、耐震化率９０％の目標についての部分を中心にお聞かせ願いたいと思います。いろいろ読ませていただくと、自然更新で、８年間で３,９５２棟とあります。年間で約５００棟ぐらいでしょうか。","respondent":"片田建築課長","answer":"それともう一つ、今回の促進計画の耐震化支援の中で盛り込んでいる数値等々を含めて考えても、現行の数字どおりで推移したとすれば、概ね、理論値でいけば１８年ぐらいかかるだろうと、このように考えてあります。","voiceIndex":29,"id":"exchange-012"},{"speaker":"菊地委員","kind":"質問","question":"特定建築物の棟数もお聞きをしたものですから、後でお答えを願えればと思います。今の数字をお聞きすると、９０％の目標を達成するぞ、こういう体制になり切れていないんだろうなというふうに思うんです。","respondent":"片田建築課長","answer":"それと、耐震化率の目標の件ですけれども、基本的には減災ということで、被害を半減するという考え方に立ち、国の方針が示されてございまして、その目標としては、かなり高い目標ですけれども、９０％という数値を示して、これを含めて区としても努力していきたいと。","voiceIndex":31,"id":"exchange-013"},{"speaker":"菊地委員","kind":"質問・要望","question":"昨年、補正で組まれて、とりあえずはこの制度を周知をするということが先行されるんだろうというのは私もわかるんですけれども、今年度からは本腰を入れて、９０％の目標に向かっていこうということになるわけですよね。非木造では２００棟。約１,３００棟の、単純に計算をすれば１,３００棟ぐらい必要になるわけですけれども、その辺の考え方をもう少し教えていただきたいなというふうに思います。","respondent":"片田建築課長","answer":"なかなか、お年寄りで難しいというようなところもありますけれども、基本的には９０％を目標とした理由については、行政だけではなくて、現況を区民の皆様もわかっていただきたいと。","voiceIndex":33,"id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"年次計画が、私、必要ではないかというところをお聞きしたので、その辺も後でお聞かせ願いたいと思うんですけれども、耐震化が進まない、こういう、理由としては幾つかあるんだと思うんです。国土交通省が出している、「調査と情報」という中で出されているのが、１つは費用負担の大変さ。これは共通するんだと思いますし、２つ目には生活面の煩わしさ。さきの質問とあわせてお願いします。","respondent":"片田建築課長","answer":"少なくとも区としては、情報の発信、あと区民にそういう現況を知り得ていただきたい、そういう流れの中でＰＲ活動、啓発活動を行いながら、目標に向けた努力をしていきたいと、このように考えてあります。","voiceIndex":35,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問・要望","question":"ですから、私、どうしてもそうした体制づくり、そのためには年次計画はどうしても必要だというふうに思います。最初に申し上げましたけれども、国が社会全体の国家的な緊急課題だと、このように位置づけをしたわけですから、もちろん国や東京都に求めるというのは必要だとは思いますよ。","respondent":"岩田まちづくり事業部長","answer":"先ほど、建築課長がお答えしましたけれども、区有施設とか公共施設であれば、向こう９年間で毎年これだけのものをやりますという年次計画を立てて、区民の皆様にお約束するということは、これは可能ですし、そういうふうにやるつもりでおります。","voiceIndex":37,"id":"exchange-016"},{"speaker":"稲川委員","kind":"質問","question":"私も昨年の本会議の一般質問でお伺いはしたのですが、平成１９年７月までの診断の件数が３８件ということでした。もしデータがあるのであれば、もうすぐ今年度は終わるので、平成１９年度、大体診断が何件あって、改修がどれぐらいあったのか、お答えください。","respondent":"片田建築課長","answer":"それと、あと改修ですけれども、昨年度は５件の予算を見込んで、すべて５件は改修支援ができたというような状況ですけれども、今年度は１５件の予算化の中で、現時点で１２件の申請が出てきてあります。なお、既に改修が終わったものについては９件ほどになってあります。","voiceIndex":40,"id":"exchange-017"},{"speaker":"稲川委員","kind":"質問","question":"今回、耐震診断助成、耐震改修工事助成、非常に、平成１９年度の予算書に書いてある以上に間口を広げて、木造、非木造、さまざまな形で前向きな予算づけというか、そういう形にはなっているんですが、この中に緊急輸送道路沿道建築物、これ、基本的に木造、一戸建てが１５０棟あって、診断をして、その中で改修するのが大体３０棟ぐらいかなという、そういう考えでいるんですけれども。","respondent":"片田建築課長","answer":"今後、区としてもそれに対しての考え方をきちんと整理をして、連携をとっていきたいと思ってありますので、ただ、東京都と区の役割がきちんと明確になった上での想定も考えて、頭出しとして、２件の改修を予定しておきたいということで示したものです。","voiceIndex":42,"id":"exchange-018"},{"speaker":"稲川委員","kind":"質問","question":"外れてしまうんですが、昨年の本会議での私の質問で、診断対象がどれぐらいありますかと言ったときに、その答えで、区長が２万４,０００戸あるというお答えもいただいておりますので、その辺、どういう関連があるのかということ。できればこの２万４,０００件の非木造と木造、どういう割り振りになっているか。ちょっと飛んでしまって申しわけないですが、お願いします。","respondent":"片田建築課長","answer":"それと、もう一つは、個別訪問ですけれども、実は今現在、２月中旬から補正予算で組ませていただいた個別訪問、おおむね予定上は１,６００軒ほど戸数を想定して、対象として行ってありますけれども、平成２０年度につきましては、今年やり残したいわゆる整備地域とか。","voiceIndex":44,"id":"exchange-019"},{"speaker":"稲川委員","kind":"意見","question":"それで、ホームページ、毎回、私、申し上げているんですが、品川区のホームページを見ますと、暮らしから都市、道路、公園、そしてまちづくりの支援の中に入っているんですが、これは、まだ平成１９年度中なので変わっていないという僕は思いでいるんですが、それを開くと、まだ木造住宅等耐震診断支援とか、そういう形で書いてあるんですが、これ、また、事業がこういう形になったときに、ホームページなど。","respondent":"片田建築課長","answer":"昨年、中間のまとめ等々でパブリックコメントを打ったところがありますので、そのパブリックコメントの公表結果のほうから引っ張っていかないと、逆に支援の内容とか、それが出てこないといったようなところが現況ありますので、その辺がわかりやすく。","voiceIndex":46,"id":"exchange-020"},{"speaker":"稲川委員","kind":"質問・要望","question":"２７５ページの踏切の件で、改良事業ということで書いてありますが、ご存じのように、３月２８日でしたか、東急の大井町線に急行が走るということで、今試験運転をしている中で、ちょっとデータだけ教えていただきたいんですが、大井町線で区道にある踏切の数を教えください。","respondent":"松代管理工事課長","answer":"東急電鉄大井町線、踏切が１１カ所あります。区内に１１カ所、交差するようなところがあります。","voiceIndex":48,"id":"exchange-021"},{"speaker":"稲川委員","kind":"意見","question":"まだ急行は試験運転をしているところなんですが、僕もあの辺、商店街に隣接している踏切もありますし、さまざまな形の中で、今後急行が走ったら、多分、開かずまではいかないと思うんですが、なかなか、試験走行しているときも、多分相互に入ってくると思うんですね。試験運転を見る限り。本当にそこが、人が集まったとき、非常に車の通りもある踏切もありますので、交通安全対策についてお願いします。","respondent":"阿部都市計画課長","answer":"踏切の解消につきましては、これはなかなか難しい面もありますけれども、今年度は下神明１号踏切の拡幅を予定してございまして、踏切対策については十分今後取り組んでまいりたいというふうに思っております。","voiceIndex":50,"id":"exchange-022"},{"speaker":"原委員","kind":"質問・要望","question":"五反田の件は後半にしまして、初めに百反歩道橋の件につきまして、平成１９年度３,０００万円で、平成２０年度５,３５０万円出ておりますが、この辺についてご説明をいただきたいのと、それから、都市再開発方針変更、これ、ポイントだけで結構なので、再開発方針の変更部分のポイントだけ、お教えいただければと思います。","respondent":"青木都市開発課長","answer":"平成２０年度以降ですけれども、今、平成１９年度の基本設計と、劣化調査等を踏まえまして、歩道橋につきましては今後、品鶴線、横須賀線が通っているところの法面を利用して階段やエレベーターを設置して、橋を架け替えようということで検討しております。","voiceIndex":54,"id":"exchange-023"},{"speaker":"原委員","kind":"質問","question":"、非常にわかりやすかったです。そうしましたら、五反田にぎわいゾーン関係で、私、きのうも質問させていただいたんですけれども、大崎のものづくり関係の施設がありますよね。私の持ち時間５分残しましたので、その辺をしっかりお願いできればと思います。","respondent":"青木都市開発課長","answer":"五反田にぎわいゾーンにつきまして、整備検討、調査したいということの動機、そもそも私どもの発端といたしましては、五反田駅周辺につきましては、戦後すぐから戦災復興の区画整理事業を行いまして、それが完了したのが昭和４０年代の初めです。","voiceIndex":56,"id":"exchange-024"},{"speaker":"武内委員","kind":"質問","question":"私は、２６５ページの交通安全対策費、それから、先ほどから重なりますけれども、２９３ページの住宅・建築物耐震化支援事業の２点、お伺いをします。それで、今の状況なんかをどのようにつかんでいらっしゃるか。いわゆる駐車違反が少なくなったのか。","respondent":"松嶋交通安全担当課長","answer":"それと、民間委託をしたことによっての警視庁内でのシフト、その関係につきましては、私のほうから答えるのは、はばかられる問題がありますので、回答を差し控えします。","voiceIndex":59,"id":"exchange-025"},{"speaker":"武内委員","kind":"質問","question":"そうすると、今、荷さばき場とか、二輪の駐輪場のお話も出たんですけれども、これもやはり都が中心となって導入した形になっていると思いますので、区は直接は関係ないわけですけれども、その中で二輪の駐輪場ですとか、また、荷さばき場なんかもしっかり都が補助金を出したりとか、そういう中で整備をするんだというような話も当初計画の中で出ていたような気もするんですけれども。","respondent":"松嶋交通安全担当課長","answer":"今回の法改正、施行に伴いまして、これは都のほうで実施は実施ですけれども、区としてもいろいろなこういった問題に対する、荷さばきだとか、二輪車に対する問題に対しては、これは都がやっているんだから関係ないという話ではごさいませんで。","voiceIndex":61,"id":"exchange-026"},{"speaker":"武内委員","kind":"質問","question":"いずれにしても、駐車違反が少なくなってくれば、いろいろ、例えば自転車道とか、自転車通行帯というんですかね、こういったものも設置しやすくなるのかなという、そういった面で言えば、しっかり、都道が中心になると思うんですけれども、そういうところで今駐車監視員の方がやっていただいて、それがどんどん減ってくれば、逆に今度そういう人たちも別のほうに回っていけるわけでしょうし。","respondent":"片田建築課長","answer":"現在、８町丁ということで、特に危険度が高い、これは平成１４年当時の防災都市づくり推進計画に基づくものですけれども、二葉二丁目、二葉三丁目および二葉四丁目、西品川二丁目、小山六丁目、旗の台四丁目、あと中延五、六丁目を対象に、連合町会のほうにもご説明した上で。","voiceIndex":63,"id":"exchange-027"},{"speaker":"武内委員","kind":"質問・要望","question":"少しでもそこでお知らせをして、また耐震診断、また耐震改修に結びついていかなければならないわけなんですけれども、かといって営業ベースで、営業的になってしまってもいけないとは思うんですけれども、ただ、その中で委託される業者には、例えば訪問件数だとか、耐震診断に結びついたとか、そういう、それがいいのか悪いのかもちょっとわかりませんけれども、報酬に見合ったインセンティブというんですか。","respondent":"片田建築課長","answer":"それと、回るに当たっては、２月５日以降でございましたけれども、概要版を１万部ほど刷りまして、全町会のほうに回覧をさせていただいて、その後、２月の前半ですけれども、各８町丁の連合町会の会議に出させていただいて。","voiceIndex":65,"id":"exchange-028"},{"speaker":"武内委員","kind":"質問・要望","question":"今後の、来年度はこういう形で行くと思うんですけれども、今後そういう方向性をちょっと教えていただきたいのと、あと、先ほど菊地委員からもありましたけれども、目標を掲げてやっていく中で、達成していくには、ある程度、区もここまでやるんだけれども、平成２７年でこの計画は終わるんですよという中で、補助金もどうなるかわからないとおどしてはいけないんですけれども、そういう部分で少しこう。","respondent":"片田建築課長","answer":"建て替えによって道路のセットバックもできるとか、不燃化も進むといったような考え方がありますので、今後の状況を踏まえて、さらに検討してまいりたいと、このように考えてあります。","voiceIndex":67,"id":"exchange-029"},{"speaker":"井桁委員","kind":"質問","question":"私は、２８３ページの２目公園管理費の中の公園・運動施設等管理運営委託、それから公園安全点検ボランティア保険料、２８５ページの子ども達による基本構想策定記念公園づくり、それから公園バリアフリー事業についてお伺いします。今現在での申し込みの手順、そして利用状況というのをお伺いしたいと思います。","respondent":"藤田道路公園課長","answer":"今現在、現地のほうに１０釜ほどありますけれども、これにつきましての利用を進めている中で、どうしても、今委員のほうからもお話がありましたとおり、季節のよい時期、春、それから秋、それから土日、祝日という日に利用が偏っているというのが現状です。","voiceIndex":70,"id":"exchange-030"},{"speaker":"井桁委員","kind":"質問","question":"ということは、申し込む際には必ず現地に行って、本登録を済ませなければいけないということなのでしょうか。そして、ホームページのほうでは、８時半から夜の８時まで登録を受け付けていますよということなんですけれども、土日のほうは受付というのは行っていますでしょうか。","respondent":"藤田道路公園課長","answer":"それにつきましては、委員、今お話もありました午前８時半から午後の８時まで、これは土日も含めて受付を行っているところです。","voiceIndex":72,"id":"exchange-031"},{"speaker":"井桁委員","kind":"確認","question":"現地の確認ということもあるんでしょうけれども、ぜひ区役所でも登録ができるように、そして、登録に行った際に、今、台帳で多分管理されていると思うんですけれども、そういったのもぜひ、こういったデジタル化時代ですので、インターネットからの予約等々のことも踏まえて、ご見解のほうをお伺いしたいと思います。","respondent":"藤田道路公園課長","answer":"それですべてオーケーということでは私もないと思いますので、次の展開をまた考えていかなければいけないかなと思います。すいません、それから、先ほど釜数を１０釜と言いましたけれども、１５釜の間違いですので、訂正します。","voiceIndex":74,"id":"exchange-032"},{"speaker":"井桁委員","kind":"質問","question":"そこで、外来種のパンパスグラスというススキに似た草木があるんですけれども、それが毎年毎年楽しみにしていたのが、刈り取られてしまうといったような問題が一時期東品川のほうでありまして、このことについて、委託の体制といいますか、そういった草木の管理に関する委託の体制というのをお伺いしたいと思います。","respondent":"藤田道路公園課長","answer":"その中で植栽の管理等も行っているわけですけれども、日々、私ども、業者のほうとは連携を図りながら、適正な管理に努めているところですけれども、パンパスグラスは、ご案内のとおり、ススキの仲間で、外来種なので、結構大きく育ってしまうということで。","voiceIndex":76,"id":"exchange-033"},{"speaker":"井桁委員","kind":"質問","question":"次に、公園安全点検ボランティア保険料というところで、これは多分あるある点検隊の保険料だと思うんですけれども、それについて現在の登録人数と、あと参加層というんですか、それから、あと開催の回数というのをお伺いしたいと思います。","respondent":"藤田道路公園課長","answer":"こちらの保険料のほうですけれども、あるある点検隊の保険料ということで、予算書上は２００名を考えて、一応この金額が計上されているものです。ただ、現状としては、あるある点検隊のほう、人数のほうがまだそこまで行っていないのが現状です。","voiceIndex":78,"id":"exchange-034"},{"speaker":"井桁委員","kind":"質問","question":"そこで、関連になるかとは思うんですけれども、２８５ページの、先ほど言いました子ども達による基本構想策定記念公園づくりというのがあったんですけれども、これとうまくあるある点検隊というのをリンクをさせながら、会議だけでなく、現地に赴いて、このあるある点検隊というのも大人たちが、お母さんたちが子どもたちの視線に立つような、また特殊なめがねを使って点検をしたりするんですけれども。","respondent":"藤田道路公園課長","answer":"今後、検討してまいります。","voiceIndex":80,"id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"２９６ページの区営住宅費について質問したいと思います。非常に区民の大きな願いだというふうに感じておりまして、この間、繰り返し区営住宅、都営住宅の建設を求める質問をしていますけれども、改めてこの場でも質問したいと思います。そして、住宅の建設をする際に、東京都なり、国からの補助金というのは、どのくらいの割合で、どういう内容であるのか、これについても伺いたいと思います。","respondent":"齋藤住宅課長","answer":"土地取得費につきましては、この４５％相当が住宅交付金で出ますが、これは基幹型と言いませんで、提案型と言いまして、出るか出ないかはその年によって違うと。ただ、取得費のすべては区債で対応できると、こういうことにルール上はなっております。","voiceIndex":83,"id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"そうすると、例えば住宅を、適切な土地が見つかったと。そういった場合に、建設をしていきたいというふうに考えたときに、品川区の独自財源でどのくらい、何割ぐらい用意しなくてはいけないかということについては、今のご答弁では、ちょっと私、すぐに出なかったので、どのくらいの割合かというのを教えてください。","respondent":"齋藤住宅課長","answer":"独自財源といいますと、１０割が、すべて区で独自財源をして、後から国、都から７割相当が補てんされるということになります。","voiceIndex":85,"id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"確認をしたいと思います。そして、同時に、品川区としてこういう住宅を独自に建設するということは、政策判断として、していけるものだというふうに私は思っているんですけれども、その辺について、今までの質疑の中で見ると、建設する意思はないように思いますけれども、改めて品川区がそういう判断をしたときには建設できるという、こういうことでいいのかどうか、そこもちょっと確認したいと思います。","respondent":"齋藤住宅課長","answer":"何年かに１回しか募集もできない区、これが四、五区ありますが、品川区は人口も、区営住宅の数も１０番目、こういうことです。もう一つは、今ちょっと申し上げましたが、土地の取得がなかなか難しい。なかなか難しいと。","voiceIndex":87,"id":"exchange-038"},{"speaker":"南委員","kind":"意見","question":"建設費は１戸当たり幾らかという具体的な数字を聞いたんですけれども、確かに土地が高いとか、いろいろ地域によっては違うとは思いますけれども、私ども、この間のいろいろな検討の中で、１戸当たり大体７００万円から１,０００万円ぐらいで都営住宅、区営住宅ができるのではないかと。土地は別ですよ。土地は別として、そういうふうにできるのではないかというふうに思っているんですけれども、どうなのか。","respondent":"齋藤住宅課長","answer":"平米当たりの単価ですが、標準単価は法では４５万円を想定しております。ただ、区内で建てるとすると、委員おっしゃったみたいに１００万円前後かかってくると思います。７０万円から１００万円ぐらいかかってくると思います。","voiceIndex":89,"id":"exchange-039"},{"speaker":"南委員","kind":"確認","question":"平米当たり１００万円というと、ファミリーだと４５m2から５０m2ぐらいなんでしょうか。そうすると、５,０００万円ということですか。ちょっとそれは考えられないんじゃないかなと思うんですよね。土地ではなくて、土地は別として、建設費用ということで聞いたんですけれども、単価当たり１００万円ぐらいだという、そういうことでいいんですか。","respondent":"齋藤住宅課長","answer":"すみません、土地代込みと、外すというのは大分違いまして、後で整理をさせてください。区の政策判断としてということですけれども、るるご答弁申し上げておりますのは、区の政策判断として、区営住宅を建設する考えはないと。これは繰り返し、繰り返しご答弁しています。","voiceIndex":91,"id":"exchange-040"},{"speaker":"南委員","kind":"質問","question":"区が独自に判断すれば、建設することは可能ですかと聞いているんですから。今、品川の区民が、では、もう一つ伺いますけれども、この間の区営住宅、都営住宅の応募状況というのは、ここ数年前からさかのぼって、いろいろ地域によっては違うと思いますけれども、大体品川区の平均応募倍率というのはどの程度になっているのか、四、五年前ぐらいからわかれば、教えてください。","respondent":"齋藤住宅課長","answer":"すいません、幾つかご質問がありまして、論理的に、政策的に判断できるかどうかということは、理屈の問題ですので、政策判断することはもちろんできますが、ただ、状況を３つほどご説明いたしましたが、区として建設する考えはないと、こういうことです。","voiceIndex":93,"id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"私たちが数年前に計算したときよりも、随分高くなっているということは実感としては率直に感じますけれども、でも、まあ、１,２５０万円ですから、普通の民間のマンションにすれば大分安く、建設資材なんかもそんなにいいものに使っているあれではないというふうに思いますので、こういうふうな価格になるのかなというふうには理解しますけれども、そういう状況の中で、それだけの金額で建設できると。","respondent":"齋藤住宅課長","answer":"ついては、低所得者向けの住宅を都が整備してくださいと、こういった形で区は積極的に住宅政策を進めておりまして、現時点におきまして、繰り返しになりますけれども、区営住宅を建設する、このような状況にはないというふうに考えております。","voiceIndex":95,"id":"exchange-042"},{"speaker":"南委員","kind":"確認","question":"区民の方が２０年間も応募をし続けていて入れない。こういう状況を区長はどういうふうな気持ちで聞いておられるんでしょうか。非常に残念です。しかし、対住民、人口比で見たときには１６番目なんです。したがって、決して遜色ない状況ではありませんし、下から数えたほうが早いという、下のほうの順位にあるということ、ここのところはどうなんでしょうか。そういう確認をしたいと思います。","respondent":"岩田まちづくり事業部長","answer":"これは福祉でも、すべての分野において、まだまだやらなければいけないことというのは多々あります。現時点における住宅施策は、他区とのバランスを考えながら、現時点で新たに建設する考えは今のところないと、こうお答えしたものです。","voiceIndex":97,"id":"exchange-043"},{"speaker":"山内委員","kind":"質問","question":"品川区全域なんですけれども、非常に、私も歩いてみますと、２項道路というのが多いかと思うんです。これは品川だけに限らないんですけれども、２項道路、私の住んでいる戸越の周辺も結構２項道路が多いのかななんて思っているんですが、この２項道路、歩いていますと、意外とまっすぐの２項道路というんですか、いわゆる直線の、まっすぐの２項道路というのがそんなにないんです。","respondent":"片田建築課長、伊勢住環境整備担当課長","answer":"したがいまして、でこぼこがあるのは逆に当然のことでございまして、やはりそれを、長い目で見て、４ｍに拡幅をしていきたいという思いでの事業ですので、よろしくお願いします。豊町だとか、あるいは二葉、西大井等々で密集事業をやっておるわけなんですけれども、特に防災まちづくりという点で、２項道路を重点的に整備促進しなければいけないというところを指定しまして、計画にもそれを位置づけて。","voiceIndex":101,"id":"exchange-044"},{"speaker":"山内委員","kind":"質問","question":"その２項道路がなぜでこぼこになってしまったのかというのは、今ご説明があった。それはもうわかっています。そういう中で、建築のいわゆる許可、これが非常に大きな誤差があるということを伺ったんです。それを防ぐにはどうしたらいいかというので、それをいろいろ考える人がいて、それをスーパーリフォームという言い方をしますけれども、これ、極端な話ですが、柱１本残して、そこを建て替えすると。","respondent":"片田建築課長","answer":"したがいまして、そういう機会をとらえながら、区のほうとしてもそういう指導をしていきたいと、このように考えてありますし、当然セットバックをしたいので、建て替えではないんだけれども、道路を広げたい、あるいは駐車場でも広げたいといったところについても。","voiceIndex":104,"id":"exchange-045"},{"speaker":"山内委員","kind":"質問","question":"今、大規模修繕をする際に、区のほうは指導するといったときに、例えば、それを大規模修繕する。でも、これ、どう見ても改築だろうといった場合は、その場合というのは、改築という形で区がとらえ、そして私有地をセットバックしてもらうというような、そういうことも今後はしていくという、それぐらい指導というか、強制的にしていくのかという考えはあるのか教えてください。","respondent":"片田建築課長","answer":"いろいろな法律がある中でも、建物の単体と集団。集団というのは近隣への影響、あるいは避難上の重要な問題ですから、そういう機会をとらえながら、行政としては指導を進めていきたいと、このように考えております。","voiceIndex":106,"id":"exchange-046"},{"speaker":"山内委員","kind":"質問","question":"ただ、そういうお母さんたちの希望があり、これが容認されるということなんですけれども、大阪のある自治体では、自転車の３人乗りが、自転車の種類によって容認されてきたということで、三輪車ですか、いわゆる三輪車を、これを使用するご家庭というか、方には容認をするというような形で、行政がそういう指導を行ってきたということなんですけれども、これから。","respondent":"松嶋交通安全担当課長","answer":"多分それだと思います。そうしますと、自転車は別に二輪、三輪関係なく、二輪であっても、それは実質上３人は乗ってもいいという状況になっているかと思います。","voiceIndex":108,"id":"exchange-047"},{"speaker":"山内委員","kind":"質問","question":"まあ、なるほど、そういうことなんですか。いや、私の考えとちょっと違いまして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-048"},{"speaker":"本間委員","kind":"意見","question":"２６５ページ、駅周辺等放置自転車対策費の関係、それから、２６９ページ、勝島運河護岸美化工事について、２７３ページ、道路バリアフリー事業について、３点についてよろしくお願いします。順序は、２７３ページの道路バリアフリー事業のほうから行ってみたいと思います。新規に予算計上されたとのことですが、この中身について簡潔にお知らせください。","respondent":"松代管理工事課長","answer":"ましてや障害者、車いすの方が通りづらいということですので、ここのところを少し、平坦化も含めまして再整備をして、そういう都南病院跡地の周辺等の整備を図っていきたいと、このような計画です。","voiceIndex":112,"id":"exchange-049"},{"speaker":"本間委員","kind":"質問","question":"今のお話ですと、ゼームス坂からというふうな切り口を、お話を伺いました。１９０ｍという部分は、旧都南病院跡地の複合福祉施設のところまでの区間というふうに理解してよろしいでしょうか。","respondent":"松代管理工事課長","answer":"都道からゼームス坂のところの通り、その通りが１９０ｍございまして、都道のほうでもいろいろな解消をしていただきまして、私ども区道としてゼームス坂の１９０ｍ、またそこから都南病院のほうに入る狭い区道等がありますけれども、これはまた違った形での、いろいろ安全対策。","voiceIndex":114,"id":"exchange-050"},{"speaker":"本間委員","kind":"質問・要望","question":"あんな細いところで。この件についてお触れになられたということは大変ありがたいことですので、何らかの形で、あそこは前々、いろいろな形の中で、どういうふうにしたらよろしいかというふうな部分が、いい知恵がなかったものですから、ぜひこの機会に、都南病院跡地の複合福祉施設の件を皮切りに、何とかいい方向で持っていっていただきたいというふうに、よろしくお願いします。次、２６９ページ。","respondent":"藤田道路公園課長","answer":"そちらの部分に、以前から落書きをされることが多くあります。私ども、何度か落書きを消すようなことをやってきたんですけれども、なかなかきれいにならないということで、絵がかければ絵を私どものほうでかいてしまおうかということで、今回の形にしたものです。","voiceIndex":116,"id":"exchange-051"},{"speaker":"本間委員","kind":"意見","question":"放置防止といいますと、やはり自転車だとか、車等々も含んでというふうなことのように理解いたします。いわゆる違法駐輪、違法駐車というようなことも含めてですが、これ、安全対策と絡むわけですけれども、安全対策費の中に入るのかどうかわかりませんが、今朝気がついたのは、ＪＲ大井町駅のところの踏切の渡るところが、緑色のゾーンが２カ所設けられています。","respondent":"松代管理工事課長","answer":"こちらは、私どもで平成１９年度進めております踏切対策の一環として施工いたしました。ここは、区内で一番の閉鎖される踏切でございまして、ここの通行量は非常に多いものです。そういった中で、自転車と歩行者が交差するようなこともしばしばございました。","voiceIndex":120,"id":"exchange-052"},{"speaker":"本間委員","kind":"意見","question":"あと１点ですけれども、三ツ又の交差点のところですね、お地蔵がありますが、あそこの件の標識がきちんとなされました。この件について大変努力されたと思いますけれども、改善策に至ったご見解といいますか、努力された中身について、一言お知らせください。","respondent":"松嶋交通安全担当課長","answer":"それと、最近、今度は右側にも同じようにつけて、２枚つけて、わかるようにしたという対策です。","voiceIndex":122,"id":"exchange-053"},{"speaker":"本間委員","kind":"質問","question":"あそこのお地蔵さまをお世話している方からお聞きしまして、大変危険な思いをしたということで、早くからその件について私どものほうにも陳情があったわけですが、大変喜んでおられます。そこを注目していただいて、早速の改善努力をされたことにつきまして感謝申し上げますが、これからも引き続き危険な箇所につきましては努力をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-054"},{"speaker":"藤原委員","kind":"質問","question":"２９７ページ、借上型区民住宅管理費についてお伺いします。空き家が多い住宅が、いろいろなところの課長のご答弁で、３つあるということなんですけれども、もし答弁してくださるなら、その３つ、具体的にどこかということと、この何年間、どんな様な空き家状態と、区がどのぐらいのお金を補償しているか、教えてください。","respondent":"齋藤住宅課長","answer":"それで、ブラウネハイム倉田は１１戸ございまして、平成１７年度、空き家が３戸。それで、空き家補償が６７０万円。平成１８年度は４室で、８９０万円。平成１９年度も４室で、同じく空き家補償は８９０万円です。","voiceIndex":126,"id":"exchange-055"},{"speaker":"藤原委員","kind":"質問","question":"３つの住宅を挙げていただいたんですけれども、平成１９年度だけで、今ちょっと計算したんですけれども、５,０００万円以上になります。区があげているわけですよね、お金。補償というきれいな言葉ですけれども。結局は、税金を使って。区がつかんでいると思うんですけれども、何でこの３つの住宅、これだけ空いているのか、理由を教えてください。","respondent":"齋藤住宅課長","answer":"平成１９年度、３住宅で５,２００万円近くの空き家補償の額になっております。","voiceIndex":128,"id":"exchange-056"},{"speaker":"藤原委員","kind":"質問","question":"でも、この制度があれば、何もしなくても、人が入らなくても、ずっと家賃補助は２０年間してくれるわけですよね。私も一般質問でちょっと伺いましたけれども、その後のことはいろいろ考えるという形なんですけれども、２０年後の更新については、まずオーナーの方はどういうふうに言っているかということと、区としては２０年後はどういうふうにしていくかということを考えているか、教えてください。","respondent":"齋藤住宅課長","answer":"２０年後どのようにするかということについては、また今後、区でも内部で検討しますし、皆さんのお話をお聞きはしますと、こういうことで、定期的にお話し合いはこれからも持とうということにしております。","voiceIndex":130,"id":"exchange-057"},{"speaker":"藤原委員","kind":"質問・要望","question":"そこをいい試練ということで、課長の頭によく入れておいていただいて、２０年後の、オーナーの気持ちはわかるんですよ。どういうお考えか。この今制度を使っているオーナーだけじゃなくても、もしそういう制度が、まだもしの話ですけれども、一般のマンションのオーナーの方たちも手を挙げたいという形になってこないと、逆におかしいと思うんですけれども、その辺はいかがでしょうか。","respondent":"齋藤住宅課長","answer":"それで、今後の住宅施策の転用ですけれども、これについては、私は住宅課長ですけれども、福祉高齢事業部の方ともいろいろ検討させていただきたいと、こういうふうには考えておりますが、住宅自体は６０m2を超える、要するに親子５人ぐらいの住宅ですので。","voiceIndex":132,"id":"exchange-058"},{"speaker":"渡部委員","kind":"質問","question":"今日は、２６９ページの交通安全施設で、特にスクールゾーンの件についてと、２８５ページ、公園・児童遊園整備の中で、設計委託費に掲げられています公園と、子ども達による基本構想策定記念公園づくりについて、お伺いしていければと考えています。どの程度の時期で行われていくのかなというところ、気になりますので、まずお聞かせ願えればと思います。","respondent":"松嶋交通安全担当課長","answer":"スクールゾーンにつきましては、これまで８時から９時ということで、通学時間との矛盾があったということで、それを７時半から８時半に徐々に変えていこうということで、今年度につきましては３校実施済みのものです。","voiceIndex":135,"id":"exchange-059"},{"speaker":"渡部委員","kind":"質問・要望","question":"ともかく７時半から８時半、実態に即した時間帯のゾーン規制に早くなることを願って、この質問は終わらせていただきます。ということは、平成２１年度以降で本改修といいますか、始まっていくのかなと思いますが、例えば八潮北公園にしましても、小山台公園にしましても、もし、今わかる段階で、改修の概要がわかれば教えていただけますでしょうか。","respondent":"松代管理工事課長","answer":"地元の町会等からの要望も含めまして、地域の方から要望がありましたので、この辺のところの部分を、バリアフリー等を含めて、もう少し使いやすいような、地域の声に合ったような形に改修したいと、このように考えているところです。","voiceIndex":137,"id":"exchange-060"},{"speaker":"渡部委員","kind":"質問","question":"八潮北公園のグラウンドで、多目的利用を目的とした人工芝ということは、今八潮北はたしか普通の野球場としてだけ使えるようになっていたと思いますが、では、フェンスだとかは１回壊しまして、例えば天王洲のＡＢ面みたいな形のものになるのでしょうか。そこを、１点、お聞かせください。","respondent":"松代管理工事課長","answer":"ほぼ９割方完成しておりますが、こちらをぜひ、近々、完成した暁にはご覧いただきたいんですが、こちらのようなイメージで、多目的に使えるような、また人工芝として、時間も広げながら、使えるような施設にしたいという考えです。","voiceIndex":139,"id":"exchange-061"},{"speaker":"渡部委員","kind":"質問","question":"八潮北公園のグラウンドは、また土が特別なグラウンドだったと思います。それと、先ほど来、朝からも質問がありました子ども達による基本構想策定記念公園づくり。取り寄せると言ったらおかしいか、取り入れられるのかなと。ぜひ、学校等を通じて、何か活動の一つとしてこの１年間できないのかな、できればいいなと思っているんですが、その辺のお考えはいかがでしょうか。","respondent":"松代管理工事課長","answer":"バーチャルリアリティー、空から見るようなことも技術的にはあります。そういったことをもっと取り入れながら、いろいろな角度から、子どもたちのイメージが膨らむ。それをいろいろと発想していただける、そういったものを一緒に考えて行ければと、このように考えております。","voiceIndex":141,"id":"exchange-062"},{"speaker":"渡部委員","kind":"質問・要望","question":"本当に夢のある話であって、子どもたちが、小さいことかもしれないですけれども、自分の意見が取り入れられたとかになりますと、愛着の生まれたものになるのかなと思います。そういう子どもたちが各校から１人集まって、いろいろ相談していくんだとか、いろいろな形がとれるのかなとか考えてはいるんですが、ぜひ立派な公園ができるように進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-063"},{"speaker":"大沢委員","kind":"質問・要望","question":"２８５ページ、小山台公園改修設計と、その下の東急目黒線緑道等整備事業、ページ進みまして、２８９ページ、都市防災不燃化促進事業、そして、時間がちょっとあると思いますので、２９１ページの都心共同住宅供給事業をお伺いさせていただきたいと思います。これは当然のことでありますけれども、地域の方の声、どのような声が上がっているのか、お知らせいただきたいと思います。","respondent":"松代管理工事課長","answer":"私どものほうでじかに聞いておりますのは、町会長等を通しまして町会の声ということで、先ほど言いましたように、改修を順次進めていたんですけれども、ここ、改修の期間が少し間が空いていまして、最近改修されていない部分がありますよと。","voiceIndex":145,"id":"exchange-064"},{"speaker":"大沢委員","kind":"質問・要望","question":"地域の声ということで、利用しやすく、バリアフリーにしたい。非常に抽象的なご意見を拝聴させていただきましたけれども、利用しやすいとは、では、一体何をもって、言葉の話になってしまいますけれども、利用しやすい、具体的に描いている像みたいなのがありましたら、何が利用しやすいのか、教えていただきたいと思います。","respondent":"松代管理工事課長","answer":"そういった流れを撤去することによって、その空間をもっと違う形で使えないか、そういったご要望がありますし、至るところに休養施設、ベンチ等が置いてあるんですけれども、そういったものを、のんびり散策しながら、ちょっとそこにたたずんだり、休んだりして。","voiceIndex":147,"id":"exchange-065"},{"speaker":"大沢委員","kind":"質問・要望","question":"いずれにしても、目黒区と品川区のちょうど、あそこは間になりますけれども、先ほど、ちょっとの間、会合を開かなかったという部分がありましたけれども、そこのところはなるべく密に、地域の方のご意見を伺うような場をぜひとも設けていただいて、あそこの場所というのは、武蔵小山駅周辺とあの場所を比べますと、温度が、夏のあの暑いときに２度違います。第２緑道が３１０ｍ。これはなぜでしょうか。","respondent":"松代管理工事課長","answer":"これは、正直申しまして、整備内容の違いでございまして、一方では、水を使う施設、もしくはそうではない施設によって、もちろんそれにかかる経費が違ってまいりますので、いろいろと当初の地域からの声を入れて。","voiceIndex":149,"id":"exchange-066"},{"speaker":"大沢委員","kind":"質問・要望","question":"平成１５年当時だったと思いますが、意見を集約して、第１緑道、第２緑道の方たち、集まっていただいて、第２緑道のほうはビオトープ、子どもたち、後輩に、荏原第六中学校、そして小山小学校を控えておりますので、ビオトープを組み入れた公園をつくりたいというような要望を、おそらくこれで入れていただけたのかなというような受け取りをさせていただきましたけれども。","respondent":"松代管理工事課長","answer":"幅員１０ｍぐらいのものしかない、もともとは鉄道敷きですので、１０ｍぐらいしかないんですけれども、そこをゆっくり散策、もしくは歩いていただくときの脇に流れを、ぜひ水の流れをつくってほしいと、そういったものを今回契約の中に入れたものです。","voiceIndex":151,"id":"exchange-067"},{"speaker":"大沢委員","kind":"意見","question":"水の流れということで、これは第１緑道、第２緑道、そして第３緑道、一連の流れの中で緑道をつくっていくわけですけれども、流れ、第１緑道、第２緑道、第３緑道の中で一定のテーマといいますか、道に対する流れのテーマというか、そういうのがもしあれば、お聞かせください。","respondent":"松代管理工事課長","answer":"３つとも一応皆さんが考えたテーマがございまして、第１緑道はシンプルですっきりとした緑道というような形でまとめてあります。第２緑道は、子どもたちと一緒に楽しめるような、多彩な緑道ということで、この第２緑道にその水の流れを設けてあります。","voiceIndex":153,"id":"exchange-068"},{"speaker":"大沢委員","kind":"質問・要望","question":"ぜひともよろしくお願いいたしたいと思いますが、もう一つだけ今言い忘れたので、あれですが、緑道をつくるに当たって、沿道の方たちの防犯といいますか、防犯対策、垣根を高くするとか、樹木を植えるとかということで、対処はしていただいているとは思うんですが、そこのところ、改めまして、確認の意味を込めて、お聞かせいただきたいと思います。","respondent":"松代管理工事課長","answer":"今回のこの整備に当たりましては、委員からお話もありましたように、ワークショップ、または説明会を開いて、多くの方に参加していただいて、計画を進めております。ただいま質問がありました説明会とは違いまして、沿道の方々とは非常に密接な、今後も、関係ができます。","voiceIndex":155,"id":"exchange-069"},{"speaker":"大沢委員","kind":"質問・要望","question":"あそこの地域、まだ３つ、４つということで、図面、そういうようないろいろな協議会、まちづくりの組合ができて、さまざま活動をしているわけですけれども、武蔵小山の立地から考えた場合、景観という観点から、高さ的にどういうようなご意見というか、区行政としてはどのような方針を持っておられるのか、これは都の委託事業、確かにしゃれた街ですから都の条例の適用もありますけれども、これ。","respondent":"伊勢住環境整備担当課長","answer":"東京のしゃれた街並みづくり推進条例だとか、あるいは地区計画、ここでは容積の緩和とともに、高さを６０ｍに定めるということで、武蔵小山でもいろいろな立地がありますけれども、基本的には駅前、あのあたり、しゃれ街のあのエリアでは６０ｍの高さは許容されていると。","voiceIndex":157,"id":"exchange-070"},{"speaker":"大沢委員","kind":"質問・要望","question":"その意味で、確かに６０ｍというのは許容されているわけですけれども、そこの近隣の方との、６０ｍ、その意識の違いというのはどのようにとらえられ、どのように、処理はできるものではないと思いますけれども、でき得る処理というのはどのような、皆さんにご納得、どのような形があるのか、教えていただきたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"この都市計画等を定めるに当たりましては、縦覧あるいは説明会等が行われて、区としては説明してきたです。","voiceIndex":159,"id":"exchange-071"},{"speaker":"大沢委員","kind":"質問・要望","question":"いずれにしても、まちづくり、本当に小山のまち、新しく生まれ変わろうと、まさに今しています。高さ、高い、低い、いろいろでこぼこがあるかもしれないんですが、ぜひとも小山の街並みを考えながら、計画を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-072"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"２７３ページの道路バリアフリー事業についてなんですが、バリアフリーと言われても、さまざまなものがあると思いますが、それこそ段差の解消だったり、道幅を広げる等があると思いますが、歩道橋について、区のお考えをお伺いさせていただきたいと思います。それと、今後、歩道橋に対して区の考え、どのような考えがあるのか、もし具体的なものがありましたら、教えていただければと思います。","respondent":"松代管理工事課長","answer":"橋の個々の利用状況ですけれども、２２橋ありますので、すべてというわけにいかないんですが、幾つかの例でいいますと、例えば先ほど質問が出ました百反歩道橋、これが１日に３６０人から３７０人ぐらいの歩行者の方が使われているというようなことの実態です。","voiceIndex":163,"id":"exchange-073"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"私もある方に、高齢化社会が進む中、歩道橋、非常に、高齢者に対してはつらいという声があって、ぜひ、歩道橋ではなく、そこに横断歩道をつくってくれないかという声もいただきました。その中で、やはり一番は、高齢化社会が進む中で、歩道橋ではなく、できたら横断歩道に変更を進めていただきたいと思うのですが、区のお考えをお伺いします。","respondent":"松代管理工事課長","answer":"これ、昭和４０年代、交通戦争といいますか、非常に自動車交通が増えまして、子どもたちの安全対策ということで、都をはじめ区も歩道橋等を設置してきたものです。この歩道橋を子どもたちが渡る、それに勝る安全というものはございません。","voiceIndex":165,"id":"exchange-074"},{"speaker":"石田（慎）委員","kind":"質問","question":"もう一点お伺いします。２８３ページにあります地域における総合的なまちづくり推進事業について、概要を教えていただければと思います。","respondent":"藤田道路公園課長","answer":"今回のこの地域における総合的なまちづくり推進事業ですけれども、今、基本構想ということで、「輝く笑顔」というような形の言葉が含まれておりますけれども、そういったまちがこれから広がるようにということで、新たなまちづくりの進め方。","voiceIndex":167,"id":"exchange-075"},{"speaker":"石田（慎）委員","kind":"質問","question":"それは区独自で考えて進めていくのか、それとも地域の方たちと相談をしながら考えていくのか、そこを教えてください。","respondent":"藤田道路公園課長","answer":"そうした面では、地域の人たちと十分な、さまざまな形で、いろいろな人たちとお話をしながら進めていきたいというふうに考えてあります。","voiceIndex":169,"id":"exchange-076"},{"speaker":"石田（慎）委員","kind":"質問","question":"午前中、原委員から五反田にぎわいゾーンについての質問もあったんですが、それと関連して大井町駅周辺地区再開発事業も２８９ページに載っておりますが、これもやはり地元の方たちといろいろな話し合いをしながらつくっていくのかなという、僕の中でイメージがあるのですが、これと、地域における総合的なまちづくりというのは関連はするのでしょうか、教えてください。","respondent":"藤田道路公園課長","answer":"そういった中で、これからどういった地域の中で、どんな活動をしていくべきか、その辺についても具体的なことを長期基本計画、そういったものもあわせもって検討する中で、考えていかなければいけないというふうに考えてあります。","voiceIndex":171,"id":"exchange-077"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"時間もないので、最後、要望というか、私の意見を伝えたいと思いますが、大井町駅周辺と五反田にぎわいゾーン、大きなＪＲの駅があって、非常に利用する方もたくさんいる中で、もちろん地元の方を中心としての意見交換というか、はあると思うのですが、ほかの実際に利用している方たちとか、そういった少し輪を広げた検討会というんですか、そういうものもぜひつくっていただければなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-078"},{"speaker":"井上委員","kind":"質問","question":"私は、やさしいまちづくりという視点で、２７３ページの道路バリアフリー事業と、２８５ページの公園バリアフリー事業、それから、別な視点で、２６９ページ街路灯建替についてお伺いをしたいと思います。それから、２００８年度はどこを予定されているのか。誘導ブロックを敷設する場所はどのような経過で決められていくのかということをお伺いします。","respondent":"松代管理工事課長","answer":"点字ブロックの敷設です。これは実施計画事業として計画的に進めているものでございまして、それぞれに、平成１８年度は９０ｍの契約に対しまして９４.７ｍ、平成１９年度の中では８４ｍの契約に当たりまして、７２.８ｍという実施をしております。","voiceIndex":175,"id":"exchange-079"},{"speaker":"井上委員","kind":"質問","question":"八ツ山通りということですが、あと、大井町から都南病院跡のバリアフリーの計画が、先ほどもあるとおっしゃっていましたけれども、ここの付近での敷設があるのかどうかということをお伺いしたいと思います。","respondent":"松代管理工事課長","answer":"失礼しました。都南病院跡地のほうのバリアフリー化は、先ほど言いましたゼームス坂のほうの歩道改修等にあわせて、実施する部分として考えてあります。そちららのほうも点字ブロック等の実施をしたいと考えているところです。","voiceIndex":179,"id":"exchange-080"},{"speaker":"井上委員","kind":"質問・要望","question":"そこで、実際に、視覚障害者の方が大井町駅から社会福祉協議会へ行く誘導ブロックがないので不便を感じているという声と、また、先日、日曜日に私、心身障害者福祉会館で、視覚障害者の方のパソコン教室をちょっと見学させていただいた折に、団体としてもその部分、要望しているけれども、なかなか実現がされないという声を聞きましたけれども。","respondent":"松代管理工事課長","answer":"これまでも障害者７団体等との協議等を踏まえて、そこからの要望分、または要望される内容等は文書できちんと受けとめて、それにできる限り対応するような取り組みをしておりますけれども、今の件については、申しわけありません、こちらのほうでは受けとめてございません。","voiceIndex":181,"id":"exchange-081"},{"speaker":"井上委員","kind":"質問・要望","question":"そのことも含めて、この間の民生費のところで、やさしいまちづくり推進計画で、その推進計画の中に当事者を入れてほしいということでしたけれども、調査をする中に、まち歩きなど、原小学校跡のエリアで行いたいということをお聞きしましたけれども、ぜひ、こういったところも、原小学校跡の敷設ということを決めるのではなく。","respondent":"松嶋交通安全担当課長、松代管理工事課長、岩田まちづくり事業部長","answer":"ただし、我々としましては、交通管理者のいつまでも、こんなことを言うとあれなんですけれども、いつまでもできないあれを待っていてもしようがないので。交差点部分の点字ブロックの件でのご質問がございました。基本的に、交差点部分の改良、交通安全の対策の改良というのは、歩道がある部分です。委員ご指摘のエスコートゾーンというのは、歩道がある交差点で、歩道から車道に下りる横断歩道の歩道側にちゃんと点字ブロックが設置されているのに。","voiceIndex":183,"id":"exchange-082"},{"speaker":"井上委員","kind":"質問・要望","question":"次は、公園バリアフリーのところなんですけれども、今年度、公園整備で、だれでもトイレの設置の予定があるのかということと、それから、公園と庁内にもだれでもトイレがあるわけですが、そこのトイレの利用対象はどういう方だと認識をされているのかお伺いします。","respondent":"松代管理工事課長","answer":"だれでもトイレです。平成２０年度の予定としましては、荏原町公衆便所の改築に当たって設置をしたい。それに加えまして、今回整備する公園の改修に当たってのトイレ、そのところでの２カ所、八潮公園便所の改修工事、ここのところでもだれでもトイレを設置したいと考えています。","voiceIndex":187,"id":"exchange-083"},{"speaker":"井上委員","kind":"意見","question":"だれでもトイレ、多機能トイレですね。それで、高齢者・障害者配慮設計指針というのが、昨年３月にＪＩＳ規格として制定されました。庁内では経理課、区有施設はそれぞれの所管課がだれでもトイレの設置を把握していると思うんですけれども、区として、どこかが中心になって、区内のだれでもトイレに関してですけれども、掌握している部署があるのか、２点、お答えください。","respondent":"松代管理工事課長","answer":"そういう中で、今委員がおっしゃられたような、今後はきちんとそれを把握し、統合して、公共施設も含め、いろいろなところでそれを実施していく、そういったものをつくっていくように、今後も検討を進めていきたいと考えています。","voiceIndex":189,"id":"exchange-084"},{"speaker":"井上委員","kind":"質問・要望","question":"そういったところを見ると、ぜひ、これから設置する、昨年の、これはＪＩＳのＳ００２６という基準になっていますけれども、こういったものを参考にしていただいて、この中でもまだまだ検討課題というふうにはなっていますけれども、今後広く規定をしていこうということがこの関係のホームページにも書かれていますので、ぜひ、その基準を統一した、ばらばらに設置するのではなく。","respondent":"松代管理工事課長","answer":"今委員から出たような新しいそういった施設、新しいものがあれば、それが取り入れられるものであるとすれば、それは取り入れるような検討を進めて、常に利用者の方々に使いやすいものを考えていきたいと、このように考えているところです。","voiceIndex":191,"id":"exchange-085"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひそれは積極的に、当事者でなければわからないバリアです。私たちが想像のつかないバリアを持っておりますので、進めていただきたいと思います。ちょっと時間が短いですので、今回、街路灯の建替えなんですけれども、街路灯の建替えについて、今回省エネ型にするということでした。そして、また、スピードアップをする方針があるのかということをお伺いしたいと思います。","respondent":"藤田道路公園課長","answer":"今回、私どものほうで街路灯の建替え、これ、実施計画の中で計画的に進めている事業ですけれども、その建替え時期にあわせて、古くなって、老朽化して、そろそろ取り替えなければいけない、そういったものについて順次建替えをしていくということで行うもので。","voiceIndex":193,"id":"exchange-086"},{"speaker":"井上委員","kind":"質問・要望","question":"今建替えの必要にあわせてということでしたけれども、今後の長期基本計画にも環境にやさしいまちづくりというところがある中で、長期基本計画の中にもぜひそういった、地球温暖化防止というところ、もっと大きくとらえていただいて、スピードアップをしてほしいと思うんですが、もう一度、その辺のところをお答えいただけますか。","respondent":"藤田道路公園課長","answer":"そのペースとあわせて、年間１５０本から２００本やっているとちょっと間に合わないというペースになりますので、できるところからやっていきたいというふうに考えてあります。","voiceIndex":195,"id":"exchange-087"},{"speaker":"若林委員","kind":"質問・要望","question":"何点か伺います。２６５ページの交通安全対策費では、歳入に戻りますが、交通安全対策特別交付金が来ておりますが、この５,０００万円の割り振りについて、この歳出のほうではどういうふうにこの５,０００万円が使われているのかというのを教えていただきたいと思います。それから、２７３ページの道路バリアフリー。エスコートゾーンのほうは、昨年の第４回定例会で私も取り上げさせていただきました。","respondent":"日下部企画財政課長、松嶋交通安全担当課長、堀越行財政改革担当課長","answer":"１点目の交通安全対策特別交付金についてのお尋ねです。それと、先ほどモデル的にと言いましたけれども、先ほどもご説明しましたとおり、これは交通管理者が設置するもので、本来であれば道路管理者ではないので。安全があって、また安心があるというような形で、基本構想、それから施政方針。","voiceIndex":198,"id":"exchange-088"},{"speaker":"若林委員","kind":"質問・要望","question":"そうしますと、午前の質疑でも、金野委員からもありましたが、ちょっと細かいところで、「交通しながわ」という冊子でしょうか、４万１,０００部について多少ご説明がありましたが、この活用についてはどのようにされているのかというのを、もうちょっと深まったお話をお聞きしたいのと、４万１,０００部というと相当な部数ですので、ここら辺のお金の使い方、ご説明いただければと思います。","respondent":"松嶋交通安全担当課長","answer":"「交通しながわ」、かなり大きい枚数ということで、先ほど配布先を地域センター、文化センター、図書館ということでお話しいたしましたけれども、あわせて各警察署に置いて、交通安全教育、警察のほうで交通安全教育をするときだとか、あとは受付のところに置いて配布をしたり。","voiceIndex":202,"id":"exchange-089"},{"speaker":"若林委員","kind":"質問・要望","question":"むだのないように、しっかり、４万１,０００部、これが３万部とか４万部でもいいのではないかというようなお話も出てくるかもしれませんので、そういう使途をよろしくお願いいたします。あわせて、先ほどあったのかどうか、年間、そういう突発的なもの、出前的なものが何カ所、小・中学校以外の突発的なものがどのぐらいあるのか、教えていただきたいなと思います。","respondent":"松嶋交通安全担当課長","answer":"それと、小・中学校の安全教育のですね、失礼しました。突発的には、ちょっと今何件というようなことは言えませんけれども、結構あるということです。","voiceIndex":204,"id":"exchange-090"},{"speaker":"若林委員","kind":"質問・要望","question":"費用がゼロということで、また、いわゆる区役所にある景品も有効活用されているということで、大変にすばらしいことだなというふうに理解いたしました。区内各所でこういう費用のかからない、こういう有意義な安全講習会が開かれますように逆に誘導していただけるような、そういうまた施策も打っていただきたいと思いますが、最後にそこだけ、一言、前向きなご答弁をお願いいたします。","respondent":"松嶋交通安全担当課長","answer":"委員おっしゃられたとおり、講習はやってやり過ぎるということはないと考えておりますので、そういった要望があればどんどん飛んでいきますし、区で対応できないものであれば警察署のほうにいろいろ要請もいたしますし、警察独自でやっているところもありますし。","voiceIndex":206,"id":"exchange-091"},{"speaker":"高橋委員","kind":"質問・要望","question":"２８１ページの河川維持費と、２８３ページの公園・児童遊園維持管理費のところと、２８５ページの公園・児童遊園整備のところをお尋ねします。２８１ページですが、立会川の浄化についてです。成果が随分上がっているとお聞きしたのですが、今後の見通しをお教えいただきたいと思います。","respondent":"家壽田下水道河川課長","answer":"立会川浄化についてお答えいたします。昨年の６月から浄化実験を開始しておりまして、ご覧いただければ一目でわかるぐらい川はきれいになって、においがとれているということで、周辺の皆様方に大変ご好評いただいております。","voiceIndex":209,"id":"exchange-092"},{"speaker":"高橋委員","kind":"質問・要望","question":"２８３ページなんですけれども、もしここでいけないようでしたら教えていただきたいんですが、鮫洲に運動公園があるんですが、そこでは土曜日、日曜日に小学生が、保護者も含めれば１００人近く来て、少年野球をやっているんですが、朝から夕方まで。そこに万が一に備えてＡＥＤを設置することができますでしょうか。","respondent":"藤田道路公園課長","answer":"そうした中で、現在、自動販売機型のやつもあるので、その辺で何とか設置ができないかということでさまざま検討したんですけれども、どうしてもいたずらがあるということで、そういった面での設置も難しいということで、なかなかいい方法が見つからないということで。","voiceIndex":211,"id":"exchange-093"},{"speaker":"高橋委員","kind":"質問","question":"つまり貸し出しですね。少年野球の連盟の方が講習を受けて、そういう方法か、あるいはこれはちょっとお金が厳しくなるんですが、少年野球の連盟のほうが購入するときに何らかの補助をするとかというようなところは、というふうに思ったんですが、いかがでしょうか。","respondent":"藤田道路公園課長","answer":"利用者の命にかかわる問題なので、さまざまな形での検討は必要かと考えています。そうした中で、所管部署とも今後もいろいろお話をしていきたいというふうに考えてあります。","voiceIndex":213,"id":"exchange-094"},{"speaker":"高橋委員","kind":"意見","question":"お祭りやコミュニティの中心にもなっております。旧消防署のところを取得して、今広場になっているんですが、地域の親子がボールを蹴ったり、そういうスペースもあるので、そういうところを残してほしいとか、防災の施設を集中できるスペースを確保したいなどの声があるんですが、地元の方々の意見を吸い上げる、そういった考えをお尋ねします。","respondent":"松代管理工事課長","answer":"今委員からも出ましたように、防災の面、また多目的に使えるような広場型にしてほしいというような声がよせられてあります。そういったものを少したたき台にしまして、この３月１９日に地元説明会を鈴ケ森小学校で開きます。","voiceIndex":215,"id":"exchange-095"},{"speaker":"高橋委員","kind":"質問","question":"同じく２８５ページなんですが、これは、公園になるといいなということで、鮫洲のポンプ場の跡、都の施設なんでしょうけれども、先ほど目黒線の緑道のワークショップでの成功の例をお話しいただいたんですが、都の施設なのでいろいろな事情がおありとは思うんですが、その後の、埋め立て跡に公園等に関して、ワークショップや、あと地元の住民の方の意見を取り入れた、区民の方々が過ごせる。","respondent":"松代管理工事課長、家壽田下水道河川課長","answer":"将来は上部を利用して公園というような形ですけれども、その進め方については、まだまだいろいろと今後検討する余地があろうかと思いますけれども、今委員からありましたような、そういった手法も一つの方法として。若干補足いたしますと、今委員ご指摘の勝島ポンプ場につきましては、平成２３年度に完成する予定というふうに都のほうから聞いておりますので、その上部の利用についてそれ以降、平成２４年度以降に決めていくという形に。","voiceIndex":217,"id":"exchange-096"},{"speaker":"高橋委員","kind":"質問","question":"景観を損ねてしまうかもしれないんですが、階段のところだけでも安全になるような、というのはここでお話を聞いていいのかちょっとわからないんですが、いかがでしょうか。","respondent":"藤田道路公園課長","answer":"そういった中に施設を設けるということになると、港湾局との十分な調整が必要ということで、通常であれば、なかなかそういった施設を設けることは難しいということにはなっておりますが、現在運河ルネッサンスのエリアにも入っていることもありますので。","voiceIndex":220,"id":"exchange-097"},{"speaker":"本多委員","kind":"質問","question":"２７５ページの踏切改良事業と、２８３ページの地域における総合的なまちづくり推進事業について、質問いたします。踏切のほうなんですが、現存する踏切を改良するということには理解できますが、今後の課題ということで質問をします。予算、費用負担についてお知らせください。","respondent":"松代管理工事課長","answer":"これにつきましては、私ども道路管理者として実施するものでございまして、費用の５５％は国庫補助、またその残りの部分は財調対象というような形で進めていくものです。","voiceIndex":223,"id":"exchange-098"},{"speaker":"本多委員","kind":"意見","question":"踏切の位置ですとか、管理方法なんですけれども、ＪＲの場合ですと何々踏切とかそういう名称ですとか、そういう管理方法だと思うんですが、私鉄の場合ですと、Ａ駅でしたらＡ駅から数えて１号踏切、２号踏切、３号踏切、Ｂ駅なら１号踏切、２号踏切と順番に、いろいろな、指定されて管理されているんだと思うんですけれども、そういう管理の決め方というのは。","respondent":"松代管理工事課長","answer":"委員から今お話がありましたように、東急、京急は比較的新しい路線でしょうか、基点とする駅から下り方向、東京から、都心から離れる方向で１号踏切、２号踏切というような感じで踏切の名称をつけているようでございまして、非常にわかりやすいものです。","voiceIndex":225,"id":"exchange-099"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、東急のほうなんですけれども、急行の停車ですとか、通過に伴って、この間建設委員会でその安全管理については十分やりとりがありましたので、東急のほうは聞かないんですけれども、苗木原のほうなんですが、２カ年で進めていくということなんですけれども、この、まず、安全管理ですね、２カ年どういうふうに安全管理を考えているのか、教えていただきたいと思います。","respondent":"松代管理工事課長","answer":"苗木原の、今回２カ年にわたっての拡幅工事ですけれども、これにつきましては、実際施工に当たりましては、ＪＲ東日本のほうに施工委託ということで工事等をお願いいたします。ですから、鉄道の通行を最優先に考えて、鉄道の通行が終わった時点から工事をする。","voiceIndex":227,"id":"exchange-100"},{"speaker":"本多委員","kind":"質問・要望","question":"夜間というか、深夜が主になるんですね、そうすると。その辺のところを確認させていただきたいんですが。","respondent":"松代管理工事課長","answer":"そういった意味では、厳しい内規、法に基づいた内規等に基づいて運行されていると考えていますし、私どもが鉄道に近接して工事する場合は非常にうるさく言ってきます。安全対策優先で、我々が普通考えるような安全対策のそれ以上の安全対策を求められております。","voiceIndex":229,"id":"exchange-101"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、議案説明会のときにいただいた資料で、この踏切事業なんですけれども、下神明のところは「東急大井町線」と書かれていて、苗木原は「横須賀線」と書いてあったんですけれども、実際的には横須賀線だけではなくて、湘南新宿ラインですとか、ほかの種類もありまして、ましてや本数がこれから増えていくような傾向だと思うんですけれども、その辺のところの課題というか、どういうふうなお考えか。","respondent":"松代管理工事課長","answer":"私どもが今ＪＲのほうと拡幅工事に当たって協議をしている中では、横須賀線の支線、品鶴線ということでの利用があるということでございまして、その利用等を最優先として、拡幅の工事等をＪＲが受けて進めていただくと、このように承知しています。","voiceIndex":231,"id":"exchange-102"},{"speaker":"本多委員","kind":"質問","question":"それで、本数が増えていく傾向だと思うんですけれども、平面交差ですね、道路と鉄道との交わる部分の平面交差なんですけれども、法的には鉄道と道路が平面交差する場所というのは踏切道という場合もあるそうなんですけれども、現在では、これ、列車のほうが優先というふうになっているんですけれども、それで、本数がどんどん、どんどん増えていって。","respondent":"松代管理工事課長","answer":"ただ、この路線はそれほど交通量等がございませんので、今のところは、現状の中での拡幅をすることが、一番の利用者にとっての平面交差上の安全対策がとれるものというふうに考えているところです。","voiceIndex":233,"id":"exchange-103"},{"speaker":"本多委員","kind":"質問","question":"今、交通量が少ないという答弁だったんですけれども、何の交通量ですか。","respondent":"松代管理工事課長","answer":"こちらは、道路と鉄道が交差しまして、道路のほうの通行量が現在、歩行者が１日当たり６８０人ぐらい。自動車が１日で２,０５３台ぐらい通っておりますけれども、これが、２６号線が完成しますと、激減するというふうに予測をしております。","voiceIndex":235,"id":"exchange-104"},{"speaker":"本多委員","kind":"質問・要望","question":"２８３ページの地域における総合的なまちづくり推進事業に移りますが、これ、ハード面、ソフト面、両側から支援というか、やっていくという説明だったんですけれども、先ほど来出ておりまして、地域の実情に合わせた総合的なまちづくりの検討ということで、地域を考えた施策を打っていく、第四次長期基本計画でやっていくということなんですけれども、そのページにいろいろある事業で。","respondent":"堀越行財政改革担当課長","answer":"今行っています例えば八潮ですとか、そういったそのほかのいろいろな取り組みを含めて、さらに総合的にどういった形で進めていくことができるかを、まちづくり事業部、それから企画部と一緒に、ほかの事業部も一緒になって、あわせて検討していくと、そういったものです。","voiceIndex":237,"id":"exchange-105"},{"speaker":"本多委員","kind":"質問・要望","question":"今、区内、再開発組合ですとか、準備組合も気運が高まって、幾つかありますけれども、これから新たにそういう気運ということも、関係というか、対応できるかどうか、その辺を教えていただきたいと思います。","respondent":"藤田道路公園課長","answer":"そういった中では、さまざまなまちの動き、これにも敏感に感じながら、どうやって動いていけばいいか、それについては十分検討する必要があるというふうに考えています。","voiceIndex":239,"id":"exchange-106"},{"speaker":"阿部委員","kind":"質問","question":"私からは、２８９ページ、大崎駅周辺再開発について、それから２６５ページに戻りまして、交通安全対策、これは交通政策全般も含めてなんですけれども、お伺いしたいと思います。さらに、２８５ページ、しながわ水族館、それから同じく２８５ページの子ども達の公園づくりについて、お伺いしたいと思います。それで、この地域ですね、特に新しい住民の割合が非常に多い。これから入ってくる人もまた多い。","respondent":"青木都市開発課長","answer":"その中に、ちょっと言い方は難しいんですけれども、クラブハウスではないんだけれども、公園の詰所よりも立派なものというようなイメージのものをつくりまして、それを、今はまだ検討段階ですが、地元の方々に管理運営をお願いできないかということを検討している最中です。","voiceIndex":242,"id":"exchange-107"},{"speaker":"阿部委員","kind":"意見","question":"一定のお考えを持っていただいているということで、集会所等もぜひ地権者に限らず、広く地域の方々が利用できるような形でご検討いただければと思います。それから、例えば五反田駅ですとか、ああいった大きな、比較的交通量の多いところなどは積極的に増やしていくべきではないかと思うんですが、今後の予定、そして今後の方針ですね、そういったところをお聞かせいただければと思います。","respondent":"松嶋交通安全担当課長","answer":"しかしながら、交通量、交通の円滑化を考えたときには、やはりその逆の効果が出てしまうということがありますので、そういった交通量だとか、歩行者の量、そういったもの、いろいろなもの、全体的なものを検討しながら、設置していきたいということで考えております。","voiceIndex":244,"id":"exchange-108"},{"speaker":"阿部委員","kind":"質問","question":"頭の中にはあるけれども、言えないということでしょうか。交通量というのは一つの検討の中でのネックといいますか、課題になるかとは思うんですけれども、そこで、交通政策全般についてお伺いしたいのですが、やはり交通量を減らすこともある程度考えていかなければいけない。その場合にはどのように展開されているかということも教えてください。","respondent":"松嶋交通安全担当課長","answer":"その中身の内容も含めて、そういった検討を実施しているところでございまして、まだ、具体的には決まったわけではございません。続きまして、公共交通への乗りかえというご質問です。","voiceIndex":246,"id":"exchange-109"},{"speaker":"阿部委員","kind":"質問","question":"このたび、またバックヤードを少し工事するという話なんですけれども、例えばこれに合わせてバックヤードツアーができるような形に持っていくとか、バックヤードツアー、あるいは、今水族館では、夜、子どもたちが寝袋で泊まり込みながら、夜の水族館の様子、魚の様子を見るなどということも結構広がってきましたけれども、そういった方向ではお考えはありますでしょうか。","respondent":"藤田道路公園課長","answer":"そういった中で、私どものしながわ水族館では、なかなかちょっと、設備的なこともありまして、厳しい面もあります。営業面としてはさまざまな検討をしていくべきだとは考えてありますので、よろしくお願いいたします。","voiceIndex":248,"id":"exchange-110"},{"speaker":"阿部委員","kind":"質問","question":"水族館について、さらに、先日、歳入のところだったでしょうか、水族館、区がお金を出し、それからサンシャインシティのほうは魚の世話は得意なんだけれども、なかなか、営業というところでは、まだ足りない部分があるというようなお話がちょっとあったかと思います。すぐに、はい、では、という話ではないと思うんですが、お考えといいますか、ご感想だけでも構いませんので、お願いいたします。","respondent":"田中総務部長、藤田道路公園課長","answer":"ただ、何をどのように働いていただくか、何を区として求めていくか、ここは大事でございまして、その辺を見定めた上で、いろいろな採用形態は今後あり得るというふうに思ってあります。ぜひ私が営業マンとして頑張っていきたいというふうに考えてあります。","voiceIndex":250,"id":"exchange-111"},{"speaker":"阿部委員","kind":"質問・要望","question":"確かに課長、ウーパールーパーの件とか頑張っていただいて、大変いいなと考えています。今後とも頑張ってください。最後、１分間になってしまったので、要望で終わるかもしれませんが、２８５ページ、子ども達の公園づくり。要望と思ったんですが、１４秒あるので、一言お願いします。","respondent":"松代管理工事課長","answer":"今の委員からの提案、前向きに受け入れて、進めていきたいと思います。","voiceIndex":253,"id":"exchange-112"},{"speaker":"安藤委員","kind":"質問・要望","question":"大崎地域などでもこれだけ多くの土地が、例えば公園やスポーツを興じられるようなところになったら、どれだけの人が喜ぶだろうかと思いながら、私、自転車を走らせているんですけれども、そういったところで、先般、区議会でも文化スポーツ条例もできたことですし、この再開発でこれ以上スポーツ環境が奪われることになってしまっては、非常に、地域の方々にとっても。","respondent":"青木都市開発課長","answer":"さりとてそれをスポーツ施設というかどうか、あるいは区が区民の皆様に提供すべきサービスであるかどうかという点は、またいろいろな議論があろうかと思います。時間がないので、結論から言いますと、再開発事業でそれを面倒見るということは考えておりません。","voiceIndex":256,"id":"exchange-113"},{"speaker":"安藤委員","kind":"質問・要望","question":"再開発地域の中でという狭い意味だけではなくて、この区内、青空野球場の問題もありますけれども、やはりどんどんスポーツができる環境が奪われつつあると思いますので、この区内全般の、施策の全般の方向としまして、この地域ではそういうことも起こってしまったということもありますので、施策全般で前向きに検討していただきたいと思うんですが、いかがでしょうか。","respondent":"日下部企画財政課長","answer":"そういうことも含めまして、十分にご理解をいただきたいというふうに思います。","voiceIndex":258,"id":"exchange-114"},{"speaker":"安藤委員","kind":"質問・要望","question":"このフットサル場を利用している若い人からすると、突然会場がなくなってしまうということを聞いたら多分びっくりすると思うんですけれども、ここの分野でも、若者も含めて、あるいは地域を利用している方々、長年住んできた方々というのを、生活者の方をとにかく巻き込んで、このまちづくりはどうあるべきなのかということを総合的に進めていくという姿勢が。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":260,"id":"exchange-115"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、１９階建てのマンションが、ほぼ外側はでき上がっています。聞いてください。１つ目。「７カ月になる子どもがいます。それも今さらあきらめるというか、小山駅周辺まちづくりの方針がそのように動いているのだから、１人がどう思うか。助けてほしいと思っているんですが、この被害状況、風害による被害状況を区はつかんでいらっしゃるのか。ぜひ対策を立てていただきたいと思いますが、いかがでしょうか。","respondent":"伊勢住環境整備担当課長","answer":"ランク３としまして事務所街程度と、この辺で許容されるというところがあるんですが、現況では大体住宅街程度で許されるというところだったんですけれども、建物が建ったときには、ランク２が３カ所ぐらいと、それからランク３が１カ所、それから植栽。","voiceIndex":265,"id":"exchange-116"},{"speaker":"飯沼委員","kind":"質問","question":"対策は植栽しかないのでしょうか。私はこのところを本当に何とかしてほしい。やはり不備であるという、ここのところが問題であると思うんですが、私はぜひこの風害の規制をつくってほしいなと思っています。８ｍ道路に６０ｍも、１９階の建物がこの品川区内にあるんでしょうか。こういった面では、ぜひ、この現にあらわれている風害を解決しなければ、私、開発には行かないと思うんですが、いかがでしょうか。","respondent":"齋藤住宅課長","answer":"いろいろ計算しまして、過去数十年間の、台風の日もあれば、風速１０ｍ、２０ｍの春一番の日もある。こういったものをいろいろシミュレーションして、風環境影響評価をして、１ランク、２ランク、３ランク、これは一般の自然現象。有楽町でも、五反田でも、大崎でもある。","voiceIndex":267,"id":"exchange-117"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはりそういう事象が、現在今住んでいるまち、この品川区で起こっているというところをしっかりと受けとめてほしいし、私は、きょう、この３－６－Ｂの関係だけじゃなくて、区内あちこちで風の害、一般的には風害と言っていると思うんですが、このことがあちこちで起こっていると思うんです。この対策を立ててほしい、このことを求めているので、再度ご答弁をよろしくお願いいたします。","respondent":"齋藤住宅課長","answer":"お一人の方、なぜか、３－６－Ｂのビルの影響で転ばれたというようなお話でしたけれども、その辺がビルの果たして影響なのか、こういったことの証明もなかなか難しいのは事実ですが、それは、基本的には評価から見ても、科学的に考えて。","voiceIndex":269,"id":"exchange-118"},{"speaker":"飯沼委員","kind":"提案","question":"今課長がおっしゃったとおり、被害者の方、本当に私は被害者だと思うんです。私は、ちょっと提案をしたいんですが、風害が起きたときに、現状で風害の証明を被害者である人が証明をしなければならないとなっていますが、ぜひ、区と事業者の間の事前協議というものがありますが、その中で事業者側がその証明をする。こういった中身に変えていただきたい。私はこう思っていますが、この点はいかがでしょうか。","respondent":"齋藤住宅課長","answer":"今回、３－６－Ｂにつきましても、風影響評価までして、事業者の方が風害に当たるものはないということを説明されたわけですから、むしろそれは違うんだということは、ご主張される方がご主張されないと、これはかみ合わないものだというふうに考えております。","voiceIndex":271,"id":"exchange-119"},{"speaker":"飯沼委員","kind":"質問・要望","question":"何か寒気が立つようなご答弁でございました。武蔵小山駅周辺の整備計画のところの、さっき報告をいただいたんですが、私は、１９階建てが今１カ所で建っているわけですが、今後の計画において、ぜひ地域の方にアンケート結果を返していただきたいのと、地権者だけではなく、地域の総意でまちづくりを進める、そういった仕組みをつくっていただきたいんですが、いかがでしょうか。","respondent":"岩田まちづくり事業部長","answer":"しゃれ街の計画をよく見ていただければ、多少高さを、容積をとるために高く建物は建てますけれども、空地、道路、こういったいわゆる都市環境をきちんと造成していくという前提の計画になっているという、総合的な判断をしていただければ幸いです。","voiceIndex":273,"id":"exchange-120"},{"speaker":"飯沼委員","kind":"質問・要望","question":"木造密集の解決は当然ですけれども、高層化にすり変えないでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":275,"id":"exchange-121"},{"speaker":"山路委員","kind":"質問・要望","question":"２６５ページ、交通安全対策について、２点目は２７３ページ、歩道空間等改善方策検討委託について、時間があったら、２６９ページ、天王洲内部護岸街路灯工事について、お伺いをいたします。第１点目は、モノレール天王洲アイル駅下交差点の歩行者の安全確保について、お伺いをいたします。","respondent":"松嶋交通安全担当課長","answer":"そこで、今の段階では、左折と歩行者の分離はされておりません。したがいまして、ここは、一番安全を確保するためには、歩車分離が必要なのかなと、そのように考えております。","voiceIndex":277,"id":"exchange-122"},{"speaker":"山路委員","kind":"質問・要望","question":"歩車分離といいますと、歩行者の安全を確保するには、例えばどういう方式があるか、お聞かせいただきたいと思います。","respondent":"松嶋交通安全担当課長","answer":"歩車分離には４つの方式があります。ここの交差点で取り入れる可能性があるのは、右左折車との分離が必要になろうかと思います。要は、右折、左折の車が行っているときには、歩行者は止まっている状態。","voiceIndex":279,"id":"exchange-123"},{"speaker":"山路委員","kind":"質問","question":"ぜひ、実現しますように、よろしくお願いいたします。では、次に、歩道空間等改善方策検討委託について、説明で、八ツ山通り、元なぎさ通りとありましたが、具体的にどういう検討をされるのか、お伺いをいたします。","respondent":"松代管理工事課長","answer":"これ、八ツ山通りおよび元なぎさ通り、約２.３kmありますけれども、そこは都市計画道路に位置づけられているというようなことも含めまして、さまざまな課題があります。その課題をきちんと整理しまして、今後の整備方策を検討するものです。","voiceIndex":283,"id":"exchange-124"},{"speaker":"山路委員","kind":"質問","question":"以前、私も北品川橋の周辺の、人と人がすれ違うのにあまりにも狭過ぎると、道路の拡幅をお願いして、品川区の単独で３０cmぐらいまでは延ばせるかなというお話を、ご答弁をお伺いしたことがあるんですが、その辺についても今回の検討では入るのかどうか、お伺いいたします。","respondent":"松代管理工事課長","answer":"そういったことも含めまして、抜本的にこの都市計画道路、きちんと課題を整理して、今委員からご指摘があった部分も含めまして、整備を進めるべく検討していきたいと、このように考えているところです。","voiceIndex":285,"id":"exchange-125"},{"speaker":"山路委員","kind":"提案","question":"この道には、八ツ山通りの東のほうには船宿通りがありまして、西のほうには旧東海道がありまして、これから観光拠点の中心として非常に重要な道路ではないかと、１０年ぐらい前から私もいろいろな形で提案、要望させていただいてきたわけなんですが、北品川橋周辺、陥没というんですか、少しへっ込んだところもありますね。","respondent":"松代管理工事課長","answer":"その基本的なところでの都市計画道路の位置づけ、そういったものを、諸課題を含めて、今後どう詰めていけばいいのか、そういったものを検討していきたいと、このように考えているところです。","voiceIndex":287,"id":"exchange-126"},{"speaker":"山路委員","kind":"意見","question":"地元住民の方も大変期待をいたしておりますので、よろしくお願いします。先ほど、元なぎさと八ツ山通りに点字ブロックを設置する予定があるとか、ちょっと聞いたような気がするんですが、どの辺に設置をされるのか、お聞かせください。","respondent":"松代管理工事課長","answer":"これも、先ほど、今後の計画の一つとしてお話をしましたが、当然のことながら先行してやるべきことではなく、今後の検討課題の中の一つの候補として、これも含めて検討してまいりたいと考えています。","voiceIndex":289,"id":"exchange-127"},{"speaker":"山路委員","kind":"質問・要望","question":"バリアフリー、あるいはユニバーサルデザインという、妊婦の方も、高齢者の方も、お子さんも、外国の方も、だれでも通れるようなすばらしいこの地域の道路整備を期待しておりますので、どうぞよろしくお願いいたします。では、続きまして、時間が少しありますので、天王洲内部護岸街路灯工事について、どのような工事をやられるか、お聞かせいただきたいと思います。","respondent":"藤田道路公園課長","answer":"これについて、港湾局がきちんと今回整備をするということでお話をしています。その中で、街路灯といいますか、照明設備、これについては港湾局のほうでは整備ができないということで、これを区が行うと、あわせもって、区民の皆さんに開放していこうです。","voiceIndex":291,"id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"２６７ページの道路維持費、２８３ページの公園用地借料、２９１ページ、避難道路機能強化事業。滝王子通りの件。それらを指導していただきたい。しかも、キャラクターがたくさんついておりまして、非常に着用率が高いですから、そういうことも含めると、まだされていない方には周知徹底をして、危険を回避するというような指導を徹底していただきたいと思いますが、そのお考えをお聞きしたいと思います。","respondent":"藤田道路公園課長、伊勢住環境整備担当課長、松嶋交通安全担当課長","answer":"これが現在の主流の舗装ですが、アスファルト舗装、やられているところを見たことがあると思いますけれども、とろっとしたような形でまず出てきて。一方、この滝王子通り、こういう道路拡幅を契機にして、そこのまちが活性化できるかどうかということもありますので、その辺を見ながら協議会。委員、今回３人乗りが緩和されたということだったんですけれども、誤ってはいけないのは、これは検討に入ったというだけで、まだ緩和されていない。","voiceIndex":294,"id":"exchange-129"},{"speaker":"西本委員","kind":"質問・要望","question":"この辺を、震災があったときも含めて、道路のどういう形状にしていったらいいのかというような考えがあるのかどうか、お聞きしたいと思います。ですから、まちづくり検討会等々、これから発足する可能性もあるということですので、もう少し広い意味での、あの地域の商店街含めてどういうまちをつくっていったらいいかという視点の中で、構想を立てていっていただきたいなと思っています。","respondent":"藤田道路公園課長、伊勢住環境整備担当課長","answer":"公園のほうの賃借の関係ですけれども、現在も、例えば神社ですとか、そういったところからは土地をお借りして、公園にしているところ、こういったところもありますので、そういうお話があれば。地区計画の関係ですけれども、この防災街区整備地区計画というのは、間口だとか、高さの制限だとか、道路の幅員だとか、こういうものを定めるもので。","voiceIndex":298,"id":"exchange-130"},{"speaker":"松澤委員","kind":"質問","question":"６項目でしょうか、いろいろ事業が書かれております。予算ですので、これがどんなところでどういうふうに使われているのか。例えば建替助成金でしたら、何丁目を何棟やるんだとか、広場整備でしたらどこの広場とか、用地取得費は何丁目のところを買うんですとか、お話を伺いたいと思います。用地取得費。これも何丁目のどの辺を用地取得するのか、この辺についてお聞きしたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"これ、最近は実例があまりないわけなんですが、見込みとして、具体的なものはないんですが、あったときに対応できるようにということで予算化しています。それから、建築資金利子補給金につきましては、過年度からの継続分です。それから、広場整備等工事費。","voiceIndex":302,"id":"exchange-131"},{"speaker":"松澤委員","kind":"質問","question":"たしか５年ぐらい前ですか、中延五丁目に、あれは銭湯の跡地を買って公園にしたら、ワーストから消えましたので、そんな意味ではいろいろな道路の拡幅とか、２項道路整備とかある中で、防災広場、公園を整備するというのが一番の大きなもとかなと思うんですけれども、もしこれが整備されれば、危険度というのは減るんでしょうか。その辺をちょっとお聞きしたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"公園を整備すると危険度が減るかということですけれども、基本的には空地、密集事業の場合は不燃領域率といっていまして、建物の耐火性と、それから空地性をあわせた指標ですけれども、基本的に大きな空地ができますので、その分減るということですけれども。","voiceIndex":304,"id":"exchange-132"},{"speaker":"松澤委員","kind":"質問・要望","question":"やはり火災危険度をなくすには、消防自動車が入れないような、のんき通りの拡幅なんかはぜひ必要ということで、予算計上されていますけれども、あとは、何回か委員も質問していますけれども、２項道路の整備ですね。それと、広場の整備。そんな中で、ワースト１位の豊町五丁目とワースト３位の二葉三丁目、ここで広場の獲得ができていない。","respondent":"伊勢住環境整備担当課長","answer":"用地取得の場合、密集事業の場合は国の補助金が２分の１、それから都の補助金が４分の１、残りの４分の１が区の負担になるわけですが、これの、年にもよりますけれども、財調の対象になっているです。地区外はゼロです。","voiceIndex":306,"id":"exchange-133"},{"speaker":"松澤委員","kind":"確認","question":"そうしますと、網がかかっている部分では、国が２分の１、残りの２分の１の半分が都、その残りの４分の１が品川区だけれども、これは財調で補てんされるからゼロ。ほかの地域で公園をつくりたい、防災広場といった場合、すべて自主財源で、補助金が全く入らないということでしょうか。確認をしたいと思います。","respondent":"日下部企画財政課長","answer":"網がかかっていないところにつきましては、実は都市計画公園として、１ｈａ以上であれば、これが都市計画交付金の交付対象になります。ということで、財源的にも、それ以外の部分は財調での手当てもされますので、負担はないと。","voiceIndex":308,"id":"exchange-134"},{"speaker":"松澤委員","kind":"質問","question":"当然要件があると思うんですね、何ヘクタールなくてはいけない。あるいは、木賃住宅がどのぐらい混在していなくてはいけない。この要件の緩和ということはおかしいかもしれないけれども、ほかに、これ以外にこの要件にかなう地域、品川区内にあるんでしょうか。まだまだ火災の危険度が多いところがあるんですが、その辺の調査はどのようにしているんでしょうか。","respondent":"伊勢住環境整備担当課長","answer":"密集事業が始まる前に整備計画等をつくるんですけれども、そういうところで、建物の老朽化率が何％だとか、いろいろ細かい基準がございまして、そういうのをクリアすると、国、都の承認を得て事業を開始するんですけれども、ほかの、区でそういう調査をしてございませんので。","voiceIndex":310,"id":"exchange-135"},{"speaker":"松澤委員","kind":"質問","question":"これを見ましても、５年前と比べて、建物倒壊の危険性が１７％減った。延焼率も１４％減った。そんな危険性もあるので、何とか品川区内にある残りの危険地域を何とかしたいという、そのような思いの中で、当然区の皆さん、いろいろな補助金を引っ張る努力をしているんでしょうけれども、ほかに何か考えられることはないんでしょうか。お願いいたします。","respondent":"伊勢住環境整備担当課長、片田建築課長","answer":"４月からスタートします耐震改修だけじゃなくて、耐震建て替え、これも大きな形で、建て替わってくれば不燃化も進むというようなことで、さまざま、あるいは地域によって地区計画をつくって、戸越一丁目みたいな街並み誘導型のもので。特に耐震化の話についても、これまで整備地域を、改修については区内全域に一応拡大していきたいと、そういう中で、国の補助金等々についても導入してくるといったような考え方を持ってありますので、ぜひいろいろな制度を活用して。","voiceIndex":312,"id":"exchange-136"},{"speaker":"松澤委員","kind":"質問・要望","question":"この密集市街地でやれるのも期間があるものですから、やはりゼロと、満額補助があるのでは、まるっきり違いますので、できるだけ防災広場をつくるように努力していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":315,"id":"exchange-137"},{"speaker":"須貝委員","kind":"質問","question":"私は、主に２９３ページ、住宅・建築物耐震化支援事業としてお聞きします。現在、品川区では、この建築物耐震化支援事業のほかに、都市防災不燃化促進事業、密集住宅市街地整備促進事業、そして防災生活圏促進事業がある、で、今お話もお聞きしましたが、なぜ実施しなければならないのか。基本的なところで、教えてください。そして、住宅に関して、改修工事と建替工事、２通りがあると思います。","respondent":"片田建築課長","answer":"耐震化の事業の実施の考え方ですけれども、基本的には、一昨年、国のほうの方針が出されまして、促進計画、なかなか、阪神淡路大震災以降、耐震化がなされていないという話の中で、都道府県としては促進計画をつくらなければいけないと、設置義務が出てきました。","voiceIndex":317,"id":"exchange-138"},{"speaker":"須貝委員","kind":"意見","question":"今お話がありましたとおり、建て替えのほうが、私としても、いろいろ、二葉町等視察してまいりましたが、建物同士で挟まれた道幅が６０cmしかない。そういう道幅のところもあります。住宅同士の間隔が本当に５０cm以下。３０年待つのか、４０年待つのか、そういう状況にもなるかと思うんですが、その辺に、スピードアップするためにどのような対策をお考えなのか、簡単でいいんですが、お聞かせください。","respondent":"片田建築課長","answer":"ただ、その中の２割ぐらいの方は、何らかの補強をし始めてきているといったような状況も、これについては促進計画の中で説明させていただいてありますけれども、そんな状況を踏まえながら、区のほうとしても、やはりこの事業を区民の方にわかりやすく。","voiceIndex":319,"id":"exchange-139"},{"speaker":"須貝委員","kind":"質問","question":"細街路のまま。そして、家と家の間隔は本当に狭いままで、果たしてそれが終わったときには、では、防災上どうなんだというような問題、耐震は何とか処理は終わったとしても、防災上どうなんだと。それで、先ほどお話がありましたが、借上型区民住宅などに空き室があり、埋まらないで空き室住宅費を年間５,０００万円以上も払っていると、先ほどお話をお聞きしました。その辺について、お聞かせください。","respondent":"片田建築課長、齋藤住宅課長","answer":"確かに密集事業等々でそういうものを検討できるところもあろうかなと思ってありますけれども、これについては住宅関係の部署とも十分協議をした中で、ちょっと検討させていただきたいと思います。極めて安い金利で、１,０００万円を上限にお貸ししております。借上型区民住宅の目的の転用ですが、これは制度上、私どももさまざまなことを考えておりますが、なかなかそういう短期で転用ができない。","voiceIndex":321,"id":"exchange-140"},{"speaker":"堺委員","kind":"提案","question":"最初に、２６９ページの街路灯の建替１５０基。私も平成１２年のときに、この街路灯については、高圧ナトリウムに改善したらどうかと。それから、あわせまして、２点目お尋ねをさせていただきたいんですが、街路灯につきまして、平成１８年の予算特別委員会のときに、我が党委員より防犯という視点で、非常に効果のある青色防犯灯というんですか、この辺について設置推進方、提案をさせていただきました。","respondent":"藤田道路公園課長","answer":"ＣＯ２の削減量は１０ｔということで、お話ししているとおりなんですけれども、削減なんですけれども、これ、なかなかちょっと計算が難しいんですけれども、おおむね、電気料金として今回の建替えで６０万円ほどの金額の減になっていくと。","voiceIndex":325,"id":"exchange-141"},{"speaker":"堺委員","kind":"質問・要望","question":"今回どの程度これについては、計画としては拡幅をされるのか、確認をしておきたいと思うんですが、当時は、左右それぞれ約７０cm、ですから、両方合わせると１.４ｍ拡幅ができると、こういうご説明をいただいているんですが、その辺についてもう一回教えていただけますでしょうか。","respondent":"松代管理工事課長","answer":"拡幅の幅員の方ですけれども、現状が約３.８ｍほどあります。それを何とか２ｍほど広げたいと思って、今交渉等を細部にわたって詰めております。おおむね両側に１ｍぐらいの拡幅ができるものと考えているところです。","voiceIndex":327,"id":"exchange-142"},{"speaker":"堺委員","kind":"質問・要望","question":"もう一点は、先ほど申し上げた平成１６年５月下旬に５つの団体から陳情を出させていただきましたけれども、そういう面で、その当時の関係者も含めまして、この当時のそういうものに携わったといいましょうか、近隣も含めまして、この工事につきましていつごろから始まって、いつごろ終わってどうのこうのという、その辺についてもきちんと周知方、徹底も必要かと思いますので。","respondent":"松代管理工事課長","answer":"ですから、ＪＲとも今後詳細を詰めまして、ＪＲに委託をして、ＪＲが工事はするんですけれども、そういう周知は我々も一緒になって、周辺の方々にきちんとお知らせしながら、進めたいと考えています。","voiceIndex":329,"id":"exchange-143"},{"speaker":"堺委員","kind":"提案","question":"３点目について、子ども達による基本構想策定記念公園づくり、これについては、先般の総務費だったでしょうか、長期基本計画策定の際の審査のときにも、子どもたちが見てもわかるような、イラスト入りというか、漫画入りといいましょうか、そういう形のものも長期基本計画の中で策定をしてほしいという提案をさせていただきました。あるいは選出方法ですね。","respondent":"松代管理工事課長","answer":"基本的には、まだ何も決まってございません。方針としましては、今から考えていきたいと。きょうのこの委員会でもいろいろとご提案をいただきました。そういったものも含めまして、考えていきたいと考えています。","voiceIndex":331,"id":"exchange-144"},{"speaker":"堺委員","kind":"質問","question":"これからですので、それで、最後にこの件について、大体素案というんですか、これはいつごろまでにまとめたいというふうに思っていらっしゃるのか。その辺、ちょっと、最後にお聞かせいただければと思います。","respondent":"松代管理工事課長","answer":"今おっしゃった構想という段階、それもなるべく早い形で積み上げて、次のステップにつなげていきたいと、このように考えているところです。","voiceIndex":333,"id":"exchange-145"},{"speaker":"須藤委員","kind":"質問","question":"２６４ページ、土木費について、この項が６項目挙げられていますけれども、項はこの６項目だけしかないのか、国のほうに出すときに、まだほかの項というのはつくっていいのかどうか、それを教えてください。","respondent":"日下部企画財政課長","answer":"この項につきましては、これは追加をするということも可能です。","voiceIndex":336,"id":"exchange-146"},{"speaker":"須藤委員","kind":"質問","question":"何でそんなことを聞いたかというと、非常に事業が多岐にわたってくるので、分けられたほうがいいかと思うのが出てくるのではないかなと思ったので。それから、もう一つ、建築費の建築行政費だけが、建築総務費ではなくて、上がってきているので、この辺は何で建築行政費となっているのか、そのあたりを教えてください。","respondent":"日下部企画財政課長","answer":"今後、その辺はいろいろ工夫いたしますけれども、ある程度基本線は踏まえつつ、より議会でもご理解いただきやすい、理解されやすいような、そういう形で工夫はしてまいりたいと、このように考えております。","voiceIndex":338,"id":"exchange-147"},{"speaker":"須藤委員","kind":"質問","question":"土木費に関連すると、いわゆる総務費に入ってくる職員住宅であるとか、それから教育費であれば学校の改築だとか、そういうのも土木というか、建てますよという、いわゆる後で財産として残りますよという絵になってくるので、行政評価のときにはこの予算書を使わないで、また別にその辺を全部リストアップして、行政評価としてつくっていくんですか。","respondent":"堀越行財政改革担当課長","answer":"成果をどういうふうに見るか、行政評価の部分ですけれども、今ちょっといろいろ予算の会計の科目のお話がありましたけれども、いろいろ、どういう形で行くかというのはこれから、長期基本計画の検討にあわせて検討していきたいと、今そういう状況です。","voiceIndex":340,"id":"exchange-148"},{"speaker":"須藤委員","kind":"質問","question":"あるいは、総務費に入りますと来るので、今度それを僕らがやるときには、それをもう一回引き出して、足し算しなければいけないのかなと思ったので、そういう見方をするようになるんだなというふうに思っているんだけれども、それでいいかどうかということ。それから、これと関連して、風のみちという考え方、前にやったと思うんだけれども、それとの連動はどうなっているか教えてください。","respondent":"日下部企画財政課長、松代管理工事課長、青木都市開発課長","answer":"これが、企業会計だと思うんですが、企業会計でのバランスシートになりますと、これが一つの資産としてそれぞれ、中身にもよりますけれども、一定。涼のみちの整備事業ですけれども、平成２０年度も計画的に進めていきたいと思っているところですけれども、これは都市のヒートアイランド対策の一環として。風のみちというのは、特に品川区内でいいますと、大崎駅周辺のまちづくりを進めていく上で、目黒川を活用して風の道を確保していこうと。","voiceIndex":342,"id":"exchange-149"},{"speaker":"須藤委員","kind":"質問","question":"そういったところと、それから涼のみちというのをドッキングして、本当にクールダウンさせるような絵というのが、涼のみちをつくるにしても、そういった全体的な視野をやっていかれたらと思うので、最初のころは試作的にやるということで、そういうふうに理解したんだけれども、ある程度それがいいことになってきたら。","respondent":"松代管理工事課長","answer":"今、委員がおっしゃったような視点で、そのようなところを取り入れていく、また環境基本計画等がありますけれども、そういったものとあわせて環境面で何か、総合的に考えていく、そういったものを今後検討してまいります。","voiceIndex":346,"id":"exchange-150"},{"speaker":"須藤委員","kind":"質問","question":"あと２点ほど。２８３ページの公園用地借料、９９０万円は、どこなのか。それから、２７９ページ、橋梁点検委託はどのぐらいの数があるのか、わかったら教えてください。","respondent":"藤田道路公園課長、松代管理工事課長","answer":"公園用地の借料のところですけれども、東急池上線のふたかけの上につくった公園の一部の土地の借料をお支払いしているものです。橋梁の点検ですけれども、対象橋梁は５７橋ございまして、横断歩道橋も含んで、この５７橋を調査したいと考えているところです。","voiceIndex":348,"id":"exchange-151"},{"speaker":"川西委員","kind":"質問","question":"最初に、２７３ページ、細街路拡幅整備。次は、中高層建築指導要綱に関連して、次は公園の管理、２８３ページ。細街路拡幅に関連してですが、これは公共溝渠の拡幅の範囲もこの予算の中でいいんですか。私、公共溝渠の細街路拡幅の中身を、平成２０年度の計画を知りたいのですが、いかがでしょうか。","respondent":"片田建築課長","answer":"ただ、細街路の中でも、私道、公の道路も含めて、一応４ｍ未満のものを第４２条の２項道路といったような扱い方をしている。その扱いをされたものについて、建て替えについて支援しながら拡幅をしていきたいという考えに基づいているものです。","voiceIndex":352,"id":"exchange-152"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、公共溝渠のことはどこで伺ったらよろしいんでしょうか。公共溝渠の平成２０年度の計画について伺いたいんです。","respondent":"松代管理工事課長","answer":"公共溝渠の関連ですけれども、こちらはもともとは水路だったものを公共溝渠として管理しているものでございまして、現在１５５路線ほどあります。そういったものを適正な管理ということで、払い下げ、もしくは今不法占拠されているものをきちんと適正化する。","voiceIndex":354,"id":"exchange-153"},{"speaker":"川西委員","kind":"質問","question":"予算書の何ページか、後の答弁のときに教えてください。ちょっと見当たらなかったものですから。実は、南品川四丁目から、碑文谷街道から目黒川に通じる公共溝渠の計画がどのようになっているか。おわかりですよね。森井電業の跡が首都高速中央環状品川線の換気所の予定地になっていまして、森井電業も公共溝渠に一部入っていました。その関係で、処理が進んでいるのかなと思いますので、聞かせてください。","respondent":"松代管理工事課長、藤田道路公園課長","answer":"そこの発進立坑みたいな形で工事で使われておりますので、その工事が終わった後、上空の整備の一部に公共溝渠のところも、将来、通路、緑道として整備される、そういう計画です。今のところは、現在工事ヤードとして使っているものです。予算書上の部分ですけれども、実際には公共溝渠、今維持管理、お掃除だとかそういったものが中心になってありますので、２８１ページの河川維持費、その中の維持補修工事費等ということで。","voiceIndex":356,"id":"exchange-154"},{"speaker":"川西委員","kind":"質問・要望","question":"そうしますと、今借りているのが企業とか、お金は払っていると思いますけれども、そういうところですから、もしかしたら、区の進め方によっては、買収というんですか、買い取る立場におありになるのではないかと思います。ですから、今後、換気口の、東京都の関係もありますけれども、この進みぐあいによって、適正な売却なり、活用なりということをぜひ早期に考えていただきたいと思います。次に移ります。","respondent":"齋藤住宅課長","answer":"せっかくの委員のご質問ですが、私、条例化を考えているなどということを建築紛争の現場で言った記憶はございませんが、すいません。恐縮です。","voiceIndex":359,"id":"exchange-155"},{"speaker":"川西委員","kind":"質問","question":"行ったり来たりになりますから。それで、お話し合いの中で、今の時代ですから絶対反対ということはないんですね。管理人をどういうふうに配置するか、あるいはごみの問題をどう処理するか、そういうような話が多いわけです。ですから、そのときにおっしゃったのは、今は２０戸以上でどうのこうですけれども、３０戸以上に変えるかもしれないなんておっしゃいませんでしたか。","respondent":"齋藤住宅課長","answer":"大変失礼いたしました。私、聞き間違いをいたしました。ワンルームマンションのことについての建築紛争で、ワンルームマンションについて建築の規制を新たに強化しないかと、こういうことで、強化いたしました。建設委員会でもご報告いたしまして、４月１日から変更になります。","voiceIndex":361,"id":"exchange-156"},{"speaker":"川西委員","kind":"質問","question":"建設委員会にいなかったので、勉強不足、まことにすいません。それで、結局そういうことですね。次に、公園の管理に関連して伺います。人工ではなくて、芝生のあるところの養生とか管理をどういうふうにされているか。そういうので、柵をつくったりいろいろ管理されているでしょう。柵をつくっているところと、つくっていないところと、どんなふうに、砂場についての住民の声からああしたんですか、伺います。","respondent":"藤田道路公園課長","answer":"もう一つはネットをかけるという手法で対応しています。これは、地域の方々に意見を聞いて、どうしてもおりの中で子どもが遊んでいるというような雰囲気に見えないわけでもないので、よくご意見を聞きながら、どういった対応をとるかお話をして、進めているところです。","voiceIndex":363,"id":"exchange-157"},{"speaker":"川西委員","kind":"意見","question":"今の公園のほうの砂場のことなんですけれども、難しいですね、砂場の管理は。本当に、私、柵の中で遊ばせているのかと、ちょっと遠くのほうの公園のことで言われたことがあって、困ったもんだねということを話したことがあります。今後とも努力されることを希望します。それから、芝生管理なんですけれども、３カ月休ませるとか、２カ月休ませるとか、そういう管理はしていらっしゃるんですよね。","respondent":"藤田道路公園課長","answer":"中央公園のほうについては３カ所の芝がありますので、それぞれ順番に休憩時間を設けてあります。","voiceIndex":365,"id":"exchange-158"},{"speaker":"中塚委員","kind":"質問","question":"私からは、２８９ページ、大井町駅周辺地区街づくり構想策定業務委託について、伺いたいと思います。どういう構想なのかご説明ください。それと、冒頭に新規事業と説明がありましたけれども、昨年までの広町地区開発計画の検討委託との関係は何かあるのか、ご説明ください。","respondent":"青木都市開発課長","answer":"これまで進めてきました広町における開発構想検討との関連性ですけれども、これにつきましては、広町の検討につきましては、決算特別委員会でもご報告申し上げまして、それに関連しまして第４回定例会に関連する所管の常任委員会でも簡単にご報告しておりますけれども。","voiceIndex":368,"id":"exchange-159"},{"speaker":"中塚委員","kind":"質問","question":"広町地区のときは、負担がＪＲとの折半という話があったんですけれども、今回は、全額区負担ということなのか。負担の参加企業みたいなものがあるのか、ないのか、教えてください。それと、構想の範囲なんですけれども、冒頭説明がありましたけれども、何ヘクタールと言ったらいいのか、どこからどこまでと言ったらいいのか、その範囲を教えてください。","respondent":"青木都市開発課長","answer":"それで、広町地区というところになってくるわけで、広町については、今までの検討してきた成果を踏まえた上で、検討を進めていくというようなところ、大体その辺をイメージしております。","voiceIndex":370,"id":"exchange-160"},{"speaker":"中塚委員","kind":"質問","question":"それと、この構想ですけれども、品川区はどんな絵を描いているのか少し伺いたいと思うんですけれども、例えば基本構想の中では国際都市品川というフレーズもありますけれども、これとつながるものなのかどうか、ご説明ください。区の予算でという話でしたけれども、国や東京都などの上位計画というものがあるのか、ないのか、教えてください。","respondent":"青木都市開発課長","answer":"事業費ですけれども、事業費につきましては、これ、ちょっと勘違いされていると困るんですが、あくまでもまちづくりの構想、区民の皆様とどういう町にしていきたいかという考え方、ビジョンを共有していくための報告書というか。","voiceIndex":372,"id":"exchange-161"},{"speaker":"中塚委員","kind":"質問","question":"上位計画のお話で、東京都の計画とありましたけれども、どんな計画なのか教えてください。それと、この構想の、大井町周辺の行政需要についてですけれども、今一つ、どんな絵を描いているのかよくわからないんです。どのような需要を、どのような調査で、どんな絵を、大井町をつくっていきたいと思っているのか、何か具体的にあるのか、ないのか、教えください。","respondent":"青木都市開発課長","answer":"行政需要とか、あるいはどんなようなまちづくりにしたいのかということですけれども、これはまさにこれから区民の皆様と共有していきたいということで、具体的なものがあるわけではないんですが、強いて言えば、市街地整備基本方針というものを私ども。","voiceIndex":374,"id":"exchange-162"},{"speaker":"中塚委員","kind":"質問・要望","question":"大崎がものづくりで、大井町はにぎわいというお話がありましたけれども、にぎわいといってもいろいろなにぎわいがあると思うんです。どういうものを描いている。つまり、この構想策定業務委託というのを、何を委託しているのか。今、にぎわいというお話がありましたけれども、どういうにぎわいをイメージしているのか、もう少しそこを詳しく教えていただきたいと思います。","respondent":"青木都市開発課長","answer":"１つには、まず、私ども、まちづくり事業部でやっておりますから、交通需要、あるいは交通処理がどうなっているのかという、まずハード面での把握が必要ですし、あと、やはりにぎわいという視点では、これは所管が違うところになりますけれども、商業の活性化状況、あるいは。","voiceIndex":376,"id":"exchange-163"},{"speaker":"中塚委員","kind":"質問・要望","question":"広町地区開発の際には、民間リサーチ会社に調査を依頼して、去年の１１月２７日の建設委員会でこの調査のことが話題になりましたけれども、そういう形で、この町、何ヘクタールかわからないですけれども、広い地域でどういう行政需要があるのか、何が求められているのか。にぎわいという話だったら、どういうにぎわいをつくっていくのか、そういうのをつかむという、そういうことを考えているのか。","respondent":"青木都市開発課長、齋藤住宅課長","answer":"これは、申しわけございません、広町の構想で検討してきた中での、ある程度の成果という形で把握しているものが、情報として私ども、とらえている中では、大井町は残念ながら山手線の大崎周辺、あるいは。こういったことが期待されておりますので、そういったこれからの大井町の方向性、にぎわいということを考えますと、今回の委託調査は大変意義のあるものになるというふうに考えております。","voiceIndex":378,"id":"exchange-164"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、にぎわいというところで、大井町駅周辺のホテルの建設のご説明がありましたけれども、伺いたいのは、ホテルを大井町に誘導といいますか、引き呼ぶというか、よく開発では誘導という言葉を使うみたいですけれども、区は何を呼び込もうと、このホテルで期待しているのか。その周辺には商業地域もつながると思いますけれども、どういうまちを目指しているのか、教えてください。","respondent":"青木都市開発課長","answer":"今、住宅課長からご紹介しましたのは、現在のニーズに基づいて、大井町が持っているポテンシャルがどんどん変わっていくということをご紹介したものでございまして、これがいいかどうかというのはまた地元の方々の評価があると思いますから、そういったものを私ども行政も。","voiceIndex":381,"id":"exchange-165"},{"speaker":"中塚委員","kind":"意見","question":"最後に、データの提供の話のところだけ１点、１１月２７日の建設委員会では、広町地区のデータ、まちづくり事業部長のほうから、年を明ければ、できるだけ早い時期にきちんと検討結果をご報告しますとご答弁がありましたけれども、いまだかつてまだないんです。そのまま次の事業に移っているわけですけれども、なぜ報告がないのか。なぜ、次の事業にそのまま流れているのか、最後、お聞かせください。","respondent":"青木都市開発課長","answer":"データはそろっておりますので、また、こういったいろいろな場が足りないというのでできていないのだとすれば、またお問い合わせいただければご紹介します。最後になりますけれども、大体、先ほど把握していなかったヘクタール、４０ヘクタールほどということでご理解ください。","voiceIndex":383,"id":"exchange-166"},{"speaker":"三上委員","kind":"質問","question":"先ほど出ておりました２６７ページ、２６９ページ、街路灯の別な角度からの質問。時間があれば、もう少し伺いたいと思います。先に、質問の前に、２８５ページの小山台公園の改修ということで、午前中その話がありましたけれども、この場所というのは、小山台公園、現在ある公園としてなっている場所と限定していいんでしょうか。それとも、都営住宅があったところ、そこまで含んだことをいうのか。","respondent":"松代管理工事課長","answer":"小山台公園の改修は、委員からも今お話がありましたように、現在開園している場所の改修です。現在、小山二丁目２番にあります公園のことです。","voiceIndex":386,"id":"exchange-167"},{"speaker":"三上委員","kind":"質問","question":"駅周辺放置自転車で、４月１日からということで報道されていましたけれども、江戸川区の東京メトロ東西線の葛西駅で、もう大きな駐輪場がつくられるということで、ＩＣタグとカードで自動出し入れするというような、こういう駐輪場がオープンすると、こういう報道がされていますが、そういったことについてご承知であれば、簡単でいいですからお教えいただけますか。","respondent":"松代管理工事課長、松嶋交通安全担当課長","answer":"小山台公園の南側の道路づけの件です。これ、現地を確認させていただきまして、今委員からの内容等、十分把握した上で、検討したいと思います。区内の自転車の事故件数です。平成１９年中、区内では発生件数５０４件。うち負傷者が４５６名。死亡事故については１件、発生をしております。それと、江戸川区の葛西駅の部分です。","voiceIndex":388,"id":"exchange-168"},{"speaker":"三上委員","kind":"提案","question":"小山台公園については、よろしくお願いしたいと思います。なぜならばと言ったならば、今回の道路交通法の自転車の改正によって、今年の、少なくても１年間の猶予があるのか、平成２０年６月１９日までに新しい改正法が施行されるわけですから、このときからは完全に自転車というのは車道を走る、そういう対象物ですよということが明確に位置づけされていますよね。","respondent":"松嶋交通安全担当課長","answer":"これは技術的にできることですので、これから登載内容なんかを検討しながら、登載する方向で実施をしていきたいと考えております。","voiceIndex":391,"id":"exchange-169"},{"speaker":"三上委員","kind":"質問","question":"武蔵小山駅周辺の整備事業について、方針作成に当たって、その整備事業の範囲というのは、どこのところを今お考えになっていらっしゃるんでしょうか。","respondent":"伊勢住環境整備担当課長","answer":"今年度、整備方針の検討をしてございまして、この範囲は５６ｈａでございまして、来年度につきましては基本的には同じようなエリアで考えてあります。","voiceIndex":393,"id":"exchange-170"},{"speaker":"三上委員","kind":"質問","question":"えらい計画ですよね。それで、林試の森という、こういうことが入っていましたけれども、そうなると、これは富士見通りあたりまで入るということですか。","respondent":"伊勢住環境整備担当課長","answer":"富士見通りも入ってあります。","voiceIndex":395,"id":"exchange-171"},{"speaker":"三上委員","kind":"質問","question":"この整備基本方針ということが当然定められていくわけですから、これからこの広いまち中にあって、どういう整備をしていくかということは大事なことになってきますね。そうすると、多少なりとも、ずっとついている街路灯を１つずつ間引きするような形で、１つはセンサー式のものに替えていくとか、こういうことも考えられてもいいのではないかと思いますが、いかがですか。","respondent":"藤田道路公園課長","answer":"そういった中で、あわせもってＣＯ２の削減ですとか、そういったことも当然考えなければいけないと思ってあります。委員ご提案のことも踏まえながら、十分に検討していきたいというふうに考えてあります。","voiceIndex":397,"id":"exchange-172"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"商店街電線類地中化事業、２７５ページか、２８５ページ、公園改修なのか、２７１ページの都市計画道路なのかよくわかりませんが、契約行為というか、どういう考え方でいくか。それから、木造軸組みで十分なわけですから、そこの部分をぜひとらえて考えていただきたいと思うんですけれども、それは、考え方を教えてください。この高さの基準というのはあるのかどうか、そこら辺を教えてください。","respondent":"松代管理工事課長、片田建築課長","answer":"それを事前に私どももきちんと踏まえた上で提案していく、また聞いていく、そういったものを今後十分に検討しながら進めたいと考えているところです。今回、品川のシェルターの支援についても、１月からやってありますけれども、そういうものを対象としてきた経過がありますが、区としても区の独自の補強方法、これの装置、あるいは工法について検討していきたいと。","voiceIndex":400,"id":"exchange-173"},{"speaker":"石田（秀）委員","kind":"質問","question":"干潟はぜひ検討してみていただいて、上からも使える、せっかく品川区の中にあるわけですから、東京都とも少し話をして、保全地区になってしまっているから、ちょっと問題なんだけれども、ぜひ検討していただければなと思います。それは確かに大切なこと。だから、そこら辺の点をどうお考えになって、そういうところとも話しているというなら、話しているで結構なんだけれども、そこをもう一度お聞きしたい。","respondent":"松代管理工事課長、岩田まちづくり事業部長","answer":"これからも、そういった意味では、お互いそういったものを理解し合いながら、進めていきたいと考えています。現在では、国土交通省は、連続点字ブロックについては、視覚障害者と、それから車いすの障害者の団体とよく意見調整をした上で、設置場所を決定するということに。","voiceIndex":403,"id":"exchange-174"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本当に、障害者の方の基準はもちろんわかりますけれども、高齢者の方で、私の知っている方もそれで転んで、顔をこんなにはらした人がいて、確かに、だけれどもお元気で、一生懸命まちを歩いている方なんだけれども、こういうこともあるということをよくご存じだというので、そこら辺のこともぜひ考えながら、またやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":406,"id":"exchange-175"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=902#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":133712,"voices":407}},{"id":"h20-20080312-3","meetingId":"h20-c-budget","date":"2008年3月12日","dateIso":"2008-03-12","committee":"予算特別委員会","time":"午前１０時０２分～午後６時０１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を172件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２０年度品川区一般会計予算","agenda":"平成２０年度品川区一般会計予算","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"私のほうは、３０３ページ、生徒指導対策費、同じく連合行事費、３２９ページの地域スポーツと総合型地域スポーツクラブ、この点について伺いたいと思います。私自身もそうですし、こういう話題は結構地域で多いもので、伺おうと思いましした。こんな心配を持ちながら、品川区内の実態はどうかがとても気になっていたので、伺いたいと思います。もう１点、塾通いの実態。ここから伺いたいと思います。","respondent":"河野指導課長","answer":"塾に通っている実態ですが、学習塾に通っているお子さんは、小学校１年生から９年生までそれぞれいるわけですが、６年生の実態としては、私どもの把握している数字では、大体４７.５％の子どもが通塾しているという実態です。","voiceIndex":4,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"少し前に新聞報道で、首都圏で６人に１人が私立中学というような、今伺うと２２％では結構高いんだなという実感がありました。２つ目に、これは感覚で皆さん感じると思うんですが、金銭的な負担、これはかなり高額になっているのではないかと考えられますが、品川区として私立中学受験のメリット、デメリットをどのようにとらえられているか、伺いたいと思います。それが主流なのか、伺いたいと思います。","respondent":"河野指導課長","answer":"これらのことを兼ねあわせて考えてみますと、私立中学校を受験して、都立もそうですが、進学できれば高校入試がないので、いわゆる１５歳、思春期の多感な時期を入試に追われずに学校生活を送ることができるという。","voiceIndex":6,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"今、最後に公立の魅力という点でありましたが、公立のことでちょっと伺いたいと思います。本当にここ数年だと思います。再度、改めてそういった公立中学校の今のＰＲの方法ですとか、公立自慢みたいなところをもうちょっと、伝え方もあるんですが、聞く側にも当然問題あると思うんですが、最後、伺いたいと思います。","respondent":"河野指導課長","answer":"品川区では、プラン２１を通して、学校の自由選択制度、あるいは外部評価、あるいは学力定着度調査等を実施するとともに、それぞれの学校が実態を踏まえて、どう自己改革をしていくのかというようなことに、教育委員会と一体となって取り組んでまいりました。","voiceIndex":8,"id":"exchange-003"},{"speaker":"渡辺委員","kind":"提案","question":"先般、議員提案条例で、品川区文化芸術・スポーツのまちづくり条例、この流れもくんでの伺いになりますが、小学校で先日伺った中で、演劇の鑑賞、劇団四季ミュージカルで、「ユタと不思議な仲間たち」を学校単位で行ったという話を保護者の方から聞きました。これが１校だけかと思ったら、複数の学校で同じような感想を伺いまして、まずどのような仕組みでこの観劇を行われているのか。","respondent":"河野指導課長","answer":"それぞれ鑑賞といいましても、音楽鑑賞はもとより、観劇、スポーツ鑑賞、さまざまあるわけですけれども、現在のところ、主に行われているのが観劇ということで、それぞれミュージカルを鑑賞したり、それから、日生劇場のほう、こちらは抽選になりますが。","voiceIndex":10,"id":"exchange-004"},{"speaker":"渡辺委員","kind":"確認","question":"感受性の高い子どもにとって、その後すごく大きな、悪い影響はまずないと思いますし、こういうトップレベルに触れることで、児童全般ですごく広く感動を与えられる反面、実際、こういったものは結構高額であったり、ご家族で行こうとすると、３人家族、４人家族だとなかなか行きづらいご家庭も多い中で、文化芸術振興に加えて、学芸会にも生かされたというところがちょっと心に残りまして。","respondent":"河野指導課長","answer":"ただ、教育課程の中に位置づけて、そこに行くということを考えると、例えば屋外で行われるスポーツ等の場合には、天候等によってもかなり影響を受けるということもありますので、実態として、期日があらかじめわかっていて、そこでまず中止だかと延期だとか。","voiceIndex":12,"id":"exchange-005"},{"speaker":"渡辺委員","kind":"質問","question":"スポーツの話が出ましたが、特に今回観劇というのが心に残りましたし、私も決して見ないわけではないので、ぜひともお願いしたいなと思いました。次に、３２９ページ、地域スポーツの推進で伺いたいと思います。今回、スポーツに限って伺おうと思いますが、運営にかかる諸経費を持ち出したりして、努力している。熱意で結構、そういう中で取り組まれている。各団体でやりくりされている。そう思っていました。","respondent":"富田生涯学習課長","answer":"地域の少年少女の育成をされている方々への支援ですけれども、生涯学習ボランティア保険というのを設けておりまして、社会教育登録団体、少年少女団体の育成者の方々を対象に保険料を教育委員会が負担するという制度を実施しております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問","question":"今回、スポーツで伺いましたが、ＰＴＡですとか、あるいは、地域の町会等でも、運営される側、役員のなり手ということで、こういったボランティアの方を守っていかなければいけないという思いがありますので、いろいろ私も引き続き研究していきたいと思います。最後に、総合型スポーツクラブについて伺います。こういった点で心配が要らないのか、あるのか、すいませんが、最後に伺いたいと思います。","respondent":"富田生涯学習課長","answer":"そういった意味で、既存の団体の既得権というようなことで活動場所が制約されることのないよう、新たな方々の活動の場所をいろいろ考えていきたいということも含めて、これからの団塊の世代等々のスポーツ参加ということを含めて、自分たちのためだけに活動するのでなく。","voiceIndex":16,"id":"exchange-007"},{"speaker":"金野委員","kind":"質問","question":"私からは、ページ数は３１４ページの３目学校教育費のうち学校給食費を質問します。物価高騰に伴い、給食費はどうなるのか、とても心配です。現状、この対応をされていると思いますが、また今後の取り組みをお聞かせください。","respondent":"古里学務課長","answer":"今、この問題で、来年度、今の給食費で給食運営ができるのかどうかというところについては、非常に厳しい状態になってありますので、今現状、どれぐらい足りなくなるのか、そうした点について、今、調査をして検討を進めているところです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"金野委員","kind":"質問・要望","question":"これまでのご努力も本当に感謝申し上げます。続きまして、現在の小中学校に配置されております栄養士に関することなんですが、学校では栄養職員となっているかと思いますけれども、この業務に関して、学校の栄養士は、現在東京都においては、単独校２校に１人というふうに配置をされていると伺っているんですが、品川区としては、栄養士、また栄養職員、学校栄養職員の配置をどのようにされているのか。","respondent":"古里学務課長","answer":"そうした意味では、２校に１人ということで、非常に厳しい状態であることは事実です。今後、この点については、さきの決算特別委員会でしたか、お話をしたとおり、補助要員として調理職員の配置等を今後検討するような形で進めてまいりたいと思います。","voiceIndex":21,"id":"exchange-009"},{"speaker":"金野委員","kind":"質問・要望","question":"近年、児童・生徒の食生活の乱れが深刻化する中で、学校における食に関する指導を充実し、すべての児童・生徒が望ましい食生活、食習慣を身につけることができるようにすることが求められるために、学校での栄養教諭の配置を促進することを求められていると思いますけれども、今後の予定というんでしょうか、東京都から、都教委から来ています平成２０年度をめどに複数のモデル地区を設置して。","respondent":"河野指導課長","answer":"ただいま委員ご指摘のとおり、東京都においても、平成２０年度からモデル地区を指定して、そのモデル地区に栄養教諭を配置するという形で進めていくと伺っております。","voiceIndex":23,"id":"exchange-010"},{"speaker":"金野委員","kind":"質問","question":"栄養士の方が単位、２４単位や２２単位、１４単位と、新たな単位をとることによって、栄養教諭の免許が取れるということで、栄養士がそのまま栄養教諭として教壇に立ってお子さんに食育の指導ができると伺っているんですが、そうすると、今はモデル地区としては品川は応募されていないということですが、今後はまたこういった流れになろうかと思うんですけれども。","respondent":"河野指導課長","answer":"食育が今、子どもたちにとって大変重要な課題になっているということについては、ただいま委員ご指摘のとおりです。品川区におきましても、食育については、今まで実際に担任のほか、教科担任、養護教諭、さらに栄養士を交えて、さまざまな視点から指導をしています。","voiceIndex":25,"id":"exchange-011"},{"speaker":"金野委員","kind":"質問・要望","question":"ですので、子どもたちへの食育に対して、教養ある食事、そして食生活をぜひこの栄養教諭を通して教えていただきたい、そのように願うものであります。そういった点を踏まえて、もう一度品川のお考えと意気込みというんでしょうか、数秒ですが、お聞かせください。お願いします。","respondent":"河野指導課長","answer":"モデル地区等の成果等も踏まえて検討してまいりたいと考えております。","voiceIndex":27,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"私からは、３１４ページの学校給食についてと、３０５ページの小中一貫教育なのでしょうか、小中学校の夏休みのプール教室について伺いたいと思います。しかし、実際は問題だらけです。私はこの説明の前提が崩れたと感じているんですけれども、導入当時のこの説明は今も変わらないのかどうか、お聞かせください。","respondent":"古里学務課長","answer":"調理代行を導入する、民間の活力を導入することについては、安全面、衛生面、こうしたことについては、社内での教育がしっかり行われておりますので、導入当時から考えてきたこと、民間の活力を安全な学校給食に活用するという、この方針については、全く変わりはございません。","voiceIndex":30,"id":"exchange-013"},{"speaker":"中塚委員","kind":"意見","question":"改めて、当時、民間業者、調理でも、衛生管理においても行政と遜色ないと、そう主張するその根拠は何なのか、ご説明ください。それと、この業者が、２カ月間にわたりますけれども、給食時間、１２時１５分に間に合わなかった回数は何回だったのか、説明してください。","respondent":"古里学務課長","answer":"大間窪小等で給食がおくれた回数ですけれども、３回ないしは４回と聞いてあります。","voiceIndex":32,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"格段によくなったと一方で説明しながら、一方で、大間窪小が３回から４回おくれている。教育委員会はしっかりと把握しているのかどうか。どうしてこれで安全でおいしい学校給食が確保できるのか、非常に疑問です。天ぷらがベチャベチャ。残菜が増えているのではないかという話も伺いました。私は、つくり手が変わるだけなんだという説明は全く実態と異なると思うんですけれども、いかがでしょうか。","respondent":"古里学務課長","answer":"それと最後には、ＰＴＡの方々にも入っていただき、その業務評価を公開しながら、最終的な事業者の評価をしていますので、こうして、私どもとしては、手を尽くせる限りの現場の事業者との協働、協力関係は築いているつもりですので、そのようなことで、今、進めているです。","voiceIndex":34,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"現場に足を運んでいるんだと説明しますけれども、じゃあ、なぜこういう状態が起きるのかと、そこをしっかりと受けとめていただきたい。私は、せめて子どもたちにアンケートをとったり、意見や感想、そういうこともやるべきではないかと思っています。続いて、夏休みのプールについて後半伺いたいと思います。私は、夏休みのプール教室をぜひ復活させていただきたいと思いますけれども、いかがでしょうか。","respondent":"藤森小中一貫教育担当課長","answer":"なぜ夏休みにプールをやらないかですけれども、通常、施設分離型の連携校の場合は、屋外にプールがありますので、当然入れる時期というのは６月の中旬ぐらいから９月の初旬ぐらいまで。","voiceIndex":36,"id":"exchange-016"},{"speaker":"中塚委員","kind":"意見","question":"子どもが夏、プールに入りたいと言っているんですね。なぜそれを断るのか、年間の通常の話と夏のプール、何でこれを奪ってしまうのか、そこがよくわかりません。一貫校、室内プールをそうですけれども、夏休みのプールの中止、これは学校長の判断なのか、それとも教育委員会の方針なのか、いつだれが決定したのか、ご説明ください。","respondent":"藤森小中一貫教育担当課長","answer":"それと、だれがこれを決定しているのかですが、これは、教育課程を編成している校長の判断で行っているという状況です。","voiceIndex":38,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"校長の判断とありましたけれども、現在、伊藤学園ですと、今度６年生になる子どもたちは、入学当時は、その学校が一貫校になるとも、ならないとも知らずに、原小学校に入った生徒なんですね。４年生まであった夏休みのプールが５年生になったら中止になった。これが全く理解できません。ぜひプール教室、復活していただきたいと思いますけれども、いかがでしょうか。","respondent":"藤森小中一貫教育担当課長","answer":"それで、もう一つは、実際に泳力、あるいは水なれ、そういった子どもたちの状況も、今までの原小、第二日野小学校の実態よりも、より効果が上がっているという報告も受けておりますので。","voiceIndex":40,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど話しましたけれども、今度６年生になる子どもは、原小学校に入学した当時は、その学校が一貫校になるとは全く知らされていなかったわけですよね。なぜそういう子どもたちからも学校の夏休みのプール指導、教室を奪うのか。そこの答弁がありませんので、ご説明していただきたい。どうでしょう。私は、夏は子どもたちがプールに入りたい。なぜこれを踏みにじるのか、わかりませんので、ご説明ください。","respondent":"藤森小中一貫教育担当課長","answer":"そういったさまざまなニーズにできるだけこたえるようなものがこの一貫校だと認識していますので、今後とも学校を支援してまいりたいと考えています。","voiceIndex":42,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう機会を奪わないでほしいと思うんですね。一貫校でも、夏、一般開放があるじゃないかとおっしゃいますけれども、１７０円、ロッカー代を含めてでしょうかね、かかるという話も伺いました。私はこれはどう考えてもおかしいと思うんですけれども、ぜひ夏休みの一般開放のとき、こういう時間を、子どもたちに確保をしていただきたいと思うんですけれども、そういうことも検討できないんでしょうか。","respondent":"藤森小中一貫教育担当課長","answer":"そういった年間を通してバランスを保ちながら、今、教育をしていますので、議員ご提案の内容につきましては、今のところ考えているところではございません。","voiceIndex":44,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"サマースクールをやることと、なぜ一貫校に夏休みのプールの時間を確保できないのか。そこが意味がよくわかりません。一般開放ですと、小学校３年生以上の方は付き添いが必要なわけですよね。なぜ一貫校になったらできないのか。一貫校でなくても、屋内プールであれば、できないのか、そこが意味がわかりません。子どもの立場に立って、よく検討していただきたいと思うんですけれども、いかがでしょうか。","respondent":"長田教育次長","answer":"夏にプールに入りたいという部分につきましては、ご両親等の協力の中で、近隣のプールもあるわけですので、そういったプールをご利用いただければと、このように考えるところです。","voiceIndex":46,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"夏休みになると、水泳バッグを持って、学校に行って、判こをもらったり、そういうことがずっと続いて、地域の方も、何で一貫校になったらプールに通う子どもたちの姿が見えなくなったのかな、そんな話も伺いました。小学校３年生以下の方は付き添いが必要なわけですね。でも、そういう都合を子どもたちに押しつけないでほしい。ぜひ子どもの声に耳を傾けていただきたいと思いますけど、最後いかがでしょうか。","respondent":"藤森小中一貫教育担当課長","answer":"今、委員のほうから、ぜひプールの時間をたくさんとってほしいということがありました。伊藤学園では既に３５時間程度のプール指導をしております。","voiceIndex":48,"id":"exchange-022"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"本日もよろしくお願いいたします。私のほうから、３０３ページのクラブ・部活動指導対策費、これに関連して３０５ページ、合同部活動、同じく関連して、３０９ページ、クラブ活動指導費、それと、３０３ページに戻りますが、教職員研修についてお伺いをさせていただきたいと思います。","respondent":"河野指導課長","answer":"ただいまお尋ねのクラブ・部活動指導対策費の増額ですが、これは、部活動を実施する際の外部指導員の方には謝礼をお出ししていますが、外部指導員をお願いする回数を１０回分から、それぞれ２０回分ということで増やしたことによる増額です。","voiceIndex":51,"id":"exchange-023"},{"speaker":"石田（慎）委員","kind":"質問","question":"今お話があった外部指導員の現状、何校で、謝礼額がどのぐらい等、今答弁で１０回から２０回とお答えいただいたので、何校で、謝礼額はどのようになっているのかを教えていただければと思います。","respondent":"河野指導課長","answer":"現在、１８校の中学校がありますが、そのうちの１７校に何らかの形で外部指導員が入っているという状況です。なお、報償費の額は、１日を基準に４,０００円という金額になってあります。","voiceIndex":53,"id":"exchange-024"},{"speaker":"石田（慎）委員","kind":"意見","question":"特に大崎中学校の例を挙げしますと、２００６年から非常にすばらしい成績をおさめるという結果が実際に出ていまして、まず初めに私のほうからも、教育委員会に非常に高い評価をしたいと思います。そんな中、大崎中学校の例で、こういった成果が出ている中、部活動だけではなくて、例えば学問とか生活態度等、部活動が活発になったことによって変わった点がありましたら、お教えいただければと思います。","respondent":"河野指導課長","answer":"共通した目標に向かって、ともに励まし合い、努力をするというようなことで、単に結果だけではなくて、その過程の中で、さまざまな体験を身につけていく。それを実際の生活、行動の中で生かしていくということが部活動の一番大きな目的であると認識しております。","voiceIndex":55,"id":"exchange-025"},{"speaker":"石田（慎）委員","kind":"提案","question":"そんな中で、区としての今後の展開、例えば外部指導員が今、実際に１７校にいるというお話でしたが、そして１日４,０００円というお話でしたが、よりよい人材確保の中で、これは提案になってしまうんですが、外部指導員に対してもう少し報酬額を出していただければなと。その点は、ご見解をお願いします。","respondent":"河野指導課長","answer":"そういうことを見きわめながら、学校のほうも外部指導員を探しているという状況もあります。そういう実態も踏まえて、私どもは、平成２１年４月を目途に、部活動をさらに活性化するための具体的な検討に入ろうということで、現在準備を進め始めたという状況があります。","voiceIndex":57,"id":"exchange-026"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"２つ目の３０３ページの職員の研修についてになると思うのですが、お伺いします。２００６年度ですが、うつ病などの精神性疾患による病気で休職した小中高などの公立学校の教員が過去最高の４,６７５人になったという報道がありました。これは１４年連続の増加で、１０年前の９７年度の約３倍に増えたと伺っています。病気休職者の占める割合の６割が精神性疾患による休職であるということで、質問します。","respondent":"河野指導課長","answer":"病気休暇はともかく、病気休職になった教員については、復職の前、おおよそ２カ月ぐらい前から復職訓練というのを担当の医師と相談をしながら進めてまいりまして、最終的に担当の医師のゴーサインを得た上で職場に復帰するという制度になってあります。","voiceIndex":59,"id":"exchange-027"},{"speaker":"石田（慎）委員","kind":"質問","question":"先ほど２０名という答弁がありましたが、その年齢別がもしわかったら教えていただければと思います。","respondent":"河野指導課長","answer":"年齢別の統計、特にはとっておりませんが、若い人に多いとか、あるいは中年層に多いとかという偏りは特にないととらえております。","voiceIndex":61,"id":"exchange-028"},{"speaker":"石田（慎）委員","kind":"意見","question":"教師の心の乱れというか、そういったことは、子どもは非常に敏感ですので、ぜひ最高の教育をしていただくためにも、教員のしっかりとした研修制度、また、復職のためのプログラム、支援策等をしっかりとこれからも行っていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-029"},{"speaker":"山内委員","kind":"質問・要望","question":"私のほうから、３３１ページ、歴史館の経費、それから、その後、３０５ページのプラン２１関連事業についてお尋ねをさせていただきたいと思います。ただ、この予算を見ますと、入りが２３０万円に対して、出が約１億１,０００万円。これは、民間であれば、閉鎖もやむなしというのが普通考えられるんですが、その辺についての品川区の考え方をまず教えてください。","respondent":"富田生涯学習課長","answer":"品川歴史館についてのお尋ねですけれども、歴史館、できましてから２０年少々の年数がたっておりますが、品川区内の歴史的なさまざまなものの保存ですとか、収集、また活用等を図っていく。","voiceIndex":65,"id":"exchange-030"},{"speaker":"山内委員","kind":"質問","question":"ただ、予算、これを見ますと、収入のいわゆる人数で換算すると、６,０００余の人数を予想しておりますよね。品川には３４万人住んでおりますけれども、住民がおりますが、その辺についての人数的な、来場者数のバランスというんですか、その辺はどうお考えなんでしょうか。","respondent":"富田生涯学習課長","answer":"収入だけを見ますと、もう少しと思われるかもしれませんが、例えば区立の小中学校に通っているお子さんについては、免除とすることなど、収入を増やすこと以上に、より多くの区民の皆さんにご利用いただき、そういった場を活用いただき、品川の歴史に愛着を持っていただくという。","voiceIndex":67,"id":"exchange-031"},{"speaker":"山内委員","kind":"質問・要望","question":"続きまして、３０５ページのプラン２１関連についてお尋ねをしますけれども、下から６行目に特色のある教育活動ということがこちらで載っておりますけれども、私、このプラン２１からずらっと見ますと、いわゆるこれがすべてが特色のある教育なんじゃないかなと思うんですけれども、この特色のある教育活動、３００万余の予算が計上されていますけれども、詳しい内容はどうなっているんでしょうか。","respondent":"河野指導課長","answer":"具体的な中身を申し上げますと、例えば三木小学校の学年担任制度のための講師の費用でありますとか、それから、今、品川小学校のほうで、エンサイクロペディアスクールということで、パソコンを使った、説明すると長くなりますから、省略いたしますけれども。","voiceIndex":69,"id":"exchange-032"},{"speaker":"山内委員","kind":"質問","question":"ということは、各学校独自の特色のある教育ということをこちらで載せているということですね。わかりました。それとも、学校独自で評価されたものを、学校独自で、いわゆる地域の方々に、こういう評価ですよという形で評価を皆さんに提示しているのか。その辺を教えてください。","respondent":"河野指導課長","answer":"学校評価、今、お尋ねのは、校区の外部評価だと思います。校区の外部評価の結果につきましては、それぞれの学校がホームページ等を通して公開をしています。教育委員会として、全校取りまとめて発表するというような形はとってございません。","voiceIndex":71,"id":"exchange-033"},{"speaker":"山内委員","kind":"質問","question":"そうしますと、例えばある学校の地域の方々に外部評価員としていろいろと評価していただきますよね。そうすると、どうしてもその地域の方々が、卒業された学校を評価すると思うんですよ。結構多いと思うんですね。あまり自分の学校はよくないよと言う人はあまりいないと思うんですが、その辺についての教育委員会からの評価員になっていただく方への指導というか、そういうことはあるんでしょうか。","respondent":"河野指導課長","answer":"校区の外部評価の中には、それをある程度客観的に見るという意味も含めて、学識経験者を入れておりますし、あわせて、専門外部評価ということで、別途評価をしています。","voiceIndex":73,"id":"exchange-034"},{"speaker":"山元委員","kind":"質問・要望","question":"私は、３０３ページの生徒指導対策費の中の幾つかをご質問させていただきたいと思います。この中の不登校対策費、３７万云々と書いてありますが、この内訳をひとつ教えていただきたいと思いますが、よろしくお願いいたします。","respondent":"河野指導課長","answer":"こちらのほうは、不登校の取り組みに対して、講師の方をお願いして、指導を受けるケースがあります。そのための講師の謝礼です。","voiceIndex":76,"id":"exchange-035"},{"speaker":"山元委員","kind":"質問","question":"この３月といいますと、卒業式になりますが、不登校ということに対して、小学校、中学校、みんなと一緒に卒業したいと思っていても、結局学校に来れなくて、一緒には卒業できない方が何人かいらっしゃるかと思いますが、今現在、中学校、小学校で不登校の人数、品川区としては何人いらっしゃるか、教えていただけますでしょうか。","respondent":"河野指導課長","answer":"今年度の１月までのデータですが、３０日以上欠席している児童・生徒が、小学校で４１名、中学校で１０９名です。","voiceIndex":78,"id":"exchange-036"},{"speaker":"山元委員","kind":"質問・要望","question":"中学校の１０５名のうち、今回卒業するメンバーは何人ぐらいいらっしゃいますか。そしてまた、卒業した後の不登校の子どもの進路がもしおわかりになれば教えていただきたいと思います。","respondent":"河野指導課長","answer":"不登校児童・生徒、６年生、それから９年生の人数ですが、先ほど申し上げた１月段階の人数で、６年生のほうが１６名、９年生のほうが５０名です。","voiceIndex":80,"id":"exchange-037"},{"speaker":"山元委員","kind":"質問・要望","question":"本当にみんなと一緒に卒業できない、とても心を痛めているのではないかなと思います。次の小学校におけるカウンセリング事業についてお聞きさせていただきたいと思います。先ほど校外対策指導費用のことを教えていただきましたけれども、カウンセリング事業について、内容といいますか、どういうことか教えていただきたいと思います。","respondent":"河野指導課長","answer":"あるいは保護者から、教員からの相談を受けるということにあわせて、学校のほうがいろいろな意味で気にしている生徒、対応に苦慮している生徒へのかかわりについて具体的にアドバイスを受けるというようなことで、活躍していただいているところです。","voiceIndex":82,"id":"exchange-038"},{"speaker":"山元委員","kind":"質問","question":"カウンセリングといいますと、私は勝手に、子どもがスクールカウンセラーにご相談をするのかと思っていましたら、今、教師とおっしゃっていましたが、現場の先生もスクールカウンセラーにご相談することがあるんでしょうか。","respondent":"河野指導課長","answer":"教員に何らかの形でかかわっているケースが２,３９２件ということで、実際には、これは教員がカウンセリングを受けるということではなくて、それぞれのクラスで抱えている子どもに対してかかわり。","voiceIndex":84,"id":"exchange-039"},{"speaker":"山元委員","kind":"質問","question":"そうしますと、先生方が、二千二百何十人という方が、現場でいろいろ悩み事があって、スクールカウンセラーにご相談をしますよね。その内容というのは、その１回で解決できるのか。それができない場合はどういう対策をなさっているのかを教えていただけますでしょうか。","respondent":"河野指導課長","answer":"子どものことに関して、教員がさまざまな形でアドバイスを受けていると申し上げましたが、実態として一番多いのが、今、発達障害が疑われる子どもたちへの対応であるとか、配慮です。","voiceIndex":86,"id":"exchange-040"},{"speaker":"山元委員","kind":"質問","question":"秘密といいますか、先生にしてみれば、ある意味とてもプライドがあって、悩み事を相談することは若干抵抗があるかなと思いますが、それは例えばカウンセラーから校長先生に話が伝わっちゃうとか、秘密というか、そういうものは守られているんでしょうか。","respondent":"河野指導課長","answer":"これは、子どもの教育に関することですので、子どもの教育に関する最終的な責任者は学校長です。学校長が何にも把握しないところで教員が勝手に物事を進めていくということはできませんので、当然学校長のほうも把握しているということになります。","voiceIndex":88,"id":"exchange-041"},{"speaker":"山元委員","kind":"質問","question":"先ほど２０人の先生がいろいろ悩まれて、疾患で休まれていると聞きましたけど、その辺とのつながりがあるのかなと自分自身は思いました。次にいかせていただきます。次の子どもへの暴力防止対策、ＣＡＰ事業というんでしょうか、こちらを教えていただけますでしょうか。","respondent":"河野指導課長","answer":"ＣＡＰというのは、子どもが暴力だとか虐待から自分自身を守るためのプログラムに基づいて勉強していくという、そういう内容で実施しているものです。","voiceIndex":90,"id":"exchange-042"},{"speaker":"山元委員","kind":"質問","question":"この子どもというのは、小学校１年生から中学生まで、全般なんでしょうか。それとも、ある程度何年生とターゲットを絞って、教えていただいているんでしょうか。","respondent":"河野指導課長","answer":"現在、このＣＡＰは、品川区内のすべての公立小学校の３年生と５年生を対象に実施している事業です。","voiceIndex":92,"id":"exchange-043"},{"speaker":"山元委員","kind":"質問","question":"実際どういうことを３年生と５年生にどんな形で教えているのか、内容を教えていただいていいですか。","respondent":"河野指導課長","answer":"学校、家庭、地域との連携、子どもを見守る、そういう大人を増やすという、この３つの柱です。そして、実際にやっている中身といたしましては、４５分を単位として２コマ実施しておりますが、子どもの持っている３つの権利に対する説明。","voiceIndex":94,"id":"exchange-044"},{"speaker":"山元委員","kind":"提案","question":"時間がないのであれなんですが、それを受けて、子どもたちが自信がついて、いろいろな思いで向かっていかれる子どもになっていただきたいと思います。今回、品川区、笑顔で輝く住み続けたいまちにというご提案がありますが、本当に子どもたちが、品川にずっとい続けたいという思いのためにも、ぜひ皆様のご努力をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":96,"id":"exchange-045"},{"speaker":"渡部委員","kind":"質問・要望","question":"私も払っている立場です。それと、あと１つ確認させていただきたいのが、衛生面、最近ニュースとかでも話題にすごくなりやすい学校給食で、やはり昨年の決算特別委員会で質問させていただいたんですが、成分分析をなさらないという話でした。でも、ニュースに出ちゃったら、行政の責任云々になってくると思うので、その辺のお考えを聞かせていただければと思いますので、よろしくお願いします。","respondent":"古里学務課長","answer":"具体的な値上げという段取りについて、業者との話し合いをしているのかということですが、先ほど申し上げたとおり、給食費にかかわる食材の値上げ、これが新年に入りまして、いろいろな報道、それから、小麦の値上げ等もはっきりしてきたという中で、今、鋭意、私どもが。","voiceIndex":98,"id":"exchange-046"},{"speaker":"渡部委員","kind":"質問","question":"そうですね。加工食品を使われてないということだったので、すみませんでした。肉の産地偽装とかというのがこの間あって、どっちかというと、そっちの部分だったんだけど、それってどうしようもないのかなというのもあるので。まあ、でも、年に一遍でもやれればいいのかなというのがまず１つなんです。例えば超短期の融資とか何か、可能な策があるのかどうかもお伺いさせていただけますでしょうか。","respondent":"古里学務課長","answer":"ただ、先般もお話ししたと思いますけれども、どうしても新年度に関しては、口座振込の手続等によって、１カ月ちょっと余計にかかってしまうということがどうしても出てまいります。これは制度上の問題ですので、その点につきましては、業者の皆さんにご協力をお願いしています。","voiceIndex":100,"id":"exchange-047"},{"speaker":"渡部委員","kind":"質問・要望","question":"次ですが、先ほどほかの委員からも質問がありましたので、かぶらないところで、お伺い、確認させていただきたいのが、３０３ページのカウンセリング事業のところなんですけれども、たしか小学校におけるカウンセリング事業というのは、どこか拠点校のようなところに所属という形にして、近隣の学校にカウンセラーが回るのかなと私は認識していたんですが、今の現状。","respondent":"河野指導課長","answer":"したがって、学校へ行った１日に、スクールカウンセラーがすべてのカウンセリングを行うということになりますと、先ほど申し上げたような教員へのコンサルテーションその他ができなくなりますので、相当期間のカウンセリングが必要であると判断される場合には。","voiceIndex":102,"id":"exchange-048"},{"speaker":"渡部委員","kind":"意見","question":"スクールカウンセリングの事業の件数、先ほどありましたけれども、こんなに多いとは、僕はある意味思っていなかったので、さまざまな、これから保護者、子どもたちからの相談も含めまして、解決していっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"３０１ページ、学事制度検討経費に関連して、学事制度審議会、学校適正規模適正配置という名のもとに進む学校統廃合問題についてお伺いしたいと思います。子どもの数は、確かに区が説明するように現在の学校数が整備された昭和５０年と比べると減ってきました。適正規模の検討を始めた、今年といいますか、平成１９年の出生数、児童数、生徒数は何人になっているのか、教えてください。","respondent":"古里学務課長、古川児童保健事業部長","answer":"今、出生数ということを突然言われまして、今数字がすぐ出ませんのでちょっとお待ちいただきたい。後ほどお答えします。申しわけございません。私の持っている資料では、平成１８年の出生数は２,８１２名です。","voiceIndex":106,"id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"平成１８年２,８１２人ということで、平成１２年が２,３５１人ですから、５００人ぐらい増えているわけですよね。その理由として、これまで区は、小規模化が進むと教育目標を達成しづらくなると説明してきましたけれども、小規模化の何が悪いのか、教育環境をどう損なうかというのを、私、わかりませんので、説明をお願いします。","respondent":"古里学務課長","answer":"したがって、子どもたちを生む世代の数が減ってまいりますので、物理的に子どもの数が減っていくということ。これは、日本国中の全体的な常識と私は考えてありますので、こうしたことから、私どもは検討しなければならないということを言っているものです。","voiceIndex":109,"id":"exchange-051"},{"speaker":"安藤委員","kind":"質問","question":"この増加を招いたのは、学校選択制と小中一貫校６校構想の品川区の競争教育そのものではないかと指摘したいと思います。だって子どもの数は増えているわけですから。そのときには検討しないと言っておきながら、小規模校の数が増えたというのは、明らかにこれは品川区がやってきた教育改革の大きな要因だということで指摘せざるを得ないんですけれども、それはお認めになるでしょうか。","respondent":"古里学務課長","answer":"このこと自体が、学校選択制がなかったとしても、小規模な学校が８つできてしまうということですから、この点は、地域バランスや地域のいろいろな事情はありますけれども、そういう事情もあるんだということ、このことが今の学校のそれぞれの小学校の先生たちの頑張りの中で。","voiceIndex":111,"id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"それで何でこうまでして適正化という名の統廃合に走るのかということで、区のねらいの大きな１つは、コストの削減であるということはたびたび共産党でも指摘しましたけれども、指摘したいと思います。教育委員会側は、教育の専門部局として、そうした動きに対しては、きっぱりと教育の専門としての立場を述べて、もっと言えば、抵抗すべきだと思うんですけれども、そちら、見解、２つお伺いします。","respondent":"福田企画部長、古里学務課長","answer":"なぜかと考えますと、これは税によって公教育が運営されているからです。そうである以上、これは教育部門であろうと、どの部門であろうと、効果、効率性を追求するのが公務員の義務です。私どもは、八潮地区が少子化が進む中で、３つの小学校、２つの中学校が小さな学校になっていく中で、地域の皆さんから、一貫校という形でまとめてくれないかという地域の方々の後押しもあって、こうしたことをしてまいりました。","voiceIndex":113,"id":"exchange-053"},{"speaker":"安藤委員","kind":"提案","question":"私は３０人学級をぜひ提案したいと思います。唯一東京だけが４０人学級を崩していない。生活面はどうでしょうか。児童との接触時間が増え、児童の要望を理解できるようになり、個に応じた指導がしやすい。そして、保護者や生徒の声、どうでしょうか。それで、３０人学級が仮に導入された場合、現在の小学校の学級数は幾つになり、現行の４０人学級と比べると幾つ増えるのか、お答えいただけますでしょうか。","respondent":"古里学務課長","answer":"私ども、そういう予定もございませんし、都教委の意向もそういう意向がございませんので、そうした試算はしたことがございません。","voiceIndex":116,"id":"exchange-054"},{"speaker":"安藤委員","kind":"提案","question":"現在の４０学校中、３２校で、品川区全体でいうと９９学級増えることになります。単学級が解消される学校は１６校。３６学年の単学級が解消されます。その中身を紹介しますけれども、提案理由ですね。広く浅く学ぶ効率中心の教育から、深く学ぶ質の高い教育へと転換していますと、その提案理由を示しています。学校の数を減らしてどうするんですか。どうするつもりなんですか。見通しを持っているんですか。","respondent":"古里学務課長","answer":"私どもは、現在の学級編成基準に従い、４０人学級を中心にしながら、ここ１０年、１５年の教育環境を整備していくという計画を考えたいと考えています。","voiceIndex":118,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ、私、何でここまで熱を込めてしまうかというと、将来の品川の子どもたちの心配を、学習面でも生活面でも心配しているわけであって、少人数学級の早期の導入へ向けて全力を挙げてもらうことを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-056"},{"speaker":"原委員","kind":"質問","question":"初めにプレス発表時から比べますと、教育センターに２,０１０万円、図書館で１,８６０万円、両方で４,０００万円ぐらい減額になっているんですけれども、ここのところについて、何か変わったことがあるのか、それともこういう時節柄ですから、効率的にされたのかどうか、その辺をお聞きしたいということと、それから、続けて先にお聞きしたい点を幾つか出してしまいますけれども、第一日野小学校移転改築。","respondent":"宍戸施設担当課長、富田生涯学習課長","answer":"そのほかのものにつきましては、建築基準法の言葉でいくと、新築となります。それとあと、今後の契約等の。業者選定についてですけれども、今、検討中ということで、間もなく明らかになるのかなと思います。五反田文化センター、プラネタリウムにつきましては、新たな機器を導入いたします。","voiceIndex":123,"id":"exchange-057"},{"speaker":"原委員","kind":"質問","question":"これ、全体的に見ていくと、プラネタリウム一式幾らかなと出てきたのは、多分建築工事に入っているのかなという気がするものですから、その辺のところがどうかなというのと、あとは、これから施工業者が決まってくるということなので、それは入札とかプロポーザルをされていくんでしょうけれども、そうすると、プラネタリウムに関しては、先に業者が決まっているのであれば、ストレートに聞いちゃうと。","respondent":"富田生涯学習課長","answer":"その検討の中で、プラネタリウムの機器はそう数があるわけではございませんので、経費の面につきましては、１２ｍドームまでの仕様のものと、あるいは１０ｍ以上のプラネタリウムの機器等ございまして、そういった意味では、導入する機器につきましては。","voiceIndex":126,"id":"exchange-058"},{"speaker":"原委員","kind":"質問・要望","question":"１点、これは要望なんですけれども、せっかくやるんだからという感じがありまして、和太鼓の音楽活動ができるとうたっている以上、プラネタリウムもしっかりしたものをやられるのであれば、やってほしい。私はここは専門的なものを入れてほしいという要望がありますので、それをお願いしておきたいということです。次に、ソフト面に関して聞いてまいります。","respondent":"市川庶務課長","answer":"ご質問にございました文化センターの持っている機能、つまり、文化センターをご利用されるさまざまな利用者、そことの学校教育との連携、連動、この辺については、１つの課題ということで認識をしています。","voiceIndex":128,"id":"exchange-059"},{"speaker":"原委員","kind":"質問","question":"もう少し踏み込ませていただいて、要は、これは確かじゃないんですけれども、図書館でミニコンサートみたいなものをやられる、そんなようなことをまちの人に伺ったんですけれども、全体的に教育委員会で集中的に、各所管ではなくて、それを上で束ねていただいたら、経費的な問題も若干もう少し効率的な形になるんじゃないかなという気がするものですから、いろんなところの、縦割りではなくて。","respondent":"工藤品川図書館長","answer":"そういった中で、新たな施設というのが、音楽ホールができるということになりますので、今後とも教育委員会のほうで連携を進めながら、事業を展開していきたいと考えています。","voiceIndex":130,"id":"exchange-060"},{"speaker":"市川委員","kind":"確認","question":"私のほうからは、３０５ページの小中一貫教育の推進、それから、３０７ページの特別支援教育について、時間がありましたら、３１４ページの学校給食に関連して少し確認します。小中一貫教育全国サミットが小中一貫教育の推進のところで予算が計上されていますという説明があったんですけれども、この全国サミットのことについてお聞きします。それとも単費で行うものなのか。その辺をお聞きします。","respondent":"藤森小中一貫教育担当課長","answer":"今回は、第３回目ということで、品川で行われるわけですけれども、これを機に、小中一貫教育は品川ありきというんでしょうか、全国でも進めた取り組みをしていますので、そこで区民、保護者の方々にも広くアピールしていきたいと考えているところです。","voiceIndex":133,"id":"exchange-061"},{"speaker":"市川委員","kind":"質問","question":"先ほど私が、京都での開催のときの経費はということは、京都での開催、全体が幾らではなくて、そのときに品川がどれぐらいの金額でそこに参加をしたのかということを聞いたので、それをお聞きします。","respondent":"藤森小中一貫教育担当課長","answer":"これは、そもそも私ども、正会員になってありますので、出席の会費については無料ということで、基本的には参加者の交通費のみです。京都につきましては２人、私ともう１人、担当の主査が参加しています。","voiceIndex":135,"id":"exchange-062"},{"speaker":"市川委員","kind":"質問・要望","question":"協議会で持ち回りというふうになるんだろうと思うんですけれども、既に品川開催は２回目となりますし、品川での開催が増えれば、その分の予算と、人にも負担がかかるということですので、今後も継続して経費がかかるようであれば、子どもたちに有効に使っていただきたいと思いますので、公平にサミット開催が行われるように協議会へ働きかけていただきたいと思うんですが、この点についてはいかがでしょうか。","respondent":"藤森小中一貫教育担当課長","answer":"このサミットは、自分のところで開催することによって、まずは、広く小中一貫教育の意義だとか、成果だとかといったものを区民の皆様や保護者の方々に広く周知することができるということと、先生方、教員が、例えばこのサミットを開催することによって。","voiceIndex":137,"id":"exchange-063"},{"speaker":"市川委員","kind":"質問","question":"次の質問に移らせていただきます。３０７ページの特別支援教育について伺います。２００８年度から本格的に始まる特別支援教育ですので、少し質問をします。介助員の充実、それから、学習支援員の新設が事業として挙げられているんですけれども、それぞれの役割、介助員、学習支援員の役割について伺います。その辺についてお聞きします。","respondent":"河野指導課長","answer":"親が介助員あるいは支援員を選択できるのかというお尋ねですが、こちらのほうは、最終的につけるということに対して親御さんの確認は得ますけれども、あくまでも介助員、支援員ともに、それぞれのニーズに応じて、申請に対してこちらで判断させていただいて、その上でつけるか。","voiceIndex":139,"id":"exchange-064"},{"speaker":"市川委員","kind":"質問","question":"その数と根拠について、まずお聞きします。それから、特別支援学級経費として、１億６,５８６万９,０００円が予算書では計上されているんですが、このうち、委託経費は幾らなのかということをあわせてお聞きします。それから、２００７年度と２００８年度は、制度的にはいろいろ変わるんですけれども、この特別支援教育の主人公の子どものほうから見ると、どんな変化が起きるのかということをお聞きします。","respondent":"古里学務課長、河野指導課長","answer":"こうした人たちも一緒になって動いていけるという意味で、ＮＰＯという任意の非営利団体で進めていき、その中にそうした今まで活動していた人たちも合流しやすい仕組みづくりということから、ＮＰＯへの委託ということを考えたものです。子どもから見て、どのように変わるのかというお尋ねですが、実は、昨年１０月から学生支援ボランティアということで、都の指定を受けまして、浜川中学校と浅間台小学校でモデルケースということで取り組んでまいりました。","voiceIndex":141,"id":"exchange-065"},{"speaker":"市川委員","kind":"質問","question":"文教委員会の資料を見ますと、児童・生徒の情報を電子化して、学校内での指導の共有化を図る。支援員への作業指示は偽装請負になるため、指導内容の指示をメールでＮＰＯを経由して現場に伝える仕組みをとるとなっているんですけれども、この仕組みについて詳しく教えてください。育成はＮＰＯで、採用は教育委員会ということがなぜできないのかも、その説明の中に入れていただければと思います。","respondent":"古里学務課長","answer":"こうした情報に基づき、委託の仕様書が決められて、それぞれの学校へスタッフが赴いていくわけですけれども、日々指導の内容を細かく打ち合わせる必要があったり、あるいは、急遽変更したりというふうな事務連絡が必要になってまいりますので、この辺のやりとりにつきましては。","voiceIndex":144,"id":"exchange-066"},{"speaker":"市川委員","kind":"質問","question":"もう一つお聞きした、なぜ採用は教育委員会ということができないのかということもお願いします。","respondent":"古里学務課長","answer":"教育委員会で雇用するということになりますと、臨時職員という形をとるか、あるいは非常勤という形をとるかという、従来の不安定雇用を継続せざるを得ないと考えています。","voiceIndex":146,"id":"exchange-067"},{"speaker":"市川委員","kind":"質問","question":"問題が発生したときに、子ども、親、指導員、学校が同じ場で一堂に会して協議ができないのかなとも思えるのですけれども、そこのところはどうなんでしょうか。","respondent":"古里学務課長","answer":"そのようなことは決してございませんで、委託でございましても、緊急の要件は現場で話し合うことは可能ですので。","voiceIndex":148,"id":"exchange-068"},{"speaker":"武内委員","kind":"質問","question":"３０５ページのまちの人々に学ぶ授業と、３０７ページの経済活動体験学習経費、それから、３２１ページの荏原東地区一貫校、時間が許せば、３２９ページの総合型地域スポーツクラブの設置をお伺いしたいと思います。","respondent":"藤森小中一貫教育担当課長","answer":"まちの人々から学ぶ授業ですけれども、こちらの授業は、開かれた学校づくりを推進し、家庭、学校、地域、この３者の連携を図るとともに、教育活動の質を高めるというような目的として、地域の方の人材を授業の中に生かしていくということで、この予算につきましては。","voiceIndex":151,"id":"exchange-069"},{"speaker":"武内委員","kind":"質問・要望","question":"非常にいい取り組みだと思うんですけれども、例えばその後の教えてもらった、これは小中全校でやっているということだと思うんですが、地域の人が来て、そこで例えばその後に何かつながっていった事例というか、子どもたちが例えば手紙を届けたとか、実際に地域の方のところに出向いていって、交流が続いているとか、何かそういう例があったら紹介していただきたいのと、あと、経済支援のほうは、それぞれ。","respondent":"藤森小中一貫教育担当課長","answer":"まちの人々から学ぶ授業の地域とのつながりの継続性というお話ですけれども、何点か聞いている中で、例えばお年寄りからいろいろ戦争の話、当時の昔の戦争の話などを聞いた中で、それ以降、今度は、例えば生活科において一、二年生が、その方のおうちに行って。","voiceIndex":153,"id":"exchange-070"},{"speaker":"武内委員","kind":"質問・要望","question":"すばらしいお話で、ありがとうございました。よくわかりました。そうした面で、またさらに進めていっていただきたいと思いますけれども、以前に、ほかの委員とか、またうちの会派のほうも何回か要望してまいったんですけど、例えば今、中学生の職業、職場体験。それで、例えば１日やっているところもあれば、多いところで４日ぐらいやっているところもあるんでしょうかね。","respondent":"河野指導課長","answer":"日数ですとか、実施学年については、それぞれの学校の実情に応じて組んでいるという実情がありますので、学校によって多少差はありますけれども、職場体験については、以上のような状況です。","voiceIndex":155,"id":"exchange-071"},{"speaker":"武内委員","kind":"提案","question":"以前にもちょっと提案というか、ご質問させていただいたんですけれども、例えば５日間という、学校現場では非常に長い時間になると思うんですけれども、それくらいの日数を使っての職場体験というのを、以前、平成１６年の第４回定例会だと思うんですけれども、ニートとかひきこもり対策という中で、質問させていただいた際には、あまり、ちょっとはっきりした、今やっている事業が非常にいいので。","respondent":"河野指導課長","answer":"したがいまして、それを補うということで、小学校、あるいは中学校、先ほど担当課長が説明いたしましたようなスチューデント・シティであるとか、あるいはファイナンス・パークを活用した、そういう体験を重視しているという状況があります。","voiceIndex":157,"id":"exchange-072"},{"speaker":"武内委員","kind":"質問・要望","question":"わかりました。３２１ページの荏原東地区の一貫校ですけれども、企画財政課長から朝お話があったときにも、ちょっとあれっと思ったんですけれども、基本設計等委託になっているんですけれども、平成２０年度は基本計画をつくった中で、平成２１年度基本設計というご説明もあったんですけれども、その辺の基本設計等委託の内容について教えてください。","respondent":"市川庶務課長","answer":"この荏原東地区の小中一貫校の建設計画につきましては、通常、これまでの実施例で、基本設計、実施設計、１年ずつかけてまいりましたところを、基本設計の前に条件整備の必要があるという判断をいたしまして、基本計画ということで組み込みをしたものです。","voiceIndex":159,"id":"exchange-073"},{"speaker":"武内委員","kind":"質問","question":"わかりました。そこら辺が気になっていたものですから。今おっしゃったように、いろんなものが、施設もあったりとか、それでどちらに校舎をどうするのかとか、いろんなことであって、それを設計ごと任せちゃうのかなと思ったら、そういうわけじゃないわけですね。じゃあ、もう１回ご答弁を。","respondent":"市川庶務課長","answer":"基本設計に出すときの設計条件、これの一定の整理をした上で行っていきたいです。","voiceIndex":161,"id":"exchange-074"},{"speaker":"武内委員","kind":"質問","question":"そうすると、どのような形で、スケジュールもあわせて、地域、どういう形で、例えば検討委員会みたいなものをつくってやっていくのか。それとも、区のほうであら方プランをつくった上で、それを地域の方にお示しして、同意を得ていくのか。どんなやり方で、また、検討委員会みたいなものをつくるのでしたら、そのメンバーというか、単位を教えてください。","respondent":"市川庶務課長","answer":"今回も、手法としては同じことを考えてありますけれども、その範囲、期間、これについては、どのようにするか、現在検討しています。","voiceIndex":163,"id":"exchange-075"},{"speaker":"武内委員","kind":"質問・要望","question":"ある程度、スケジュール等また固まった段階で、それぞれの場でお知らせいただきたいと思いますけれども、いずれにしても、非常に難しい場所だったりとか、分断されているということもあって、いろいろ逆に可能性もあるかなと思っていますので、非常にいいものができるように期待して、また地域の方の意見をぜひ反映していただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":165,"id":"exchange-076"},{"speaker":"大沢委員","kind":"質問・要望","question":"３０３ページ、研修、教職員研修だと思うんですが、教育指導費、３０７ページ、教科書採択事務、それと３２７ページ、シルバー大学、３２６ページ、生涯学習ということでお伺いをします。３０３ページの上からいきます。研修なんですけれども、これは職員の研修ではなくて、私が今日聞こうと思ったのは、ちまたで言われているクレーマー、そして、モンスターペアレントに関してお伺いしたいと思いました。","respondent":"河野指導課長","answer":"こんな言い方をすると大変失礼かもしれませんが、どちらかというと、そのお子さん、あるいは自分の考え方を周囲に合わせるのではなく、自分の考え方に周囲を合わせよう、そういう傾向が最近強くなってきているなと感じているところです。","voiceIndex":167,"id":"exchange-077"},{"speaker":"大沢委員","kind":"質問","question":"先ほどちょっと言い漏れました。まさに自己中心的な苦情ということが実際にあるのだということを、今、改めて認識をさせていただきました。生徒の指導もあると思います。進路の指導もあると思います。これは、先生が一手に引き受ける部分、大変なところがありますけれども、クレームに対処している学校の組織の中、あるいは教育委員会の組織の中、あれば、お伺いしたいと思います。","respondent":"河野指導課長","answer":"学校だけで対応が不可能な事例については、こちらのほうからも関係職員、指導主事等を派遣する、あるいは、地域からも主任児童委員であるとか、民生委員、あるいは児童相談所の方等々、さまざまな人に集まっていただいて、対応について協議をし。","voiceIndex":169,"id":"exchange-078"},{"speaker":"大沢委員","kind":"質問・要望","question":"去年ですか、港区のほうで管理室というんでしょうか、専門の部署を設けて、警察、また弁護士が中に入って、極端にエスカレートしたクレームには対応しましょう、そして、先生方の負担を軽くして、子どもたちに教えることに先生方の心血を注いでいただこう、そういう体制を整えましたけれども、それについて感想を聞かせていただきたいと思います。","respondent":"河野指導課長","answer":"港区では、そういう制度をつくって対応されているようですが、本区の教育委員の中に弁護士もいらっしゃいますので、法律にかかわる部分についてはいろいろアドバイスをいただいて、それを学校のほうにも提供させていただいているところです。","voiceIndex":171,"id":"exchange-079"},{"speaker":"大沢委員","kind":"質問","question":"そうですね。本会議のときにいつも前に座られている方が弁護士ということを忘れておりました。わかりました。それはそれで対処していただくようにお願いしたいと思います。次、３０７ページ、教科書の採択事務ということで、朝の説明のときに、平成２１年度より小学校でということで説明を受けました。すいません。これ、もう１回説明を伺いたと思いますので、よろしくお願いします。","respondent":"河野指導課長","answer":"小学校、中学校で使用される教科書は、原則として４年に１回採択がえを行うです。現在、小学校で使われている教科書、平成２０年度でもってちょうど４年目になりますので、平成２１年度から使用する教科書について採択を進めるものです。","voiceIndex":173,"id":"exchange-080"},{"speaker":"大沢委員","kind":"質問・要望","question":"ふれあい、いきいき、うるおいと、３カ年修業年限があります。各１年間に応じてカリキュラム、３年間学んでもらうわけですけれども、中には、これからまさに、先ほどの生涯学習、団塊の世代を見据えた場合に、さらに３年間を終えて、また新たに大学へ入学できるのか、できないのか、まずそれを最初に伺わさせていただきたいと思います。","respondent":"富田生涯学習課長","answer":"シルバー大学ふれあいアカデミー、３年制のコースですが、随分応募抽選倍率は減ってまいりましたが、平成１９年度も１.５倍という状況でございまして、まだまだ皆さん、お受けできる状況ではございませんので。","voiceIndex":175,"id":"exchange-081"},{"speaker":"大沢委員","kind":"質問・要望","question":"勉学というか、ものを学びたい気持ちというのは、ご遠慮いただきたいといっても、ご遠慮できるものでもない部分もあると思うんですね。学びたいという、一生勉強するという、生涯学習というわけですね。そう思ったんですが、大学があるのであれば、大学院もつくっていただいたらいかがかなと、こういうふうに単純に思ったんですけれども、そこはいかがでしょうか。","respondent":"富田生涯学習課長","answer":"そういったところを支援していくとともに、例えばシルバー大学全体の仕組みを、行政がやっていく現在の状態でいいのか。もっともっと拡大していく仕組みづくりができていけばいいなというような、そういったところも含めて検討していきたいと考えているところです。","voiceIndex":177,"id":"exchange-082"},{"speaker":"大沢委員","kind":"質問","question":"動機づけになると思いますので、ぜひとも検証の上、ご検討願いたいと思います。これ、文化のほかに、学習も入っているわけでありまして、文化センター、これからの時代といいますか、これから先にかけて、文化センターという名称、私はちょっともう１回考えを直していただき、文化センターというのが合っているのか、合わないのかなという気がしますので、そこのところ、ちょっとご答弁ください。","respondent":"富田生涯学習課長","answer":"生涯学習、スポーツ、文化含めての活動ができる施設としての名称、文化センターとしても、私はそんなにおかしくないとは思いますが、その辺は、文化センターのこれからの発展、内容等を含めて検討課題の１つということで検討させていただきたいと思っています。","voiceIndex":179,"id":"exchange-083"},{"speaker":"大沢委員","kind":"質問","question":"やはりいろいろと文化ということを考えると、課長のほうでは文化でおかしくないと。それはお互いのいろんな考え方があるからいいと思いますが、私は、少なくともこれから先々、文化センター云々という名称よりは、むしろこれからの時代に合ったよりよい名前、考えていただければいいんじゃないかなと思いまして、希望を言いまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-084"},{"speaker":"稲川委員","kind":"質問","question":"３２７ページにあります施設予約システム改修・管理経費について、質問をよろしくお願いいたします。何を改修、どういう形にするか、内容と、経費と改修が一緒に３,２００万円余になっておりますので、内訳を教えていただきたく思います。初めて利用する方にとっては、あまり利便性がよくないのではないかと、そういうのも含めての改修なのかどうか、お聞かせください。","respondent":"富田生涯学習課長","answer":"施設予約システムについてのお尋ねですけれども、施設予約システムはスポーツ系が平成１４年１０月、そして、翌年の初めに文化・集会所系ということでスタートしたものでございまして、既に導入してから５年以上経過しておりまして。","voiceIndex":183,"id":"exchange-085"},{"speaker":"稲川委員","kind":"質問","question":"経費、３,２００万円ですよね。これ、まとめて改修と管理経費という形になっているので、大体どれぐらいの予算配分なんでしょうか、教えてください。","respondent":"富田生涯学習課長","answer":"リプレースの経費は１,４００万円でございまして、あと、予約システムのソフトウェアの保守等の経費が約１,０００万円。大きなところはそういったところです。","voiceIndex":185,"id":"exchange-086"},{"speaker":"稲川委員","kind":"質問","question":"さまざまな形で予約システム、５年たっているということなんですが、予約方法について、ホームページを見ますと、インターネットからの予約と窓口などでの予約という形になって、例えばグラウンドの件とかになりますと、そう書いてあるんですが、グラウンド限定で大変申しわけないんですが、区内の使用者と区外の使用者で、ネットからの予約と窓口からの予約とあると思うんですが。","respondent":"富田生涯学習課長","answer":"運動施設、予約に当たっての区内、区外の比率ですけれども、区内が８割強でございまして、区外が１７％程度です。","voiceIndex":187,"id":"exchange-087"},{"speaker":"稲川委員","kind":"質問","question":"やっぱりネットからの予約のほうが多いんですか。それとも、窓口に行っての予約が多いか。","respondent":"富田生涯学習課長","answer":"失礼いたしました。公園運動施設と体育館と状況が違うわけですけれども、公園運動施設、野球場、サッカー場、テニスコート等につき、屋外の公園運動施設につきましては、約９５％がインターネットの申し込みでございまして、体育館につきましては、約７６％です。","voiceIndex":189,"id":"exchange-088"},{"speaker":"稲川委員","kind":"意見","question":"それ、誤っていたら申しわけございません。それ以外の人は１カ月前からの予約という話なんですよ。今回、ネットの予約に関しても、ここは、多分区外、区内、同じスタートライン、あんまり利用料金は触れたくないんですが、利用料金はちょっと安くなっているという形にはなっているんですが、区内と区外、料金以外で、申し込みを早くするとかという、そういう差別化はどうでしょう。","respondent":"富田生涯学習課長","answer":"体育館につきましては、区内の方が優先でということになっておりますが、公園運動施設につきましては、区内、区外、料金での違いはありますけれども、そういった差異は設けていない現状がありますので、その点については今後検討して、改善していきたいと。","voiceIndex":191,"id":"exchange-089"},{"speaker":"稲川委員","kind":"質問","question":"何でですかと聞いたら、近所からのクレームが入って、朝からうるさいと。大体クレーマーというんですか、大体１人の人が、どれぐらいの人が、住民全員がうるさいからやめてくれと言うんだったらわかるんですが、結局使えなくなってしまったと。使えなくなったというよりも、それを判断する人、例えば校長先生が使うなと言うのか、それとも、それはどの部分、だれが判断をすることか、教えてください。","respondent":"富田生涯学習課長","answer":"学校施設でありますので、最終的には学校長になろうと思います。","voiceIndex":193,"id":"exchange-090"},{"speaker":"稲川委員","kind":"意見","question":"現場に行って、いろいろ采配を振るっていただいているのは、非常にありがたく思うんですが、やはり子どもたちがスポーツをするというのは大切なことだと思いますので、何とか、中途半端に入るのではなく、そこは何とか住民の方を説得するほうにいってもらいたいんですが、どうでしょう。","respondent":"富田生涯学習課長","answer":"ですから、少年少女スポーツの団体につきましても、校庭に限らず体育館でもそういうことは往々にしてあるのですけれども、そういったことの上に、いろいろ同じ地域の方々同士になりますので、その辺は私どももできる限り努力してまいりますけれども、地域の子どもたちのために。","voiceIndex":195,"id":"exchange-091"},{"speaker":"稲川委員","kind":"質問","question":"本当に長い答弁ありがとうあります。１回、校長先生の判断で、使っちゃだめだよと言われたときに、次に、どうしても使いたいと言ったときに、使えなくなってしまうわけですよね。子どもたちはそこの学校を中心として野球をしているわけですから、ぜひ利用をまた再開させたいという思いもありますので、それは、もう地域住民との話し合いということになってくるんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-092"},{"speaker":"高橋委員","kind":"質問","question":"３０３ページの教育指導費、３０５ページのすまいるスクール運営費、それから、３０７ページの特別支援教育費、３２７ページの団体等支援事業、地域スポーツ活動の支援費ですか、先ほどの続きから、すいません、３２７ページか３２９ページ、どちらかちょっとわからないんですが、昨日課長に答えていただいたんですが、鮫洲の公園のＡＥＤの件で、こちらでスポーツ協会で何台か保有し、貸し出すとか、あと。","respondent":"富田生涯学習課長","answer":"したがいまして、その他の貸出用のＡＥＤの準備につきましては、検討課題とさせていただきたい。今後検討していきたいと思います。","voiceIndex":199,"id":"exchange-093"},{"speaker":"高橋委員","kind":"質問・要望","question":"３０３ページの教育指導費と、教育指導費全般という感じになるんですが、先ほど私立の中学、あるいは中高一貫の受験者が２０％から二十数％というお話があったんですが、これだけ私立を受験する児童が多くなり、かつ、学校選択制で、品川区の中のどこの中学校に行こうかなと考える生徒、児童、または、一番近い中学校に行こうという児童が増えてきていると思うんですが、これは、数年前に比べると。","respondent":"藤森小中一貫教育担当課長","answer":"小学生に対する進路指導についてですけれども、これは、当然６年生になれば、中学校に実際に行ってみて、いろんな中学校を見たり、中学生の生活というのはどういうものかというようなものを体験したり、あるいは。","voiceIndex":201,"id":"exchange-094"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、例えば中学校になると、高校受験のときに３者面談といいますか、そういうことをして、親と子どもと担任がお話をしたりするんですが、受験ということではなくて、進路について考える、将来のことを考えるいいチャンスが小学校の６年生のときに来ると思うんですが、そういった３者面談みたいなようなことを、ある小学校ではやってみて。","respondent":"藤森小中一貫教育担当課長","answer":"その中の１つの方策として、小学校６年生においては、３者面談をきちんとして、自分の子どもがどこの中学校に行くのかということをしっかりと親子で相談しながら決めていこうというような機会を小学校の中で設けようということで、すべての小学校で今行われているところです。","voiceIndex":203,"id":"exchange-095"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、今度は中学校のほうなんですが、私立中学に行った子はあれなんですが、残念ながら希望がかなわずに公立の中学校に入学した子がいると思うんですが、その子は、自分として、第一希望は私立で、公立になった場合には、自分で切りかえられれば非常にいいと思うですが、自分なりにいろいろ悩みを持って、公立中学で頑張ろうとなった子はいいんですが、そういった子どもたちが心を病んで。","respondent":"河野指導課長","answer":"私立中学校の受験に失敗して公立中学校に入学してくる子どものケアですが、いろいろな悩みについて、親御さんから直接相談を受けるケースもあります。そういうようなケースについては、スクールカウンセラーもおりますので、そういう方とも連絡をとりながら対処しています。","voiceIndex":205,"id":"exchange-096"},{"speaker":"高橋委員","kind":"質問","question":"３０５ページのすまいるスクールのほうをお尋ねしたいと思います。すまいるスクールに関しては、保護者の期待は非常に大きく、すまいるがどうなっているかで学校選択をされている保護者の方もいらっしゃるとお聞きして、品川区の施策としては、保護者の方々の期待を随分担っていると思います。","respondent":"市川庶務課長","answer":"どこの学校かということでお尋ねですけれども、例えばご質問の中にございましたけれども、特別支援学級が置かれている学校、基本的にはそこの児童については、そこのすまいるスクールで受けてあります。","voiceIndex":207,"id":"exchange-097"},{"speaker":"高橋委員","kind":"意見","question":"先ほど介助員と学習支援員のお話があったんですが、すまいるのほうでは、今ちょっと人数のお話はあれだったんですが、すまいるのほうでそういった支援を必要とする子、配慮を必要とする子がいた場合に、人的なそういった配慮等はどのようにされているのか、お尋ねしたいんですが。","respondent":"市川庶務課長","answer":"子どもの状況に応じて必要な人的措置をしています。","voiceIndex":209,"id":"exchange-098"},{"speaker":"高橋委員","kind":"質問","question":"それは人的に増やす、指導を厚くするということでよろしいんでしょうか。","respondent":"市川庶務課長","answer":"児童の状況に応じて必要な場合には必要な措置をとる、こういうものです。","voiceIndex":211,"id":"exchange-099"},{"speaker":"高橋委員","kind":"意見","question":"その子どもたちがどんな状況かということを把握するために、すまいるの方々は、参加登録申込書にいろいろ書いてもらっているみたいなんですが、そこにはあまり詳しいことは書かないようになっているんですけれども、学校との打ち合わせとか、連携といいますか、職員会議に出るかどうかというのはいろいろ問題があると思うんですが、学校との連携はどのようにされているのか、お尋ねします。","respondent":"市川庶務課長","answer":"特に指導上、配慮、健全育成の指導上、すまいるスクールで配慮を要する子については、学校側とも十分連携をとって対応をしています。","voiceIndex":213,"id":"exchange-100"},{"speaker":"西本委員","kind":"質問","question":"３０３ページ、生徒指導対策費、特に中学生においてお聞きします。まとめて質問します。結局、これは１つの例なんですけれども、中学校の生徒指導というのは、どういう考えでやっているのかなということが非常に疑問になりました。それから、特別支援学級においては、小中一貫教育という観点から、特別支援学級の一貫した政策、考え方というのはあるのかどうかお聞きしたいと思います。","respondent":"河野指導課長、古里学務課長、市川庶務課長","answer":"小中一貫教育における特別支援学級ですが、基本的には、理想から言えば、グループごとに特別支援学級を設置するというのが一番望ましいとは思うのですが。食物アレルギーへの対応のお弁当持ち込みの件ですけれども、できるだけ学校でということでございましたけれども、これは。２点目のすまいるスクールの利用時間、開設時間、現在の午前９時から午後６時まで、これについては変更する考えは持ってございません。","voiceIndex":216,"id":"exchange-101"},{"speaker":"西本委員","kind":"質問・要望","question":"例えば小さいコンロを１つ準備していただければできるところもあるだろうし、もっと広く考えていくと、センター方式みたいな形で、例えばそういう調理のところの、調理の施設があるようなところを利用して、複数校の拠点方式になるんでしょうけれども、そこでそれぞれのメニューを、統一メニューなわけですから、そこで対応していくというような方法も、今後展開、すぐとは言いませんけれども。","respondent":"河野指導課長、古里学務課長、市川庶務課長","answer":"学習の場が、通常学級、あるいは特別支援学級、あるいは通級、さまざまな場面が想定されますが、学ぶ場所の違いではなくて、小中一貫教育の中で学ぶ子ども。センター方式のご提案ですけれども、これは確かにそういうことをやっている自治体もあるんですが、一人ひとりの子どもの症状が違う。それと、２点目のご質問は、少なくともすまいるスクール、放課後の健全育成指導という場面で、子どもの自立なり、あるいは社会性を育むということで。","voiceIndex":220,"id":"exchange-102"},{"speaker":"西本委員","kind":"質問・要望","question":"最後２点ほど確認、それから要望しますが、すまいるスクールの中で、水分補給の状況を確認するというお話でしたが、仮に例えばすまいるスクール、それから、保護者の方の協力で、製氷機とかを設置したいといった場合には、学校施設の中でそういうことはできるのでしょうか。そういう許容範囲があるのかどうかというのを１点お聞きします。いかがでしょうか。","respondent":"市川庶務課長、古里学務課長","answer":"すまいるスクールの水分補給の件については、とにもかくにも実情を把握した上で対応を考えたいと思います。現状の中でどうなのかということ、それから、あるべき姿としてどうなのか。この辺を検討します。民間に移行する中でです。業者の中からもしっかりとしたアレルギー対応をしたいという提案もありますので、これからの検討課題とさせていただきたいと思います。","voiceIndex":224,"id":"exchange-103"},{"speaker":"本多委員","kind":"質問・要望","question":"それと、３３５ページの図書館経費の中で、五反田図書館臨時窓口運営についてということで、今まで教育総合会館の中にあった図書館が、ＴＯＣのほうに臨時窓口ということになっておりますが、先ほども原委員から教育複合施設について質問がありましたけれども、その工事中ですか、このオープンが、プレス発表でいくと平成２２年の１０月がオープンということなんですけれども、その間。","respondent":"市川庶務課長、河野指導課長、工藤品川図書館長","answer":"その結果、今の段階ですけれども、今年予定しております周年行事のうち、１１月の後半の２回の土曜日については。そちらのほうに情報センターとしての機能も移しますが、その情報センター機能の中の現在設置しております教科書センター。スペースですけれども、約６０m2ということで、小さな書店のような形のスペースになります。家賃ですけれども、月々賃貸料は約３０万円ほどを見込んです。","voiceIndex":228,"id":"exchange-104"},{"speaker":"本多委員","kind":"質問","question":"校地借地料のほうなんですけれども、３年おきで見直しということでわかりました。窓口だけになるんでしょうか。これ、ちょうど複合施設がオープンをすると、平成２２年のときまで借りて、その後ＴＯＣに旧第一日野小を貸すという、入れかわるような、ちょうどタイミングになるのか、そこを教えてください。","respondent":"市川庶務課長、工藤品川図書館長","answer":"さらには、それができなくとも、改築承諾料、改築する際の承諾料については無償としてほしい。こういう旨を要望してきている経過があります。今後とも同様の働きかけを継続して行ってまいります。ＴＯＣビルの臨時窓口の提供サービスですけれども、資料の取り次ぎはもちろんですけれども、話題、人気本を中心とした簡単なベストセラー本、あと、旅行ガイドブック本を中心としまして。","voiceIndex":232,"id":"exchange-105"},{"speaker":"山路委員","kind":"確認","question":"私のほうからは、３０５ページ、プラン２１関連事業について、３３１ページ、歴史館経費について、３３３ページ、図書館経費についてお伺いをいたします。平成１２年の決算特別委員会で、当時いろんな提言がございました。そこで、濱野新区長誕生の予算編成に当たりまして、改めて、全体の教育界のトップとして、教育長に、教育とはということで確認をしたいと思いますので、よろしくお願い申し上げます。","respondent":"若月教育長","answer":"区長部局、そして、議会の皆さん方の応援があったらばこそ、ここまで来られたという気持ちをいつも忘れずにこれからも頑張ってまいりたい、こんなふうに思っております。","voiceIndex":236,"id":"exchange-106"},{"speaker":"山路委員","kind":"意見","question":"通告しておりませんでしたので、突然で申しわけございませんが、今いただいたんですが、私が尋ねたのは、教育とはという、教育は何のため、教育の目的について改めてご答弁をお願いいたします。","respondent":"若月教育長","answer":"失礼いたしました。教育とは何か、いろいろな言い方があろうかと思います。今、私の気持ちでは、教育とは、未来を創造する最も基本的な営みである、こんなふうに考えております。","voiceIndex":238,"id":"exchange-107"},{"speaker":"山路委員","kind":"質問","question":"習熟度別学習、プラン２１関連事業についてですが、習熟度別学習と職場体験、先ほど武内委員がお尋ねしましたが、別の角度からお伺いします。習熟度別学習についてですが、学力向上ということで、毎年毎年議会でも議論がされ、そして一歩一歩前進させたという現場で、お母さん方からもお伺いしておりますが、どういう現在取り組みをされているのか、お伺いをいたします。","respondent":"藤森小中一貫教育担当課長","answer":"こういう成果が出てきたなという認識を持ってあります。学校のほうといたしましても、この習熟度別学習の方法なども絶えず校内研究会等で取り上げながら工夫・改善をしています。","voiceIndex":240,"id":"exchange-108"},{"speaker":"山路委員","kind":"質問・要望","question":"そういう中で、一方、豊かな人間性の育成、教育長はよく、教育とは人なりということを私も何回か聞いたことがあるんですが、この教育長のお考えの教育とは人なりということについて、教育現場ではどのように生かされているのか、お聞かせをいただきたいと思います。","respondent":"藤森小中一貫教育担当課長","answer":"具体的には、いろいろな成果が報告されているところでありますが、特に規範意識だとか、あるいは、公徳心、集団行動、こういうようなところに成果が出ているなということを教育委員会としても認識しています。","voiceIndex":242,"id":"exchange-109"},{"speaker":"山路委員","kind":"提案","question":"抽象的にだんだんなっていきますので。先ほど職業体験、地域との、また、まちの人々から学ぶ授業についても取り入れて、非常に効果を出しているということでございましたが、この職業体験は、私ども提案させていただいた関係で、ずっと何回も、予算、決算で質問させていただきましたが、進学、進路における職業体験として、非常に重要な意味を持つんじゃないかということをかつて質問したことがあります。","respondent":"河野指導課長","answer":"まだまだ多感な中学生時代ですので、この時期に５年先、あるいは１０年先の進路を、職業を具体的に決定するということは実態としては非常に難しいものがあります。","voiceIndex":244,"id":"exchange-110"},{"speaker":"山路委員","kind":"質問","question":"両面に大事な教育だと思いますので、どうぞよろしくお願いいたします。続いて、情報教育につきまして、インターネット活用等で、マスコミでも、児童・生徒のいろんな事故が起こっておりますが、昨年お伺いしたときに、学年によって情報教育の教え方は変わっているということで、今後検討している話もされましたが、現状ではどのような教育をなされているのか、お伺いいたします。","respondent":"河野指導課長","answer":"今年度、新たな取り組みということで、これはネット関係の業者ですが、ニフティというところの協力で、小学生を対象に体験シミュレーション、今、ニフティで開発中のものですが、それを具体的に使って、パソコン上でそういうサイトの恐ろしさ、これを子どもたちに体験させて。","voiceIndex":246,"id":"exchange-111"},{"speaker":"山路委員","kind":"質問","question":"次は、歴史館についてですが、歴史館につきましては、収蔵、倉庫に入っている作品ですね。インターネット美術館等で紹介をされていると思うんですが、収蔵されているものに関して、貸し出しとか、そういうものはされているんでしょうか。","respondent":"富田生涯学習課長","answer":"収蔵資料、浮世絵ですとか、さまざまありますけれども、貸し出しをする場合は、それぞれ、例えば出版物に使用したいですとか、他の博物館等で展示したいといったような申し出があったときには、申請書を受けまして、貸し出しをしております。","voiceIndex":248,"id":"exchange-112"},{"speaker":"山路委員","kind":"提案","question":"歴史館に、先ほども質問がありまして、入場者数とかお答えになっていたんですけれども、以前、特別展によっては、多くの人が来たり、少なかったりという、そういう傾向もあったみたいですけれども、私は、時代的にサプライズと言われておりますが、歴史館に入館した方が体験をできるようなコーナーを設けたらいいんじゃないかとご提案したいんですけれども、どのようにお考えでしょうか。","respondent":"富田生涯学習課長","answer":"子ども向け、夏休みなどにいろいろ講座等を行っておりますけれども、その中でも、土器を焼いてみようですとか、勾玉をつくってみようですとか、そういったところでのものは実施しておりますし、これからも検討していきたいと思っています。","voiceIndex":250,"id":"exchange-113"},{"speaker":"山路委員","kind":"意見","question":"多くの区民の方に、多くの小中学生に品川の文化、歴史を知っていただくことをお願いしておきます。続いて、図書館ですが、ＢＤＳについて、品川図書館には設置してあるということですが、その作動について、装置についてはどのような経緯があるか、お聞かせください。","respondent":"工藤品川図書館長","answer":"ＢＤＳ、ブックディテクションシステムといって、いわゆる不正持ち出しを感知するシステムです。今、品川区、１０館図書館がございまして、今、品川、荏原、それで来年度、大井図書館のほうに新たに入れる予定です。","voiceIndex":252,"id":"exchange-114"},{"speaker":"飯沼委員","kind":"質問","question":"３０５ページのすまいるスクールについて、いじめ問題にもちょっと触れますのでよろしくお願いいたします。運営委託費を見ますと、６億を超えているんですけれども、内容を具体的に、どこが変わるのか、あと、派遣の職員のところでは、１校何人配置されて、ローテーションを組んで、１日当たり何人の配置なのか。入れかわりがどのぐらいあるのか、把握できるのかどうか、その辺も教えてください。","respondent":"市川庶務課長","answer":"一方、運営委託費が１億８,０００万円ということで、この差額の４,６００万円、これが変更点になってあります。そして、次に、平成２０年度の委託の予定ですけれども、５社によりまして３８校のすまいるスクールの事業を進めてまいります。","voiceIndex":255,"id":"exchange-115"},{"speaker":"飯沼委員","kind":"質問・要望","question":"委託がさらに広がって、３８校ということで、驚いて受けとめていますけれども、不安定雇用の指導員が非常に多くなるわけですけれども、安定した運営ができるのかどうか、この点を後でお答えをいただきたいと思います。すまいるの中での学童保育機能に絞ってこれからお伺いしますけれども、学童保育が児童福祉法に位置づけをされて今年で１０年になります。保護者への支援、連携についてはこう書かれています。","respondent":"市川庶務課長","answer":"それと、国の放課後子どもプランの実施に伴って、放課後児童クラブガイドラインというのが昨年１０月に東京都を経由して伝えられてきました。","voiceIndex":257,"id":"exchange-116"},{"speaker":"飯沼委員","kind":"質問・要望","question":"たびたびの質問の中で、すまいるの中には学童保育機能が入っていますというご答弁のもとなので、この学童機能についてお伺いをしているわけなので、そういった意味でお答えをしていただきたいと思います。その辺の把握があったら聞かせていただきたいんですが、そういった不安定な雇用の体制で安定した運営ができるのかどうか。その辺をたった１人の正規職員に全部負わせていて、できるのかどうか。","respondent":"市川庶務課長","answer":"その場でそれぞれスタッフにどういう指示を出して、どういうマネジメントをしていくか。これが私どもの配置している正規職員の役割だと思ってあります。それぞれ指導員については、十分その役割を果たしていると私は認識しています。","voiceIndex":259,"id":"exchange-117"},{"speaker":"飯沼委員","kind":"質問・要望","question":"専任の指導員が丸ごと委託された派遣の皆さんと一体となってやれるのかどうか、私はこれ、ちょっと疑問なんですが、ここをお答えいただきたいと思います。特にすまいるの指導員は、正規１名ではなくて、ぜひ正規雇用を増やして、せめて正規複数の配置にしないと、見えていない子どもたちの問題、心の中の問題まではとても対応できないと思うんですが、いかがでしょうか。","respondent":"市川庶務課長","answer":"丸ごと委託ということですけれども、私は、先ほど来の答弁の中で、丸ごとに相当する答弁をした覚えはございませんので、何が丸ごとなのかというのを逆にちょっと疑問に感じてあります。","voiceIndex":261,"id":"exchange-118"},{"speaker":"飯沼委員","kind":"質問","question":"すいません。委託の形式はどうなんですか。丸ごと委託ですよね。請負と言われる丸ごと委託ですよね。違うんですか。","respondent":"市川庶務課長","answer":"すまいるスクール事業の業務の一部の委託です。","voiceIndex":263,"id":"exchange-119"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は、大変な体制の中で、１人の専任指導員に任されているこの体制をぜひ変えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":267,"id":"exchange-120"},{"speaker":"阿部委員","kind":"提案","question":"本日は、３２６ページ、生涯学習について、全般の話を伺いたいと思います。さきの本会議の中で別の議員からも出ておりました、生涯学習課を区長部局に移してはどうかというようなご提案があって、それは私もいいなと思いながら聞いていたんですけれども、実際に、それを移す部分と残すべき部分というようなものもあるんじゃないかと感じております。現段階でのお考えをお伺いしたいと思います。","respondent":"富田生涯学習課長","answer":"現段階での考え方ですが、生涯学習、スポーツの分野を区長部局に移すことが法改正でもって可能になり、他の自治体でも動きがあるという状況はありますが、本区での検討は全くこれからという段階であります。","voiceIndex":270,"id":"exchange-121"},{"speaker":"阿部委員","kind":"質問","question":"こういった形の利用というのも当然今後もあるべきだと思うんですけれども、それ以外にも、プロジェクト型といいましょうか、１つのテーマに沿っていろんな人たちが集まり、そして、また多くの人を集めて１つのことをやったら、それでもうおしまいというような、そういった活動というのもあり得ると思うんですけれども、なかなか今の規定ではそういった形では使いにくい、あるいは場所を借りるときに。","respondent":"富田生涯学習課長","answer":"しかしながら、委員ご指摘の、例えば自分たちが自分たちの定例的な学びですとか、スポーツですとか、そういった活動の自分たちの自己実現のための活動だけではなくて、地域貢献ですとか、ボランティアですとか、あるいはさまざまな社会的な課題。","voiceIndex":272,"id":"exchange-122"},{"speaker":"阿部委員","kind":"質問","question":"ぜひ幅広く検討していただければと思います。先ほど政治活動はだめよということだったんですけれども、それも理解もできますが、しかし、文化センターという場所で、例えば選挙で選ばれた人たちがその活動の報告をして、有権者に説明責任を果たすというのも、それも１つのあり方ではないかと思うんですが、これは見解を伺ってよろしいでしょうかね。","respondent":"富田生涯学習課長","answer":"文化センターの内々の定めによれば、政治活動といっても、すべてがということではございませんで、例えば政党、政治団体内部の政策報告学習会でありますとか、区政報告会等々、そういったものにつきましてはご利用いただくことはもちろん可能です。","voiceIndex":274,"id":"exchange-123"},{"speaker":"阿部委員","kind":"質問","question":"それを聞いて安心しました。次に、学校給食費についてお伺いします。確かに校長の裁量というご説明もあったかと思います。ただ、給食費というのがどれだけの収入があって、どのくらいの滞納があって、そして、どういうお金の出入りでやっているのだというのが、どこかで資料として示されるべきではないかと思うんですけれども、その可能性はありますでしょうか。","respondent":"古里学務課長","answer":"この校長口座に入ったものを毎日の食材費の調達費用に充当し、残額を計算しながら使っていくということでやってありますので、特段特殊なことはやっておりませんので、です。","voiceIndex":276,"id":"exchange-124"},{"speaker":"阿部委員","kind":"提案","question":"これに関しては、今のところいいです。以前の委員会でも、私、ちょっとご提案もさせていただいたことはありますが、その後、品川区内での学校栄養職員の負担軽減策、何かとられていることがあれば教えていただきたいと思います。その中で、本当に２０分ぐらいで食べないと、食べる時間がない。食に関する指導について、給食の時間についての視点も必要なのではないかと思いますが、いかがでしょうか。","respondent":"古里学務課長、河野指導課長","answer":"これが担当の栄養士と一緒に協働しながら２つの学校の給食管理に当たっていくという形を来年度から実現したいと思ってあります。実際には、小学校の場合には、中学校の場合も似たりよったりですが、４０分ぐらいの時間を確保していますが、学年が上がるにつれて、次の昼休みをどれだけ遊ぶのかというほうに気が回りますので。","voiceIndex":278,"id":"exchange-125"},{"speaker":"阿部委員","kind":"質問","question":"フランスなんかの学校で、食の指定校なんかになったりすると、給食時間、９０分ぐらいとると言うんですね。次、３０７ページの特別支援教育なんですけれども、新しく学習支援員の制度をつくられるということですが、１点お伺いしたいのが、電子カルテと個別の支援計画の関係は一体どうなっているのか、教えてください。","respondent":"河野指導課長","answer":"個別の支援計画と申しますのは、その子どもが、例えば義務教育在学中に、学校だけではなくて、例えば医療機関であるとか、あるいは児童センターであるとか、さまざまな機関と関係をしながら成長を見守るというケースがあります。","voiceIndex":281,"id":"exchange-126"},{"speaker":"阿部委員","kind":"質問","question":"その電子カルテ、支援員の方と派遣元で共有し、かつ学校の先生、担任の先生も見ることができるんじゃないか。資料だけ読むと、直接会話ができなくて、文字を通してだから情報交換ができるんだというふうに読めてしまうと、ちょっと違うんじゃないかなと思うんですが、その辺のチームづくりというのはどのようにやっていくのか教えてください。","respondent":"河野指導課長","answer":"特にスクールカウンセラーの役割というものについては、支援員、あるいは介助員のいわゆるケースカンファレンス含めて、情報交換を密にとれるような、そういう仕様にしていますので、できる限りそういうところでチームワークを崩さないように。","voiceIndex":283,"id":"exchange-127"},{"speaker":"阿部委員","kind":"質問","question":"３１６ページの学校施設に関してなんですけれども、昨年の夏に学校整備指針の改定がありました。そこで、すべての幼稚園、小中学校で、特別支援教育を推進するための指針が新たに示されたわけですけれども、品川区の幼小中学校での指針をどのように取り入れていくか、整備計画みたいなものはありますでしょうか。","respondent":"河野指導課長","answer":"差し当たって今進めているところは、今年の４月開級します源氏前小学校の通級学級をはじめ、平成２１年度は、さらに中学校の通級の増設等々、内容によっては、今、準備を進めているものも実際としてはあります。","voiceIndex":287,"id":"exchange-128"},{"speaker":"松澤委員","kind":"質問","question":"２点お伺いします。１点目は、中学校消火ポンプ配備４校、２点目が３１１ページ、校舎等耐震経費、補強工事小学校１０校、中学校１校。小中学校に消火ポンプを配備。教育費ですから、私が質問するのは、中学生の機器操作等の訓練、この点についてお聞きしたいと思います。教育委員会としては、中学校の校長先生にこのことについてどのような通達を出されているのでしょうか。お願いします。","respondent":"河野指導課長","answer":"特に好奇心旺盛な中学生にとっては、こういう機械の操作というものに関心を示す子どももおそらく多数いると思われますので、防災課のほうの応援もいただきながら、希望する子どもたちに対しては積極的に訓練等、呼びかけていただきたいという形で働きかけていく予定です。","voiceIndex":291,"id":"exchange-129"},{"speaker":"松澤委員","kind":"質問","question":"中学校に聞きました。１つの学校、ボランティア部があり、部活として行う。部員は１２名ぐらいと言われている。この指導は地元の消防団に頼む。もう一つの学校ですね。ですから、そこで防災訓練をやるわけですよ。何回か訓練したって、やっぱり子どもたちにとっては、披露する場所、みんなに見てもらう場所がないといけないと思うので、その点をどういうふうに考えているのか、お聞きしたいと思います。","respondent":"久保田防災課長","answer":"これから十分検討していきたいと思います。よろしくお願いします。","voiceIndex":293,"id":"exchange-130"},{"speaker":"松澤委員","kind":"質問","question":"２点目にいきます。３１１ページの校舎等耐震経費、今年は小学校１０校、中学校１校ということですけれども、この１１校をすることによって何校補強工事、これを含めてですね。そして、まだやっていない学校は何校あるのかお聞きしたいと思います。","respondent":"市川庶務課長","answer":"中学校が１８校中８校、これがいわゆる耐震化済みという数字です。残りの小学校１７校、中学校６校ありますけれども、このうちの小学校１０校、中学校１校を平成２０年度に計上している、こういうことです。","voiceIndex":295,"id":"exchange-131"},{"speaker":"松澤委員","kind":"質問","question":"実は、学校の適正な教育環境確保ということで、平成１９年８月に設置した学事制度審議会での審議を継続し、平成２０年１０月を目途に答申を得る。そうすると、二重投資をしませんよという答えがもし来るとするならば、まだ着工してない学校がそういう対象になるのかなという気がしますので、その辺をお聞きしたいと思います。","respondent":"市川庶務課長","answer":"そういうこともございまして、平成２０年度、平成２１年度で一定の事業の振り分けをしています。したがいまして、現在、そういう説明でご理解をいただければと思います。","voiceIndex":297,"id":"exchange-132"},{"speaker":"松澤委員","kind":"質問・要望","question":"今年度、耐震補強する予定だったけれども、改築するので、お宅やらないよと言った学校が二、三校あると思うんですね。これは別に名前を言えという意味ではないんですけれども。そういうのを見ると、私たちはそれを聞くと、あれっ、それじゃあ、この学校そういうあれなのかな。そんなようなもので、何を言ったらいいかわかりませんけれども、しっかりと計画をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":299,"id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"私は、３０２ページ、教育指導費の中の教科書採択と副読本について、同じく教員の異動についてお伺いいたします。新学習指導要領が文部科学省より公表されました。告示は３月末を予定している。学習指導要領が改訂されると、現行の教育課程に合わせた品川の小中一貫教育要領も部分的に改訂することが必要になると思われます。そこで、改訂の作業は、実施するのでしょうか。その２点についてお聞かせください。","respondent":"藤森小中一貫教育担当課長","answer":"それに伴いまして、当然副読本のほうも改訂作業ということで、来年度からそれぞれの各教科ごとのカリキュラム部会において、改訂作業を、検討をスタートするということで考えてあります。","voiceIndex":301,"id":"exchange-134"},{"speaker":"須貝委員","kind":"質問","question":"教科書は本来国の検定を受けたものを採択して、学校で使用しております。品川区の副教材は、副読本ということで、検定は受ける必要はありませんが、指導用教材として、学術的に正しく、信頼性と品質の高い教材でなくてはならないと思います。この品川区版教科書と言われる副教材の質について、検定に匹敵する仕組みを考慮して作成したのでしょうか。それについてお答えください。","respondent":"藤森小中一貫教育担当課長","answer":"この副教科書の大きな特徴としましては、当然現場の声を重視しておりまして、例えばこういう内容でいくと、多分ここのところで子どもがつまずくだろうというようなものについては、現場の先生からたくさんの声を聞きながら作成しているという状況ですので。","voiceIndex":303,"id":"exchange-135"},{"speaker":"須貝委員","kind":"質問","question":"今、かなり高いレベルであるという話も聞きましたが、じゃあ、検定を受けるということは、文部科学省の認定を受けて、学者、そして学識経験者、多くの方が、そして、教科書づくりの経験豊富な方がつくっております。じゃあ、学識経験者は何人いて、現場の先生は何人なんですか。ほとんど現場の先生じゃないんですか。何でもいいんですというわけにいかないと思うんですが、その辺をもう一度お聞かせください。","respondent":"河野指導課長","answer":"それは、それぞれの地域により即した内容で子どもたちに学習をさせるということで作成しておりまして、いずれの区市で作成しているものも、非常に子どもたちにとってはわかりやすい、具体的な教材として各学校で活用されているところです。","voiceIndex":305,"id":"exchange-136"},{"speaker":"須貝委員","kind":"質問","question":"教科書じゃない。それは、授業の時間数が足りないというお話をお伺いしました。現在の品川区版の副教材は、費用対効果の高い教材と言えるのでしょうか。今後もこの副教材をつくり続けていくつもりなのでしょうか。たとえ改訂されなくても、区の税金を今後も投入して、印刷し、配付し続けるのでしょうか。もう一度言います。検定を受けている教科書はただであり、０円であります。ちょっとお答えください。","respondent":"藤森小中一貫教育担当課長","answer":"私どもが学校から報告を受けたり、あるいは、今行っている新教育システムの開発プログラム、小中一貫教育の評価ですけれども、その中でも、教員のアンケートをとったり、さまざまな情報を集めているところですが、例えば市民科の教科書が大変有効であるとか。","voiceIndex":307,"id":"exchange-137"},{"speaker":"須貝委員","kind":"質問","question":"今、現場の先生は必死で大変ですよ、忙しくて。日々追われています。夜７時、８時、場合によっては９時まで残ってやっています。ここで、別の面でお聞きします。品川区で現在副読本を採用していますが、品川区は２つの出版会社を採用しています。これは両方とも副読本をつくったところですが、両者とも副読本をつくったところですが、なぜここで変更したのか、だれが教科書を変更したのか、教えてください。","respondent":"藤森小中一貫教育担当課長","answer":"中学校の教科書採択、検定本の教科書採択につきましては、これはあくまでも内容をいろいろ検討委員会で検討していただいて、最終的に資料に基づいて教育委員会で決定したものです。","voiceIndex":309,"id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"今、教育委員会で決定ということでよろしいんですよね。若月教育長が入っております。この中で、４名の方は少なくても学校の本をつくるという力がありませんし、そんなに学校の教科書を判定する力はないと思います。若月教育長は、申しわけないんですが、中学校で教鞭をとっていたという事実は私は聞いてないんですが、そういう方たちが決めたということでよろしいんですか。","respondent":"河野指導課長","answer":"教科書採択の仕組みについてご説明します。教科書採択につきましては、採択用に検定を通った教科書、すべての教科書について、まず検討委員会でそれぞれの内容について研究をいたします。","voiceIndex":311,"id":"exchange-139"},{"speaker":"須貝委員","kind":"意見","question":"事前に教員の皆さんのご意見は承っていると思います。ですが、途中で教科書が変わるということは、学習指導の連続性の意味からも、教員にとっては大きなストレスになると思います。教員の世界では、２３区の中学校では、教育出版や学校図書は、これは先生の言うことなので、ほとんど２３区内では使われていません。教科書の採択に不自然さを感じるんですが、その辺は全く問題ありませんね。","respondent":"河野指導課長","answer":"教科書の採択に当たりまして、最終的に協議をする場面では、教科書の出版社名は一切伏せて、内容で勝負しております。なお、教科書の採択については、教育委員会が採択すると定められております。","voiceIndex":313,"id":"exchange-140"},{"speaker":"須貝委員","kind":"確認","question":"わかりました。今、確認をとらさせていただきましたので、その話は終わります。次に、今年も日野学園や伊藤学園からも多くのベテラン教職員が異動するような話を聞いております。このような実態があります。このような品川区の教育の現状をどのように改善しようとしているのでしょうか。その認識と今後の対策について説明してください。","respondent":"河野指導課長","answer":"毎年大勢の新採教員が採用されているのは事実です。しかし、品川区では、他の区市に負けないように、例えばその教員が研修に出るときには後補充をつけるなり、あるいはその研修の中身を充実させるなりというような方法をとって、指導力のある教員を積極的に養成しています。","voiceIndex":315,"id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"大田区教育委員会に問い合わせたところ、大田区には教員が約２,０００名おります。教育委員会はないのかもしれないんですが、何年、いつまで区民は待てばその結果を出していただけるんでしょうか。私は、高どまりになるなら、高どまりでいいんですが、このままずるずる、ずるずる行って、いつまでたっても子どもたちの状況が変わらないということは少し考えてほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":317,"id":"exchange-142"},{"speaker":"堺委員","kind":"質問","question":"私のほうから３０２ページの教育指導費に関連して何点かお尋ねします。この中で、全部私も読ませていただいたんですが、講評を大崎高校の校長先生が審査員長としてされた、それがこの文集に載っかっておりますので、ちょっと引用しますと、大変読む側としては、大変いい講評というんですか、ありがたい講評というんでしょうか、そんなので、ちょっと参考に。それは、人の心を大切にすることです。","respondent":"河野指導課長","answer":"一部のこういう子どもたちだけではなくて、１人でも多くのこういう子どもたちが品川区の学校教育を通して育っていくことを私たちも目的、目標として、今後も頑張っていきたいと考えます。","voiceIndex":319,"id":"exchange-143"},{"speaker":"堺委員","kind":"質問","question":"ぜひそういうことで、これからも中学生に対する取り組みについても、なお一層頑張っていただければと思います。それから、２点目に、昨年ですか、第四日野小学校で始められたセカンドステップについて教えていただけますでしょうか。","respondent":"藤森小中一貫教育担当課長","answer":"最近の子どもたちの様子の中に、対人関係がうまくできないために、自分の感情を表現できず、些細なことで突然キレるという方法で問題解決を図ろうとする、そういった子どもたちも見受けられます。","voiceIndex":321,"id":"exchange-144"},{"speaker":"堺委員","kind":"質問","question":"こういう強い要請もされておりますが、そこで、品川区では、現在２４校で実施していると言われておりますけれども、そのとおりでいいのかどうか。それからまた、１０年度までには、４０ある小学校、全校で導入する予定で、これによりますと、年間１０時間で２年間かけて、１年生、２年生について対応していくということが言われておりますが、そういう理解でいいんでしょうか。","respondent":"藤森小中一貫教育担当課長","answer":"具体的には、平成１８、１９年度におきましては、私どものほうでは２２校の実施。来年、平成２０年度におきましては７校、平成２１年度につきましては９校という予定で最終的にすべての小学校で実施したいと考えています。","voiceIndex":323,"id":"exchange-145"},{"speaker":"堺委員","kind":"意見","question":"最近、急速に広がるネットのいじめ。こういうことが言われております。これも、携帯電話でネットに接続できる環境にある小中高生は現在７５０万人いるとも言われております。このように報道されているんですが、この辺について、品川区的には、こういう事実はないだろうとは思うんですが、この辺について、現況、どうなっておりましょうか。","respondent":"河野指導課長","answer":"携帯電話によるいじめ、誹謗中傷等、かなり件数が増えているということは私どもも認識しています。私どもが区内の小中学生を対象にした調査によると、残念ながら、悪口を書かれたというような経験のある子どもが１３.５％という数字も出てきております。","voiceIndex":325,"id":"exchange-146"},{"speaker":"堺委員","kind":"質問","question":"それとあわせまして、最近、インターネットでのいじめに対応できる教師を育てようということから、全国ウェブカウンセリング協議会というところで、学校裏サイトの見つけ方ということで、ご存じかと思いますが、４月から２回ですか、５月以降は月２回から４回、こういう講座を開催されるということも一部報道されておりますが、この辺についてご存じのなかどうか、あわせて。","respondent":"河野指導課長","answer":"今ご案内の講座については、まだ内容等、具体的なことが把握し切れておりませんので、内容等を十分吟味した上で、またその方向性については考えさせていただきたいと思います。","voiceIndex":327,"id":"exchange-147"},{"speaker":"堺委員","kind":"質問","question":"ぜひひとつよろしくお願いいたします。これについて、例えば公教育、これの充実という視点から、やはり公立学校の先生の立場というんですか、資質といいましょうか、それが非常に大事であるということは毎回委員会で取り上げられております。その辺についてのお考え、それから、教員の資質向上に向けての区の取り組み、この２点、残された時間で恐縮ですが、お答えいただければと思います。","respondent":"若月教育長","answer":"これは１つのそのあらわれであると、こういうふうに考えているところでもあります。学習指導要領といったようなものについても、それだけに頼るのではなく、やはり自分たちがカリキュラムを開発していくという能力を身につける。","voiceIndex":329,"id":"exchange-148"},{"speaker":"須藤委員","kind":"質問・要望","question":"そのあたりの評価についてお知らせいただきたいと思います。それから、施設建設費については、小中一貫で、２１世紀における学校教育の教室、施設をつくっていただいているので、そのあたりの留意点というのは、どういう点を配慮されて、一貫校、それから連携校でもつくられています。どういう点を配慮されて考えられてきているのか。そのあたりの連携がどうなっているのか、教えていただきたいと思います。","respondent":"藤森小中一貫教育担当課長、古里学務課長、市川庶務課長","answer":"そういった中で、子どもたちの中から規範意識が高まってきたとか、公徳心だとか、礼儀作法だとか、集団行動。学校医の先生方からは、もう少し子どもの健康に関する具体的な指導に学校に入ってまいりたいというありがたいご要望もいただいてありますので、来年度以降。当然のことながら、学習活動への機能的な対応、それと安全管理、この辺は学校施設として本来十全に備えなければならないものである。","voiceIndex":332,"id":"exchange-149"},{"speaker":"須藤委員","kind":"質問・要望","question":"学校保健費のほうで、この前衛生費でもちょっとお願いしたんだけれども、区民の健康ということが、いわゆる学校は学校だけで、衛生のほうは児童保健事業部はそちらでということではなくて、そこは連携をとってもらいたいと思うので、そのあたりの仕組みはどういうふうになっているか教えていただきたいと思います。","respondent":"藤森小中一貫教育担当課長、古里学務課長","answer":"大変市民科については、全国から注目を集めているなという認識です。児童保健事業部との連携の仕組みですが、昨年麻疹が流行したときには、児童保健事業部と学務課、教育委員会が協力をしながら対応してまいりました。","voiceIndex":336,"id":"exchange-150"},{"speaker":"須藤委員","kind":"質問・要望","question":"市民科、つくって、今、プラン２１、着々と進めているので、また議会としてもしっかり見守って、応援をしていきたい。変なおじさんに声をかけられてもしゃべるんじゃないよというような教えをしていればそうなっちゃうし、あるおばあさんは、ああいうふうにあったら、もう声かけないんだなんていう話もあるので、教育現場は、８３運動とどういうふうに連携をとっているのか、教えてください。","respondent":"藤森小中一貫教育担当課長","answer":"今後とも、地域に出ても、あいさつを徹底するように学校のほうにも指導してまいりたいと考えています。","voiceIndex":339,"id":"exchange-151"},{"speaker":"須藤委員","kind":"意見","question":"毎朝、そのおじいさんは、庭掃除しながら声をかけているんだと。「あなた、顔が怖いんじゃねえか」と言ったら、「そんなことないよ」なんていう話をしているんだけれども、やはり逆にお子さんのほうから「おはよう」と声をかけるぐらいに親しくなってくるのが８３運動の目的だろうと思うので、そのあたり、学校教育現場のほうもやはり承知をしながら、タッグを組んでやっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":341,"id":"exchange-152"},{"speaker":"川西委員","kind":"質問","question":"小中一貫校、それから２番目が３１７ページ、学校施設建設費に関連して、３番目が職員の研修に関連、それから４番目が幼稚園の関係で伺います。時間があれば、夏季施設です。そういう点で、楽しい子育て、学校に行ってもそうなんですけれども、それを保障するためには、小中一貫校、区域を定めないで、中学校のようにフリー化をすることについてどのようにお考えか、改めて伺います。","respondent":"古里学務課長","answer":"一般質問でもいただいたご質問ですけれども、今、小中一貫校につきましては、鋭意計画を早期実現するよう努力をしているところでございまして、各地区にそれぞれ一貫校があり、遠くないところでも一貫校があるという状況をできるだけ早くつくりたいと考えていますので。","voiceIndex":343,"id":"exchange-153"},{"speaker":"川西委員","kind":"質問・要望","question":"４月に入学する子どもたちが、例えば荏原東地区ができるのが、その子が卒業してしまう。そういうように待っていただきたいと言っても、これは、いろいろお考えもあるかと思いますけれども、チャンスを与えてほしいということをぜひお願いいたします。先だっての質問のときに、いろいろ部課長たちにお話を伺いながら、そういうふうに思っているんですが、それを取り消すためのご答弁をいただければ幸いです。","respondent":"市川庶務課長","answer":"自然エネルギーの活用につきましては、学校施設としての備えるべきもの、それと、先ほどのご質問にもございましたけれども、公共施設としての役割、この２つの視点から今後の建設計画の中で検討させていただきたい。こういうことで先日来説明をさせていただいてあります。","voiceIndex":345,"id":"exchange-154"},{"speaker":"川西委員","kind":"質問","question":"平成１９年度の実績の中で、例えば施設のほう、例えば荏原第五中、日野学園、伊藤学園、小山小学校、第二延山小学校と、建設を実施してきましたよね。その中で、受け入れていただいたのが何％か、このぐらいだと、数％に満たないというようなことでした。これは、ご答弁いただくのは、同じようになりますので、結構です。３番目は、職員研修の中で、食育研修をどのように取り入れられているか、伺います。","respondent":"河野指導課長","answer":"現在食育研修という形で都で実施しておりますが、対象がそれぞれの学校に配置されている栄養職員です。こちらのほうに積極的に参加するようにしております。","voiceIndex":347,"id":"exchange-155"},{"speaker":"川西委員","kind":"質問・要望","question":"やっぱり素材からつくっていくという姿がなくて、もう少し教員の方も子どもたちと一緒に給食を食べるんですから、食育についての基礎的な認識をぜひ取り入れていただきたいなと思います。そこでもう一つ質問ですが、給食を食べられない教員の方っていらっしゃるんでしょうか。","respondent":"河野指導課長","answer":"現在のところ、若干名、体調の関係等で、給食がだめだと、正式に言うと、私どもで把握しているのは１名だけですが、それ以外の教員はすべて給食を食べております。","voiceIndex":349,"id":"exchange-156"},{"speaker":"川西委員","kind":"質問","question":"そういう中で、最近は、時代が変わってきて、そういうことが、今、伺いましたご答弁のように、数名でもいらっしゃるということは、昔にはなかったなと思いますので、教員採用のときに、給食が食べられるかどうかの問診でもしていただくことが、今後は本当に必要なんです。これはどういう理由でそういうふうになされてきたのか、伺います。それから、預かり保育の実績、予算の積算の根拠について伺います。","respondent":"高橋幼保一元担当課長","answer":"日々の実績におきましては、平成１９年度におきましては、各園におきましてまちまちですが、１日平均約、多いところでは１３名から、少ないところにおきましては３名という状況で、昨年と比べると倍に増えているです。","voiceIndex":351,"id":"exchange-157"},{"speaker":"川西委員","kind":"質問","question":"中学生の夏季施設のことですけれども、毎年毎年激変しているように思われます。これは、このまま続けていけるのか、どうなのかという瀬戸際の人数かなと思いますが、何校でこの人数なんでしょうか。","respondent":"古里学務課長","answer":"これは、その意味では、いわゆる林間学校など、移動教室などの指定をされた郊外授業から外れてございまして、各学校における任意の教育課程の編成の中で行われるものですので、現在、さまざまな事情の中で減っているです。","voiceIndex":353,"id":"exchange-158"},{"speaker":"川西委員","kind":"質問","question":"それと、教員の先生方の忙しさも加わっているんでしょうかね。これで質問を終わりますが、さっきすまいるスクールのことで予定していまして、質問をとりやめましたので、意見だけ述べておきたいと思います。それで、つい１０日ぐらい前のことなんですけれども、小学生２人と私が、夜の８時半ごろ、一緒に歩いていました。「さっき話していた人はだれですか」と私は子どもに聞いたんです。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":355,"id":"exchange-159"},{"speaker":"南委員","kind":"質問・要望","question":"３０７ページ、特別支援教育について伺います。ＮＰＯに委託をするということになっておりますけれども、今までの質疑でも同じような質問がありましたけれども、重複する部分も了解していただいて、答弁していただきたいと思います。どういう内容で委託をするのか。そして、それぞれの介助員、学習支援員等々の時間単価は幾らなのか。業務の委託料は全体で幾らなのか。とりあえずよろしくお願いします。","respondent":"古里学務課長、河野指導課長","answer":"そのような内容で進めてまいりたいと考えております。委託の全体の中身といたしましては、介助員の報償費、学習支援員の報償費、それから、保険料、事務経費等という内容です。単価については、現在のところ、介助員が１,０５０円、学習支援員は１,４００円を予定しております。","voiceIndex":357,"id":"exchange-160"},{"speaker":"南委員","kind":"質問・要望","question":"事項別明細書の金額とちょっと違うので、確認をしたいと思うんですけれども、介助員は時間単価１,１００円、学習支援員１,５００円、こういうふうに書いてあるんですけれども、その差は交通費なのか。よくわからないので、教えていただきたいと思います。そこで予定する介助員、学習支援員、そして、そこに通級される児童・生徒さんの人数は何人なのか、ここも教えてください。","respondent":"河野指導課長","answer":"通級につきましては、小学校が５校、中学校が１校の予定です。現在のところ、通級に進学する予定の生徒ですが、小学校につきましては７５名ですね。それから、通級のほうが６６名、中学校につきましては、固定級のほうが４３名、通級のほうが２１名を予定しております。","voiceIndex":360,"id":"exchange-161"},{"speaker":"南委員","kind":"質問","question":"通級についてですけれども、共働きをしているご家庭では、通級させたいけれども、送迎をしなくちゃいけないので、できなくて、通級をあきらめているという方もいらっしゃるやに聞いておりますけれども、私は、そういう状況があるとしたら残念だし、改善させなきゃいけないと思いますので、その辺の状況をつかむ必要があると思うんですけれども、その辺の見解を伺います。","respondent":"河野指導課長","answer":"介助員等のいわゆる勤務時間の関係ですが、私どもは、勤務していただいた時間単位ということでお支払いをする予定です。","voiceIndex":362,"id":"exchange-162"},{"speaker":"南委員","kind":"質問","question":"それはどういうことかというと、教育委員会が提出された資料によりますと、これは港区に次いで２番目だと。そなんことをやっている時間がないという場合は、どうしても担任の先生と直接の会話をして、指導をやりとりしていかなきゃいけないと思っているんですけれども、先ほどの質疑の中での答弁は、現場で話し合うことは可能だという答弁をしているんですけれども、これで本当にいいんですか。","respondent":"古里学務課長","answer":"緊急時の対応につきましては、委託契約の中においても、現場での緊急対応ということは許される範囲となっていますので、そうした緊急の場合は、当然のことながら、担当の教諭、あるいは学校長、あるいは校内委員会と話をして対応するということは当然のことですので、その点。","voiceIndex":364,"id":"exchange-163"},{"speaker":"南委員","kind":"質問","question":"差し支えないと判断しているという話ですけれども、会話はすることは当然あり得るでしょう。ないと、子どもさんに共通の対応ができないわけですから、かえって子どもに２次障害を与えちゃう。しかし、そのやりとりが指示・命令になっていったら、偽装請負になっちゃうんじゃないんですか。そのことを心配して聞いているんです。","respondent":"古里学務課長","answer":"まだスタートしてない事業ですから、スタートしていく中で、法制度の内容をしっかり見定めながら、必要な改革、改善、そして何よりも大事なのは、発達障害がある子どもたちができるだけ早く一つ一つの困難を乗り越えて。","voiceIndex":366,"id":"exchange-164"},{"speaker":"南委員","kind":"意見","question":"もう時間がないのであれですけれども、私はやっぱりこういう教育の内容に、しかも、いろんな方々の情報を共有することで成り立たなきゃいけない教育の場面に、こういうシステムを導入するというのはいかがなものかと、なじまないんじゃないかと思うんです。人間同士の信頼関係がベースの仕事ですので、ぜひぜひそういうふうにならないように、きちんとした体制を検討するべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":368,"id":"exchange-165"},{"speaker":"三上委員","kind":"確認","question":"私は３００ページ、事務局費の関連で、それから、３０３ページ、区教員採用事務費、それから、３２１ページなんでしょうか、学校改築推進経費、それから、ちょっと戻っちゃいますが、３１３ページ、３３３ページ、学校図書館運営費、図書館経費、それから、３１９ページの八潮地区小中一貫校、ちょっと内容がいろいろありますので、簡単に伺っていきたいと思います。もう既に取りましたと。簡単でいいです。","respondent":"長田教育次長、河野指導課長","answer":"指摘を受けました事項につきましては、早速３月５日の校長会等で周知いたしまして、すぐ是正するところは是正するというようなこととともに、今後二度とこういった指摘を受けないような形での指導を校長が中心となって行うよう。社会性等云々ということについては、長期休業期間等も含めて、そういう機会を積極的に設定してまいりたいと考えております。","voiceIndex":370,"id":"exchange-166"},{"speaker":"三上委員","kind":"質問・要望","question":"二度とこういうようなことで指摘が、３度、４度と指摘を受けるようなことのないようにお願いしたいと思います。小中一貫校に異動した場合にどうするのか。学校経営に関して、学校長はそれを持っていなくてもいいという、それは私は学校長としても、自分でも努力するんだというくらいのものがあって、学校経営をやっていってもらいたいなと、こういうふうに思いますけれども、いかがですか。","respondent":"河野指導課長","answer":"一貫校に勤務ですが、本会議等での答弁でもお答えいたしましたように、中学校の教員免許を有している者は、当該教科に関する小学校での教科指導については差し支えないという回答もいただいておりますし、品川区といたしましては。","voiceIndex":373,"id":"exchange-167"},{"speaker":"三上委員","kind":"質問・要望","question":"それはわかった上で言っているんです。だけれども、私が言っているのは、そういった事例を１つ示しながらも、そういった小中一貫教育をやるという意味での意気込みという、そういった１つの体制につくり上げていこうという、そういう人たちの共有する、そういう気持ちをもっと大事にして、そういったものを育てていってもらいたい。こういうことについてどうお考えになっていらっしゃるか、お伺いします。","respondent":"工藤品川図書館長","answer":"そういった中で整備を進めていきたいと思ってあります。朝の読書活動につきましても、今、小学校でも７割以上の学校が実施されているような状況です。引き続きこのような学校図書館の活性化と学校での読書活動を進めていきたいと考えています。","voiceIndex":375,"id":"exchange-168"},{"speaker":"三上委員","kind":"質問・要望","question":"それで、私は、恵庭市の図書館ともいろいろ情報交換させていただいた話の中から、小学校１年生の読書態度等についてということを平成１９年度にまとめています。それから、多くの児童が登校してすぐに学校図書館を訪れて本を借りていくとか、それから、これはちょっと注目すべきだなと思うのは、２年、３年生と比べて、学校図書館で本を借りる児童が多い。","respondent":"工藤品川図書館長","answer":"私どもも来年度からブックスタート事業を始めるです。やはり幼児のときからこのような形で本を手渡すという部分は重要なことと認識しています。","voiceIndex":377,"id":"exchange-169"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"いよいよ款別、最後でありますので、どうぞよろしくお願いします。３２９ページ、総合型地域スポーツクラブの設置は、これは渡辺委員が朝一番で質問して、最後のところの部分、答弁がというのがありましたので、もう１回聞きます。そこら辺のところが、多くなることが、あるのですか、ないんですか。別に考えるぐらいはお金がかからないわけですから。そこの点を教えていただきたいと思います。","respondent":"富田生涯学習課長、日下部企画財政課長、藤森小中一貫教育担当課長","answer":"特別展等々の機会をとらえまして、委員、ご提案ありましたように、さまざまな、例えば観光協会ですとか、商店街連合会ですとか、そういったところ。全庁公平に行っているです。スチューデント・シティの区長と区役所の内容については、どこがつくっているのかですけれども。","voiceIndex":380,"id":"exchange-170"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"歴史館はそれでいいです。登録したって、お金かけなきゃいいじゃないですか。だけど、ずっと２万４,０００円かけているのが、子どもたちにとって、質を落とさず、いいことなのかという検証ぐらいはどこかで１回してほしいなと。それが今言ったようなところの経常的で出るのを、それはお考えを聞かせてほしいなと。これはちょっと考えたほうがいいんじゃないのかなと思うんだけど、そこら辺の２つの答弁だけ。","respondent":"古里学務課長、藤森小中一貫教育担当課長","answer":"磐梯についても、もう数年続いてありますので、新たな教育の課程の中で新たな検討が必要かどうかということもあわせて伝えてまいりたいと思います。その中でも、今、委員のほうからご紹介いただきましたけれども、品川区役所のブースの仕事とほかの企業のブースの仕事の性格が違うだとか、仕事の量が違うだとか、そういうような声も出ておりまして、今後、区役所ブースの廃止を含めて。","voiceIndex":384,"id":"exchange-171"},{"speaker":"石田（秀）委員","kind":"意見","question":"私は、廃止しろというつもりで言ったんじゃなくて、ぜひ子どもたちに、区長もこういう仕事を一生懸命頑張っているよ、区の職員の人も、これだけ頑張っているよという内容にしてもらいたいなと思っているわけで、ただ、毎年２,０００人ぐらいそういう子どもが生まれるということは、やっぱり考えてほしいなと思っていますので、ぜひそこら辺の検討はよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":387,"id":"exchange-172"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=904#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":123974,"voices":388}}]);
